 (not exists(select 1 from expected_tables e full join tables t on t.full_name=e.name
  where e.name is null or t.oid is null or t.relkind<>'r')) as table_contract_ok,
 (not exists(select 1 from tables t join expected_tables e on e.name=t.full_name where
  pg_catalog.has_table_privilege('helpdesk_app',t.oid,'SELECT') is distinct from e.read
  or pg_catalog.has_table_privilege('helpdesk_app',t.oid,'INSERT') is distinct from e."insert"
  or pg_catalog.has_table_privilege('helpdesk_app',t.oid,'UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
  or pg_catalog.has_table_privilege('helpdesk_app',t.oid,'SELECT WITH GRANT OPTION,INSERT WITH GRANT OPTION,UPDATE WITH GRANT OPTION'))
  ) as table_privileges_ok,
 (not exists(select 1 from tables t join expected_tables e on e.name=t.full_name
  join pg_catalog.pg_attribute a on a.attrelid=t.oid and a.attnum>0 and not a.attisdropped where
  pg_catalog.has_column_privilege('helpdesk_app',t.oid,a.attnum,'SELECT') is distinct from e.read
  or pg_catalog.has_column_privilege('helpdesk_app',t.oid,a.attnum,'INSERT') is distinct from e."insert"
  or pg_catalog.has_column_privilege('helpdesk_app',t.oid,a.attnum,'UPDATE') is distinct from (a.attname=any(e.updates))
  or pg_catalog.has_column_privilege('helpdesk_app',t.oid,a.attnum,'REFERENCES,SELECT WITH GRANT OPTION,INSERT WITH GRANT OPTION,UPDATE WITH GRANT OPTION'))
  ) as column_privileges_ok,
 (not exists(select 1 from tables t cross join clients r where
   pg_catalog.has_table_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
   or pg_catalog.has_any_column_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,REFERENCES'))
  and not exists(select 1 from functions p cross join clients r where pg_catalog.has_function_privilege(r.oid,p.oid,'EXECUTE'))
  and not exists(select 1 from tables t cross join lateral pg_catalog.aclexplode(coalesce(t.relacl,pg_catalog.acldefault('r',t.relowner))) a where a.grantee=0)
  and not exists(select 1 from tables t join pg_catalog.pg_attribute c on c.attrelid=t.oid
   cross join lateral pg_catalog.aclexplode(c.attacl) a where a.grantee=0)) as client_object_privileges_ok,
 (not exists(select 1 from expected_functions e full join functions p on p.signature=e.signature
  where e.signature is null or p.oid is null or p.prokind<>'f' or p.prosecdef is distinct from e.definer)) as helper_contract_ok,
 (not exists(select 1 from functions p join expected_functions e on e.signature=p.signature
  where pg_catalog.has_function_privilege('helpdesk_app',p.oid,'EXECUTE') is distinct from e.execute
   or pg_catalog.has_function_privilege('helpdesk_app',p.oid,'EXECUTE WITH GRANT OPTION'))) as helper_privileges_ok,
 (not exists(select 1 from functions p where p.owner_name='helpdesk_app'
  or not coalesce(p.proconfig @> array['search_path=""'] or p.proconfig @> array['search_path='],false)
  or (p.prosecdef and not (p.rolsuper or p.rolbypassrls)))) as helper_settings_ok,
 (not exists(select 1 from expected_triggers e left join tables t on t.full_name=e."table"
  left join pg_catalog.pg_trigger g on g.tgrelid=t.oid and g.tgname=e.name
  left join functions p on p.oid=g.tgfoid where g.oid is null or g.tgenabled not in ('O','A')
   or g.tgisinternal or g.tgtype<>e.type or g.tgdeferrable is distinct from e.deferred
   or g.tginitdeferred is distinct from e.deferred or p.signature is distinct from e."function")
  and not exists(select 1 from pg_catalog.pg_trigger g join tables t on t.oid=g.tgrelid where g.tgenabled not in ('O','A'))) as trigger_contract_ok,
 (not exists(select 1 from expected_constraints e left join tables t on t.full_name=e."table"
  left join pg_catalog.pg_constraint c on c.conrelid=t.oid and c.conname=e.name
  where c.oid is null or c.contype::text<>e.type or not c.convalidated)
  and not exists(select 1 from pg_catalog.pg_constraint c join tables t on t.oid=c.conrelid where not c.convalidated)) as constraint_contract_ok,
 (not exists(select 1 from pg_catalog.pg_index i join tables t on t.oid=i.indrelid where not i.indisvalid or not i.indisready)
  and exists(select 1 from pg_catalog.pg_index i join pg_catalog.pg_class x on x.oid=i.indexrelid
   join tables t on t.oid=i.indrelid where t.full_name='helpdesk_core.ticket_events' and x.relname='assignment_event_version'
    and i.indisunique and i.indisvalid and i.indisready)
  and (select count(*) from pg_catalog.pg_index i join pg_catalog.pg_class x on x.oid=i.indexrelid
   join tables t on t.oid=i.indrelid where t.full_name='helpdesk_audit.write_effects'
    and x.relname in ('write_effect_revision','write_effect_source')
    and i.indisunique and i.indisvalid and i.indisready and i.indpred is not null)=2) as index_contract_ok,
 ((select count(*) from pg_catalog.pg_policy p join tables t on t.oid=p.polrelid)=(select count(*) from expected_policies)
  and not exists(select 1 from expected_policies e left join tables t on t.full_name=e."table"
   left join pg_catalog.pg_policy p on p.polrelid=t.oid and p.polname=e.name where p.oid is null
    or p.polpermissive is distinct from e.permissive or p.polcmd::text<>e.command
    or p.polroles is distinct from array[(select oid from app)]::oid[])) as policy_contract_ok,
 ((select count(*) from expected_roles)=2 and not exists(select 1 from expected_roles e left join pg_catalog.pg_roles r on r.rolname=e.name where r.oid is null
   or r.rolsuper or r.rolbypassrls or r.rolcreaterole or r.rolcreatedb or r.rolreplication or r.rolinherit
   or EXISTS(
 SELECT 1 FROM pg_catalog.pg_auth_members m WHERE m.member=r.oid
 OR (m.roleid=r.oid AND NOT ((m.member=(SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4))
 AND m.grantor=10 AND EXISTS(SELECT 1 FROM pg_catalog.pg_roles bootstrap WHERE bootstrap.oid=10 AND bootstrap.rolsuper)
 AND m.admin_option AND NOT m.inherit_option AND NOT m.set_option) IS TRUE)))
   or exists(select 1 from schemas n where n.nspowner=r.oid or pg_catalog.has_schema_privilege(r.oid,n.oid,'USAGE') is distinct from (n.nspname=any(e.schemas)) or pg_catalog.has_schema_privilege(r.oid,n.oid,'CREATE,USAGE WITH GRANT OPTION'))
   or exists(select 1 from tables t where t.relowner=r.oid or pg_catalog.has_table_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') or pg_catalog.has_any_column_privilege(r.oid,t.oid,'SELECT,INSERT,UPDATE,REFERENCES'))
   or exists(select 1 from functions p where p.proowner=r.oid or pg_catalog.has_function_privilege(r.oid,p.oid,'EXECUTE') is distinct from (p.signature=any(e.functions)) or pg_catalog.has_function_privilege(r.oid,p.oid,'EXECUTE WITH GRANT OPTION'))
 )) as reserved_roles_ok,
 ((SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4)) IS NOT NULL AND NOT EXISTS(
 SELECT 1 FROM pg_catalog.pg_default_acl d CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) a
 WHERE d.defaclrole=(SELECT owner.oid FROM pg_catalog.pg_roles owner
 WHERE owner.rolcreaterole AND (owner.rolsuper OR owner.rolbypassrls)
 AND owner.rolname NOT IN ('helpdesk_app','helpdesk_resource_publisher','helpdesk_notification_worker','helpdesk_maintenance','anon','authenticated','service_role')
 AND owner.oid=(SELECT n.nspowner FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')
 GROUP BY n.nspowner HAVING count(*)=4))
 AND (d.defaclnamespace=0 OR d.defaclnamespace IN (SELECT oid FROM pg_catalog.pg_namespace WHERE nspname IN ('helpdesk_auth','helpdesk_core','helpdesk_integration','helpdesk_audit')))
 AND a.grantee<>d.defaclrole AND NOT (a.grantee=0 AND d.defaclobjtype='f' AND a.privilege_type='EXECUTE'))) as owner_defaults_ok,
 (pg_catalog.current_setting('server_version_num')::integer between 170000 and 179999
  and pg_catalog.current_setting('row_security')='on'
  and pg_catalog.current_setting('session_replication_role')='origin') as execution_settings_ok) catalogue;
 IF checked.table_count IS DISTINCT FROM 67 OR checked.unsafe_tables IS DISTINCT FROM 0
 OR checked.public_schema_access IS DISTINCT FROM FALSE OR checked.client_schema_access IS DISTINCT FROM FALSE OR checked.public_helper_execute IS DISTINCT FROM FALSE
 OR checked.schema_contract_ok IS DISTINCT FROM TRUE
 OR checked.table_contract_ok IS DISTINCT FROM TRUE
 OR checked.table_privileges_ok IS DISTINCT FROM TRUE
 OR checked.column_privileges_ok IS DISTINCT FROM TRUE
 OR checked.client_object_privileges_ok IS DISTINCT FROM TRUE
 OR checked.helper_contract_ok IS DISTINCT FROM TRUE
 OR checked.helper_privileges_ok IS DISTINCT FROM TRUE
 OR checked.helper_settings_ok IS DISTINCT FROM TRUE
 OR checked.trigger_contract_ok IS DISTINCT FROM TRUE
 OR checked.constraint_contract_ok IS DISTINCT FROM TRUE
 OR checked.index_contract_ok IS DISTINCT FROM TRUE
 OR checked.policy_contract_ok IS DISTINCT FROM TRUE
 OR checked.execution_settings_ok IS DISTINCT FROM TRUE
 OR checked.reserved_roles_ok IS DISTINCT FROM TRUE
 OR checked.owner_defaults_ok IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Exact wave2 catalogue required' USING ERRCODE='HDE04';END IF;
END $wave2_base_catalogue$;

-- SOURCE hdn_notification_wave2_public.sql SHA256 8bb4b9cf9567040f9b4cc70c242414e309137a7888c7e51200ac3ea274ca2537
-- Exact intent shape from the immutable v024 validator; only the admitted kinds extend.
CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_valid_intent(i jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE k text;BEGIN
 IF NOT coalesce(helpdesk_auth.hdn_cfg_object(i,ARRAY['id','workspaceId','accountId','ticketId','eventId','recipientId','channelId','templateId','templateVersion','templateHash','kind','sourceVersion','resourceHash','protocol','invitationId','createdAt','expiresAt','idempotencyKey']),false) THEN RETURN false;END IF;
 FOREACH k IN ARRAY ARRAY['id','workspaceId','accountId','ticketId','eventId','recipientId'] LOOP IF jsonb_typeof(i->k) IS DISTINCT FROM 'string' OR i->>k !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' THEN RETURN false;END IF;END LOOP;
 FOREACH k IN ARRAY ARRAY['channelId','templateId','templateHash','kind','resourceHash','protocol','createdAt','expiresAt','idempotencyKey'] LOOP IF jsonb_typeof(i->k) IS DISTINCT FROM 'string' THEN RETURN false;END IF;END LOOP;
 IF jsonb_typeof(i->'templateVersion') IS DISTINCT FROM 'number' OR jsonb_typeof(i->'sourceVersion') IS DISTINCT FROM 'number' THEN RETURN false;END IF;
 IF i->>'channelId'<>'resend' OR i->>'templateId' !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$'
 OR i->>'kind' NOT IN ('support.created','support.devolutiva','support.customer_reply','support.form_revised','support.resolved','support.approval_requested','support.approval_granted','support.approval_rejected','support.transition','support.reply','support.handoff','support.closed','support.reopened','support.cancelled','internal.queue_created','internal.assignment_changed')
 OR i->>'protocol' !~ '^CG-[1-9][0-9]{4,17}$' OR i->>'templateHash' !~ '^[a-f0-9]{64}$' OR i->>'resourceHash' !~ '^[a-f0-9]{64}$'
 OR i->>'templateVersion' !~ '^[1-9][0-9]{0,15}$' OR (i->>'templateVersion')::numeric>9007199254740991 OR i->>'sourceVersion' !~ '^[1-9][0-9]{0,15}$' OR (i->>'sourceVersion')::numeric>9007199254740991
 OR (i->>'kind'='support.approval_requested')<>(i->'invitationId'<>'null'::jsonb)
 OR i->'invitationId'<>'null'::jsonb AND i->>'invitationId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
 OR helpdesk_auth.hdn_notification_stamp(i->>'expiresAt')<=helpdesk_auth.hdn_notification_stamp(i->>'createdAt') THEN RETURN false;END IF;
 RETURN coalesce(i->>'idempotencyKey'=helpdesk_auth.hdni_digest(jsonb_build_array('helpdesk-notification-v1',i->'workspaceId',i->'eventId',i->'recipientId',i->'channelId',i->'templateId',i->'templateVersion')),false);
EXCEPTION WHEN OTHERS THEN RETURN false;END$$;

-- Wave2 public semantics. Compose only inside the reviewed additive upgrade.
-- Existing source qualification remains intact; no historical plan is rewritten.
ALTER FUNCTION helpdesk_auth.hdn_notification_facts(uuid) RENAME TO hdn_notification_facts_v024;
CREATE FUNCTION helpdesk_auth.hdn_notification_facts(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE facts jsonb;source jsonb;legacy jsonb;prior jsonb;c helpdesk_audit.hdn_workflow_commits%rowtype;eligible boolean:=true;kind text;BEGIN
 facts:=helpdesk_auth.hdn_notification_facts_v024(target);legacy:=facts->'source';source:=legacy;
 IF legacy->>'type'<>'support.created' THEN
  SELECT * INTO STRICT c FROM helpdesk_audit.hdn_workflow_commits WHERE event_id=target FOR SHARE;
  kind:=CASE c.command->>'action'
   WHEN 'reply' THEN 'support.reply' WHEN 'request_customer' THEN 'support.devolutiva'
   WHEN 'start' THEN 'support.transition' WHEN 'triage' THEN 'support.transition'
   WHEN 'handoff' THEN 'support.handoff' WHEN 'customer_reply' THEN 'support.customer_reply'
   WHEN 'resolve' THEN 'support.resolved' WHEN 'close' THEN 'support.closed'
   WHEN 'reopen' THEN 'support.reopened' WHEN 'cancel' THEN 'support.cancelled'
   ELSE legacy->>'type' END;
  eligible:=CASE kind
   WHEN 'support.transition' THEN c.command->>'action'='start' AND c.from_status IN ('new','triage') AND c.to_status='open' AND c.public_event->>'actorKind'='human_agent'
   WHEN 'support.reply' THEN c.from_status IN ('triage','open','waiting_customer','waiting_internal','waiting_third_party') AND c.to_status=c.from_status AND c.public_event->>'actorKind'='human_agent'
   WHEN 'support.devolutiva' THEN c.from_status IN ('triage','open') AND c.to_status='waiting_customer' AND c.public_event->>'actorKind'='human_agent'
   WHEN 'support.handoff' THEN c.from_status='open' AND c.to_status IN ('waiting_internal','waiting_third_party') AND c.public_event->>'actorKind'='human_agent'
   WHEN 'support.customer_reply' THEN c.public_event->>'actorKind'='customer' AND c.from_status IN ('open','waiting_customer','waiting_internal','waiting_third_party') AND (c.to_status=c.from_status OR c.from_status='waiting_customer' AND c.to_status='open')
   WHEN 'support.resolved' THEN c.from_status IN ('triage','open','waiting_customer','waiting_internal','waiting_third_party') AND c.to_status='resolved' AND c.public_event->>'actorKind'='human_agent'
   WHEN 'support.closed' THEN c.from_status='resolved' AND c.to_status='closed' AND c.public_event->>'actorKind' IN ('customer','human_agent')
   WHEN 'support.reopened' THEN c.from_status IN ('resolved','closed') AND c.to_status='open' AND c.public_event->>'actorKind' IN ('customer','human_agent')
   WHEN 'support.cancelled' THEN c.from_status IN ('new','triage','open','waiting_customer','waiting_internal','waiting_third_party') AND c.to_status='cancelled' AND c.public_event->>'actorKind'='human_agent'
   ELSE false END;
  source:=jsonb_set(source,'{type}',to_jsonb(kind),false);
 END IF;
 SELECT document INTO prior FROM helpdesk_integration.hdn_notification_plans WHERE event_id=target;
 IF prior IS NOT NULL THEN
  IF prior->>'sourceHash'=helpdesk_auth.hdni_digest(legacy) THEN source:=legacy;
  ELSIF prior->>'sourceHash'<>helpdesk_auth.hdni_digest(source) THEN RAISE EXCEPTION 'Historical source mismatch' USING ERRCODE='HDN05';END IF;
 END IF;
 RETURN jsonb_set(facts,'{source}',source,false)||jsonb_build_object('wave2Eligible',coalesce(eligible,false));
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Unqualified wave2 source' USING ERRCODE='HDN05';END$$;
DO $private$
DECLARE role_name text;BEGIN
 REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_facts(uuid) FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN
   EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_facts(uuid) FROM %I',role_name);
  END IF;
 END LOOP;
END $private$;

ALTER TABLE helpdesk_integration.hdn_notification_routes ADD COLUMN effective_after timestamptz;
ALTER TABLE helpdesk_integration.hdn_notification_routes ADD CONSTRAINT hdn_notification_routes_effective_after_check CHECK(effective_after IS NULL OR isfinite(effective_after));
ALTER TABLE helpdesk_integration.hdn_notification_routes DROP CONSTRAINT hdn_notification_routes_check;
ALTER TABLE helpdesk_integration.hdn_notification_routes ADD CONSTRAINT hdn_notification_routes_check CHECK(
 (audience='none' AND template_id IS NULL AND template_version IS NULL)
 OR (audience='requester' AND kind IN ('support.created','support.devolutiva','support.resolved','support.transition','support.reply','support.handoff','support.closed','support.reopened','support.cancelled') AND template_id IS NOT NULL AND template_version IS NOT NULL));

CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_routing(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE facts jsonb;src jsonb;route helpdesk_integration.hdn_notification_routes%rowtype;t helpdesk_integration.hdn_notification_templates%rowtype;recipients jsonb:='[]';BEGIN PERFORM helpdesk_auth.hdn_notification_worker();facts:=helpdesk_auth.hdn_notification_facts(target);src:=facts->'source';
 SELECT * INTO STRICT route FROM helpdesk_integration.hdn_notification_routes WHERE workspace_id=(src->>'workspaceId')::uuid AND kind=src->>'type' ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF route.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Routing expired' USING ERRCODE='HDN05';END IF;
 IF route.audience='requester' AND facts->'wave2Eligible'='true'::jsonb
  AND (route.effective_after IS NULL OR helpdesk_auth.hdn_notification_stamp(src->>'createdAt')>=route.effective_after) THEN
  SELECT * INTO STRICT t FROM helpdesk_integration.hdn_notification_templates WHERE id=route.template_id AND version=route.template_version FOR SHARE;
  IF t.kind<>route.kind THEN RAISE EXCEPTION 'Template kind mismatch' USING ERRCODE='HDN05';END IF;
  recipients:=jsonb_build_array(jsonb_build_object('principalId',facts->'requesterId','channelId','resend','templateId',t.id,'templateVersion',t.version,'templateHash',t.sha256));
 END IF;
 RETURN jsonb_build_object('eventId',target,'workspaceId',src->'workspaceId','accountId',src->'accountId','ticketId',src->'ticketId','sourceVersion',src->'version','kind',src->'type','protocol',facts->'protocol','resourceHash',facts->'resourceHash','revision','route-'||route.revision::text,'status','published','expiresAt',helpdesk_auth.hdn_workflow_iso(route.expires_at),'recipients',recipients);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Published routing required' USING ERRCODE='HDN05';END$$;


-- SOURCE hdn_notification_wave2_internal.sql SHA256 04a31d13040ad372e651531dfd3e3b007f65a99ef9773e13ca0eb504479242ae
-- Additive private projection. No historical event is copied or backfilled.
CREATE FUNCTION helpdesk_auth.hdn_notification_valid_members(m uuid[],maximum integer) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT coalesce(maximum BETWEEN 1 AND 10 AND cardinality(m) BETWEEN 1 AND maximum
  AND array_ndims(m)=1 AND array_lower(m,1)=1 AND array_position(m,NULL) IS NULL
  AND (SELECT count(DISTINCT x) FROM unnest(m) x)=cardinality(m),false)
$$;
CREATE TABLE helpdesk_integration.hdn_notification_queue_rosters(
 workspace_id uuid NOT NULL,account_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),
 member_ids uuid[] NOT NULL,max_recipients integer NOT NULL,expires_at timestamptz NOT NULL,
 request_id uuid NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 3 AND 1000),
 recorded_by name NOT NULL DEFAULT session_user,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(workspace_id,account_id,revision),UNIQUE(workspace_id,request_id),
 FOREIGN KEY(workspace_id,account_id) REFERENCES helpdesk_core.accounts(workspace_id,id),
 CHECK(helpdesk_auth.hdn_notification_valid_members(member_ids,max_recipients)),
 CHECK(isfinite(expires_at) AND isfinite(recorded_at) AND expires_at>recorded_at));
CREATE TABLE helpdesk_integration.hdn_notification_private_sources(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,account_id uuid NOT NULL,ticket_id uuid NOT NULL,
 parent_event_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('internal.queue_created','internal.assignment_changed','support.customer_reply')),
 source_version integer NOT NULL CHECK(source_version>0),assigned_principal_id uuid REFERENCES helpdesk_auth.principals(id),
 request_id text NOT NULL,created_at timestamptz NOT NULL CHECK(isfinite(created_at)),
 UNIQUE(workspace_id,parent_event_id,kind),
 FOREIGN KEY(workspace_id,account_id,ticket_id) REFERENCES helpdesk_core.tickets(workspace_id,account_id,id),
 FOREIGN KEY(workspace_id,parent_event_id) REFERENCES helpdesk_core.ticket_events(workspace_id,id),
 CHECK((kind='internal.queue_created' AND source_version=1 AND assigned_principal_id IS NULL)
 OR (kind='internal.assignment_changed' AND source_version>1 AND assigned_principal_id IS NOT NULL)
 OR (kind='support.customer_reply' AND source_version>1)));
CREATE INDEX hdn_notification_private_sources_pending ON helpdesk_integration.hdn_notification_private_sources(created_at,id);
CREATE TRIGGER hdn_notification_roster_immutable BEFORE UPDATE OR DELETE ON helpdesk_integration.hdn_notification_queue_rosters FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdn_notification_immutable();
CREATE TRIGGER hdn_notification_private_source_immutable BEFORE UPDATE OR DELETE ON helpdesk_integration.hdn_notification_private_sources FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdn_notification_immutable();

-- Deferred projection binds the source to the real request transaction. The
-- existing receipt/write-effect guards remain responsible for complete commits.
CREATE FUNCTION helpdesk_auth.hdn_notification_project_internal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c helpdesk_audit.hdn_workflow_commits%rowtype;r helpdesk_audit.hdni_receipts%rowtype;
 f helpdesk_audit.write_effects%rowtype;t helpdesk_core.tickets%rowtype;o helpdesk_integration.outbox_events%rowtype;
 kind text;version integer;person uuid;correlation text;source_id uuid:=gen_random_uuid();BEGIN
 IF session_user<>'helpdesk_app' OR current_setting('role') NOT IN ('none','helpdesk_app') THEN RETURN NULL;END IF;
 SELECT * INTO f FROM helpdesk_audit.write_effects WHERE (workspace_id,account_id,ticket_id,event_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id);
 IF NOT FOUND OR f.transaction_id<>pg_current_xact_id() OR NOT f.applied OR f.actor_id<>NEW.actor_id OR f.kind<>NEW.type THEN RETURN NULL;END IF;
 IF NEW.type='ticket.created' THEN
  SELECT * INTO r FROM helpdesk_audit.hdni_receipts WHERE (workspace_id,account_id,ticket_id,event_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id);
  IF NOT FOUND OR r.transaction_id<>pg_current_xact_id() OR r.actor_id<>NEW.actor_id OR f.ticket_version<>1 OR NOT NEW.customer_visible THEN RETURN NULL;END IF;
  SELECT * INTO STRICT o FROM helpdesk_integration.outbox_events WHERE (workspace_id,account_id,ticket_id,id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id);
  kind:='internal.queue_created';version:=1;person:=NULL;correlation:=o.request_id;
 ELSE
  SELECT * INTO c FROM helpdesk_audit.hdn_workflow_commits WHERE (workspace_id,account_id,ticket_id,event_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id);
  IF NOT FOUND OR c.transaction_id<>pg_current_xact_id() OR c.actor_id<>NEW.actor_id OR c.core_type<>NEW.type OR c.at<>NEW.created_at OR c.to_version<>f.ticket_version THEN RETURN NULL;END IF;
  IF c.command->>'action'='transfer' AND NEW.type='ticket.assignment_changed' AND NOT NEW.customer_visible THEN
   kind:='internal.assignment_changed';person:=(c.command->>'targetPrincipalId')::uuid;
  ELSIF c.command->>'action'='customer_reply' AND c.public_event->>'actorKind'='customer' AND NEW.customer_visible THEN
   kind:='support.customer_reply';source_id:=NEW.id;
   SELECT * INTO STRICT t FROM helpdesk_core.tickets WHERE (workspace_id,account_id,id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id) FOR SHARE;
   IF t.version<>c.to_version THEN RAISE EXCEPTION 'Customer return assignment snapshot changed' USING ERRCODE='HDN05';END IF;
   person:=t.assigned_to;
  ELSE RETURN NULL;END IF;
  version:=c.to_version;correlation:=c.audit->>'requestId';
 END IF;
 INSERT INTO helpdesk_integration.hdn_notification_private_sources(id,workspace_id,account_id,ticket_id,parent_event_id,kind,source_version,assigned_principal_id,request_id,created_at)
 VALUES(source_id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,kind,version,person,correlation,NEW.created_at);
 RETURN NULL;
END$$;
CREATE CONSTRAINT TRIGGER hdn_notification_project_internal AFTER INSERT ON helpdesk_core.ticket_events
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdn_notification_project_internal();

ALTER FUNCTION helpdesk_auth.hdn_notification_facts(uuid) RENAME TO hdn_notification_facts_wave2_public;
CREATE FUNCTION helpdesk_auth.hdn_notification_facts(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE p helpdesk_integration.hdn_notification_private_sources%rowtype;root helpdesk_audit.hdni_receipts%rowtype;
 e helpdesk_core.ticket_events%rowtype;f helpdesk_audit.write_effects%rowtype;c helpdesk_audit.hdn_workflow_commits%rowtype;
 facts jsonb;source jsonb;prior jsonb;BEGIN
 SELECT * INTO p FROM helpdesk_integration.hdn_notification_private_sources WHERE id=target FOR SHARE;
 IF NOT FOUND THEN RETURN helpdesk_auth.hdn_notification_facts_wave2_public(target);END IF;
 SELECT * INTO STRICT root FROM helpdesk_audit.hdni_receipts WHERE (workspace_id,account_id,ticket_id)=(p.workspace_id,p.account_id,p.ticket_id) FOR SHARE;
 facts:=helpdesk_auth.hdn_notification_facts_v024(root.event_id);
 IF facts->'source'->>'type'<>'support.created' THEN RAISE EXCEPTION 'Private root source mismatch' USING ERRCODE='HDN05';END IF;
 SELECT * INTO STRICT e FROM helpdesk_core.ticket_events WHERE (workspace_id,account_id,ticket_id,id)=(p.workspace_id,p.account_id,p.ticket_id,p.parent_event_id) FOR SHARE;
 SELECT * INTO STRICT f FROM helpdesk_audit.write_effects WHERE (workspace_id,account_id,ticket_id,event_id)=(p.workspace_id,p.account_id,p.ticket_id,p.parent_event_id) FOR SHARE;
 IF NOT f.applied OR f.actor_id<>e.actor_id OR f.kind<>e.type OR f.ticket_version<>p.source_version OR e.created_at<>p.created_at
 OR (e.data-CASE WHEN e.type IN ('ticket.status_changed','ticket.assignment_changed') THEN 'reason' ELSE '__absent__' END)<>f.expected_data THEN RAISE EXCEPTION 'Private parent mismatch' USING ERRCODE='HDN05';END IF;
 IF p.kind='internal.queue_created' THEN
  IF p.parent_event_id<>root.event_id OR e.type<>'ticket.created' OR NOT e.customer_visible OR f.transaction_id<>root.transaction_id OR p.request_id<>facts->'source'->>'requestId' THEN RAISE EXCEPTION 'Private opening mismatch' USING ERRCODE='HDN05';END IF;
 ELSE
  SELECT * INTO STRICT c FROM helpdesk_audit.hdn_workflow_commits WHERE (workspace_id,account_id,ticket_id,event_id)=(p.workspace_id,p.account_id,p.ticket_id,p.parent_event_id) FOR SHARE;
  IF c.transaction_id<>f.transaction_id OR c.actor_id<>e.actor_id OR c.core_type<>e.type OR c.to_version<>p.source_version OR c.at<>p.created_at OR c.audit->>'requestId'<>p.request_id
  OR p.kind='internal.assignment_changed' AND (c.command->>'action'<>'transfer' OR e.type<>'ticket.assignment_changed' OR e.customer_visible OR c.command->>'targetPrincipalId' IS DISTINCT FROM p.assigned_principal_id::text)
  OR p.kind='support.customer_reply' AND (c.command->>'action'<>'customer_reply' OR c.public_event->>'actorKind'<>'customer' OR NOT e.customer_visible) THEN RAISE EXCEPTION 'Private workflow mismatch' USING ERRCODE='HDN05';END IF;
  IF p.kind='support.customer_reply' THEN PERFORM helpdesk_auth.hdn_notification_facts_wave2_public(p.parent_event_id);END IF;
 END IF;
 source:=jsonb_build_object('id',p.id,'workspaceId',p.workspace_id,'accountId',p.account_id,'ticketId',p.ticket_id,'type',p.kind,'version',p.source_version,'requestId',p.request_id,'createdAt',helpdesk_auth.hdn_workflow_iso(p.created_at));
 SELECT document INTO prior FROM helpdesk_integration.hdn_notification_plans WHERE event_id=target;
 IF prior IS NOT NULL AND prior->>'sourceHash'<>helpdesk_auth.hdni_digest(source) THEN RAISE EXCEPTION 'Private historical source mismatch' USING ERRCODE='HDN05';END IF;
 RETURN jsonb_set(facts,'{source}',source,false)||jsonb_build_object('wave2Eligible',true,'sourceAssigneeId',p.assigned_principal_id,'parentEventId',p.parent_event_id);
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Unqualified private source' USING ERRCODE='HDN05';END$$;
DO $private$
DECLARE obj text;role_name text;BEGIN
 FOREACH obj IN ARRAY ARRAY['helpdesk_integration.hdn_notification_queue_rosters','helpdesk_integration.hdn_notification_private_sources'] LOOP
  EXECUTE 'ALTER TABLE '||obj||' ENABLE ROW LEVEL SECURITY';EXECUTE 'ALTER TABLE '||obj||' FORCE ROW LEVEL SECURITY';
  EXECUTE 'REVOKE ALL ON TABLE '||obj||' FROM PUBLIC';
  FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
   IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON TABLE %s FROM %I',obj,role_name);END IF;
  END LOOP;
 END LOOP;
 REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_valid_members(uuid[],integer) FROM PUBLIC;
 REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_project_internal(),helpdesk_auth.hdn_notification_facts(uuid) FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_valid_members(uuid[],integer) FROM %I',role_name);END IF;
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN
   EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_project_internal(),helpdesk_auth.hdn_notification_facts(uuid) FROM %I',role_name);
  END IF;
 END LOOP;
END $private$;


-- SOURCE hdn_notification_wave2_audiences.sql SHA256 57c6d4da319ee5829b42fca29348c78e543d6662d2ba058d9819db97f42dcf93
-- Additive routing data, initially empty. No implicit recipient or role audience.
ALTER TABLE helpdesk_integration.hdn_notification_routes ADD COLUMN recipient_ids uuid[];
ALTER TABLE helpdesk_integration.hdn_notification_routes ADD CONSTRAINT hdn_notification_routes_cohort_check CHECK(
 (recipient_ids IS NULL OR helpdesk_auth.hdn_notification_valid_members(recipient_ids,10))
 AND (audience='none' OR kind IN ('support.created','support.devolutiva','support.resolved') OR recipient_ids IS NOT NULL AND effective_after IS NOT NULL));
ALTER TABLE helpdesk_integration.hdn_notification_routes DROP CONSTRAINT hdn_notification_routes_audience_check;
ALTER TABLE helpdesk_integration.hdn_notification_routes ADD CONSTRAINT hdn_notification_routes_audience_check CHECK(audience IN ('none','requester','queue','assignee','customer_return','approver'));
ALTER TABLE helpdesk_integration.hdn_notification_routes DROP CONSTRAINT hdn_notification_routes_check;
ALTER TABLE helpdesk_integration.hdn_notification_routes ADD CONSTRAINT hdn_notification_routes_check CHECK(
 (audience='none' AND template_id IS NULL AND template_version IS NULL)
 OR template_id IS NOT NULL AND template_version IS NOT NULL AND (
  audience='requester' AND kind IN ('support.created','support.devolutiva','support.resolved','support.transition','support.reply','support.handoff','support.closed','support.reopened','support.cancelled','support.form_revised','support.approval_granted','support.approval_rejected')
  OR audience='queue' AND kind='internal.queue_created' OR audience='assignee' AND kind='internal.assignment_changed'
  OR audience='customer_return' AND kind='support.customer_reply' OR audience='approver' AND kind='support.approval_requested'));

-- Current authority for one explicit internal candidate, never contact lookup.
-- This wave qualifies the persisted local Consulte GEO source. No external API
-- decision or generic account title is substituted when that source is absent.
CREATE FUNCTION helpdesk_auth.hdn_notification_internal_person(target uuid,person uuid) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE facts jsonb;src jsonb;w uuid;a uuid;ticket uuid;t helpdesk_core.tickets%rowtype;
 r helpdesk_auth.cg_local_registries%rowtype;l helpdesk_auth.cg_local_accounts%rowtype;
 p helpdesk_auth.cg_local_permissions%rowtype;s helpdesk_core.cg_ticket_resource_sets%rowtype;
 b helpdesk_auth.cg_resource_bindings%rowtype;connection helpdesk_auth.cg_resource_connections%rowtype;
 roster helpdesk_integration.hdn_notification_queue_rosters%rowtype;ref record;is_queue boolean;BEGIN
 facts:=helpdesk_auth.hdn_notification_facts(target);src:=facts->'source';
 IF src->>'type' NOT IN ('internal.queue_created','internal.assignment_changed','support.customer_reply') THEN RETURN false;END IF;
 w:=(src->>'workspaceId')::uuid;a:=(src->>'accountId')::uuid;ticket:=(src->>'ticketId')::uuid;
 SELECT * INTO STRICT t FROM helpdesk_core.tickets WHERE (workspace_id,account_id,id)=(w,a,ticket) FOR SHARE;
 IF t.status IN ('resolved','closed','cancelled') OR EXISTS(SELECT 1 FROM helpdesk_core.ticket_events e WHERE (e.workspace_id,e.account_id,e.ticket_id)=(w,a,ticket) AND e.type='ticket.assignment_changed' AND (e.data->>'version')::integer>(src->>'version')::integer) THEN RETURN false;END IF;
 is_queue:=src->>'type'='internal.queue_created' OR src->>'type'='support.customer_reply' AND facts->'sourceAssigneeId'='null'::jsonb;
 IF is_queue THEN
  IF t.assigned_to IS NOT NULL THEN RETURN false;END IF;
  SELECT * INTO roster FROM helpdesk_integration.hdn_notification_queue_rosters WHERE workspace_id=w AND account_id=a ORDER BY revision DESC LIMIT 1 FOR SHARE;
  IF NOT FOUND OR roster.expires_at<=clock_timestamp() OR NOT person=ANY(roster.member_ids) THEN RETURN false;END IF;
 ELSE
  IF person::text IS DISTINCT FROM facts->>'sourceAssigneeId' OR t.assigned_to IS DISTINCT FROM person THEN RETURN false;END IF;
 END IF;
 IF src->>'type'='support.customer_reply' AND person::text=facts->>'requesterId' THEN RETURN false;END IF;
 SELECT * INTO r FROM helpdesk_auth.cg_local_registries WHERE workspace_id=w FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Qualified local internal source required' USING ERRCODE='HDN06';END IF;
 SELECT * INTO l FROM helpdesk_auth.cg_local_accounts WHERE workspace_id=w AND account_id=a FOR SHARE;
 IF NOT FOUND OR NOT l.active THEN RETURN false;END IF;
 IF l.registry_revision<>r.revision OR l.product_instance_id<>t.product_instance_id OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.cg_local_receipts receipt WHERE receipt.workspace_id=w AND receipt.registry_revision=r.revision AND receipt.decision_hash=r.decision_hash AND receipt.receipt->>'decisionHash'=r.decision_hash AND receipt.receipt->'revision'=to_jsonb(r.revision) AND receipt.receipt->'sourceManifest'=helpdesk_auth.cg_local_manifest()) THEN RAISE EXCEPTION 'Current local internal receipt required' USING ERRCODE='HDN06';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('helpdesk-human-scopes:'||w::text||':'||person::text,0));
 PERFORM 1 FROM helpdesk_auth.principals WHERE id=person AND kind='human' AND active FOR SHARE;IF NOT FOUND THEN RETURN false;END IF;
 IF NOT ARRAY['tickets:read','tickets:write']<@helpdesk_auth.human_scopes(w,person) THEN RETURN false;END IF;
 PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE workspace_id=w AND principal_id=person AND active AND role='admin' FOR SHARE;
 IF NOT FOUND THEN PERFORM 1 FROM helpdesk_auth.account_grants WHERE workspace_id=w AND account_id=a AND principal_id=person AND active AND role='agent' FOR SHARE;IF NOT FOUND THEN RETURN false;END IF;END IF;
 SELECT * INTO p FROM helpdesk_auth.cg_local_permissions WHERE workspace_id=w AND account_id=a AND principal_id=person AND operation='tickets.write' FOR SHARE;
 IF NOT FOUND OR NOT p.active THEN RETURN false;END IF;
 IF p.registry_revision<>r.revision THEN RAISE EXCEPTION 'Current internal write decision required' USING ERRCODE='HDN06';END IF;
 SELECT * INTO STRICT s FROM helpdesk_core.cg_ticket_resource_sets WHERE (workspace_id,account_id,ticket_id)=(w,a,ticket) AND sealed FOR SHARE;
 SELECT * INTO b FROM helpdesk_auth.cg_resource_bindings WHERE (workspace_id,account_id,id)=(w,a,s.binding_id) FOR SHARE;
 IF NOT FOUND OR NOT b.active THEN RETURN false;END IF;
 SELECT * INTO connection FROM helpdesk_auth.cg_resource_connections WHERE (workspace_id,id)=(w,b.connection_id) FOR SHARE;
 IF NOT FOUND OR NOT connection.active THEN RETURN false;END IF;
 IF l.binding_id<>s.binding_id OR l.connection_id<>connection.id OR b.tenant_id<>l.tenant_id OR connection.product_instance_id<>t.product_instance_id THEN RAISE EXCEPTION 'Internal namespace mismatch' USING ERRCODE='HDN06';END IF;
 IF (SELECT count(*) FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,ticket))<>s.expected_count THEN RAISE EXCEPTION 'Incomplete sealed internal resources' USING ERRCODE='HDN06';END IF;
 FOR ref IN SELECT x.resource_type,x.resource_id FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,ticket) ORDER BY x.resource_type,x.resource_id FOR SHARE LOOP
  IF ref.resource_type<>'work' OR NOT ref.resource_id=ANY(p.work_ids) THEN RETURN false;END IF;
  PERFORM 1 FROM helpdesk_auth.cg_local_works x WHERE x.workspace_id=w AND x.account_id=a AND x.id=ref.resource_id AND x.active AND x.registry_revision=r.revision FOR SHARE;
  IF NOT FOUND THEN RETURN false;END IF;
 END LOOP;RETURN true;
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Internal authority unavailable' USING ERRCODE='HDN06';END$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_sources(bound integer) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE row record;facts jsonb;src jsonb;ids jsonb:='[]';p jsonb;remaining integer;BEGIN
 PERFORM helpdesk_auth.hdn_notification_worker();IF bound NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'Bound required' USING ERRCODE='HDN02';END IF;
 FOR row IN SELECT x.id FROM helpdesk_integration.hdn_notification_private_sources x WHERE NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_plans planned WHERE planned.event_id=x.id) ORDER BY x.created_at,x.id LIMIT bound FOR UPDATE OF x SKIP LOCKED LOOP
  PERFORM helpdesk_auth.hdn_notification_facts(row.id);ids:=ids||jsonb_build_array(row.id);
 END LOOP;
 remaining:=bound-jsonb_array_length(ids);
 FOR row IN SELECT o.id FROM helpdesk_integration.outbox_events o WHERE NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_private_sources x WHERE x.id=o.id) AND NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_plans planned WHERE planned.event_id=o.id) AND EXISTS(SELECT 1 FROM helpdesk_core.hdni_snapshots s WHERE (s.workspace_id,s.account_id,s.ticket_id)=(o.workspace_id,o.account_id,o.ticket_id)) ORDER BY o.created_at,o.id LIMIT remaining FOR UPDATE OF o SKIP LOCKED LOOP
  facts:=helpdesk_auth.hdn_notification_facts(row.id);src:=facts->'source';
  IF src->>'type' NOT IN ('support.created','support.devolutiva','support.customer_reply','support.form_revised','support.resolved','support.approval_requested','support.approval_granted','support.approval_rejected','support.transition','support.reply','support.handoff','support.closed','support.reopened','support.cancelled','internal.queue_created','internal.assignment_changed') THEN
   p:=jsonb_build_object('schema',1,'eventId',row.id,'sourceHash',helpdesk_auth.hdni_digest(src),'sourceVersion',src->'version','routingRevision','unhandled-v1','plannedAt',helpdesk_auth.hdn_workflow_iso(clock_timestamp()),'state','no_recipients','intentIds','[]'::jsonb);
   INSERT INTO helpdesk_integration.hdn_notification_plans VALUES(row.id,(src->>'workspaceId')::uuid,(src->>'accountId')::uuid,(src->>'ticketId')::uuid,p);
  ELSE ids:=ids||jsonb_build_array(row.id);END IF;
 END LOOP;RETURN ids;
END$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_routing(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE facts jsonb;src jsonb;route helpdesk_integration.hdn_notification_routes%rowtype;t helpdesk_integration.hdn_notification_templates%rowtype;
 roster helpdesk_integration.hdn_notification_queue_rosters%rowtype;people uuid[]:='{}';person uuid;recipients jsonb:='[]';BEGIN
 PERFORM helpdesk_auth.hdn_notification_worker();facts:=helpdesk_auth.hdn_notification_facts(target);src:=facts->'source';
 SELECT * INTO STRICT route FROM helpdesk_integration.hdn_notification_routes WHERE workspace_id=(src->>'workspaceId')::uuid AND kind=src->>'type' ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF route.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Routing expired' USING ERRCODE='HDN05';END IF;
 IF route.audience<>'none' AND facts->'wave2Eligible'='true'::jsonb AND (route.effective_after IS NULL OR helpdesk_auth.hdn_notification_stamp(src->>'createdAt')>=route.effective_after) THEN
  SELECT * INTO STRICT t FROM helpdesk_integration.hdn_notification_templates WHERE id=route.template_id AND version=route.template_version FOR SHARE;
  IF t.kind<>route.kind THEN RAISE EXCEPTION 'Template kind mismatch' USING ERRCODE='HDN05';END IF;
  IF route.audience='requester' THEN people:=ARRAY[(facts->>'requesterId')::uuid];
  ELSIF route.audience IN ('assignee','customer_return') AND facts->>'sourceAssigneeId' IS NOT NULL THEN people:=ARRAY[(facts->>'sourceAssigneeId')::uuid];
  ELSIF route.audience IN ('queue','customer_return') THEN
   SELECT * INTO STRICT roster FROM helpdesk_integration.hdn_notification_queue_rosters WHERE workspace_id=(src->>'workspaceId')::uuid AND account_id=(src->>'accountId')::uuid ORDER BY revision DESC LIMIT 1 FOR SHARE;
   IF roster.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Published queue roster expired' USING ERRCODE='HDN05';END IF;people:=roster.member_ids;
  ELSE RAISE EXCEPTION 'Audience not yet qualified' USING ERRCODE='HDN05';END IF;
  FOREACH person IN ARRAY people LOOP
   IF (route.recipient_ids IS NULL OR person=ANY(route.recipient_ids)) AND (route.audience='requester' OR helpdesk_auth.hdn_notification_internal_person(target,person)) THEN
    recipients:=recipients||jsonb_build_array(jsonb_build_object('principalId',person,'channelId','resend','templateId',t.id,'templateVersion',t.version,'templateHash',t.sha256));
   END IF;
  END LOOP;
 END IF;
 RETURN jsonb_build_object('eventId',target,'workspaceId',src->'workspaceId','accountId',src->'accountId','ticketId',src->'ticketId','sourceVersion',src->'version','kind',src->'type','protocol',facts->'protocol','resourceHash',facts->'resourceHash','revision','route-'||route.revision::text,'status','published','expiresAt',helpdesk_auth.hdn_workflow_iso(route.expires_at),'recipients',recipients);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Published routing required' USING ERRCODE='HDN05';END$$;

REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_internal_person(uuid,uuid) FROM PUBLIC;
DO $private$ DECLARE role_name text;BEGIN
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_internal_person(uuid,uuid) FROM %I',role_name);END IF;
 END LOOP;
END $private$;

-- Preserve the qualified v024 contact/coverage checks; extend only current audience and required operation.
CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_recipient(i jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE w uuid:=(i->>'workspaceId')::uuid;a uuid:=(i->>'accountId')::uuid;person uuid:=(i->>'recipientId')::uuid;target uuid:=(i->>'ticketId')::uuid;p helpdesk_auth.principals%rowtype;t helpdesk_core.tickets%rowtype;s helpdesk_core.cg_ticket_resource_sets%rowtype;b helpdesk_auth.cg_resource_bindings%rowtype;c helpdesk_auth.cg_resource_connections%rowtype;g helpdesk_auth.cg_resource_grant_sets%rowtype;o helpdesk_auth.cg_resource_observations%rowtype;facts jsonb;address text;verified_at timestamptz;until timestamptz;revision text;allowed boolean:=false;local_registry jsonb;local_account jsonb;local_permission jsonb;local_receipt jsonb;local_work jsonb;ref record;recipient_operation text:='tickets.read';internal_recipient boolean;current_route helpdesk_integration.hdn_notification_routes%rowtype;BEGIN
 SELECT * INTO STRICT t FROM helpdesk_core.tickets WHERE (workspace_id,account_id,id)=(w,a,target) FOR SHARE;
 facts:=helpdesk_auth.hdn_notification_facts((i->>'eventId')::uuid);internal_recipient:=i->>'kind' IN ('internal.queue_created','internal.assignment_changed','support.customer_reply');IF i->'resourceHash'<>facts->'resourceHash' OR i->'protocol'<>facts->'protocol' OR i->'kind'<>facts->'source'->'type' OR i->'sourceVersion'<>facts->'source'->'version' OR (NOT internal_recipient AND i->'recipientId'<>facts->'requesterId') OR (internal_recipient AND NOT helpdesk_auth.hdn_notification_internal_person((i->>'eventId')::uuid,person)) THEN RAISE EXCEPTION 'Recipient source mismatch' USING ERRCODE='HDN04';END IF;
 IF internal_recipient THEN recipient_operation:='tickets.write';END IF;
 IF i->>'kind' NOT IN ('support.created','support.devolutiva','support.resolved') THEN
  SELECT * INTO STRICT current_route FROM helpdesk_integration.hdn_notification_routes WHERE workspace_id=w AND kind=i->>'kind' ORDER BY revision DESC LIMIT 1 FOR SHARE;
  IF current_route.audience='none' OR current_route.expires_at<=clock_timestamp() OR current_route.recipient_ids IS NULL OR NOT person=ANY(current_route.recipient_ids) OR current_route.effective_after IS NULL OR helpdesk_auth.hdn_notification_stamp(facts->'source'->>'createdAt')<current_route.effective_after THEN RAISE EXCEPTION 'Wave2 recipient route revoked' USING ERRCODE='HDN04';END IF;
 END IF;
 -- Candidate installation precedes the local registry. These fixed queries
 -- become available after promotion; no identifier or actor comes from a caller.
 -- Lock registry before scopes/ACL, matching the local operator's lock order.
 IF to_regclass('helpdesk_auth.cg_local_registries') IS NOT NULL THEN
  EXECUTE 'select to_jsonb(r) from helpdesk_auth.cg_local_registries r where workspace_id=$1 for share' INTO local_registry USING w;
  EXECUTE 'select to_jsonb(a) from helpdesk_auth.cg_local_accounts a where workspace_id=$1 and account_id=$2 for share' INTO local_account USING w,a;
 END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('helpdesk-human-scopes:'||w::text||':'||person::text,0));
 SELECT * INTO p FROM helpdesk_auth.principals WHERE id=person FOR SHARE;IF NOT FOUND OR NOT p.active OR p.kind<>'human' THEN RAISE EXCEPTION 'Recipient human revoked' USING ERRCODE='HDN04';END IF;
 IF NOT 'tickets:read'=ANY(helpdesk_auth.human_scopes(w,person)) OR internal_recipient AND NOT 'tickets:write'=ANY(helpdesk_auth.human_scopes(w,person)) THEN RAISE EXCEPTION 'Recipient scopes revoked' USING ERRCODE='HDN04';END IF;
 PERFORM 1 FROM helpdesk_auth.account_grants WHERE workspace_id=w AND account_id=a AND principal_id=person AND active AND (role IN ('account_manager','agent') OR role='requester' AND t.created_by=person) FOR SHARE;allowed:=FOUND;
 IF NOT allowed THEN PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE workspace_id=w AND principal_id=person AND active AND role='admin' FOR SHARE;allowed:=FOUND;END IF;IF NOT allowed THEN RAISE EXCEPTION 'Recipient ticket access revoked' USING ERRCODE='HDN04';END IF;
 SELECT * INTO STRICT s FROM helpdesk_core.cg_ticket_resource_sets WHERE (workspace_id,account_id,ticket_id)=(w,a,target) AND sealed FOR SHARE;
 SELECT * INTO b FROM helpdesk_auth.cg_resource_bindings WHERE (workspace_id,account_id,id)=(w,a,s.binding_id) FOR SHARE;IF NOT FOUND OR NOT b.active THEN RAISE EXCEPTION 'Recipient binding revoked' USING ERRCODE='HDN04';END IF;
 SELECT * INTO c FROM helpdesk_auth.cg_resource_connections WHERE (workspace_id,id)=(w,b.connection_id) FOR SHARE;IF NOT FOUND OR NOT c.active OR c.product_instance_id<>t.product_instance_id THEN RAISE EXCEPTION 'Recipient connection revoked' USING ERRCODE='HDN04';END IF;
 IF (SELECT count(*) FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,target))<>s.expected_count THEN RAISE EXCEPTION 'Recipient sealed resources unavailable' USING ERRCODE='HDN06';END IF;
 IF local_account IS NOT NULL THEN
  IF local_account->'active'='false'::jsonb THEN RAISE EXCEPTION 'Recipient local account revoked' USING ERRCODE='HDN04';END IF;
  IF local_registry IS NULL OR local_account->'active' IS DISTINCT FROM 'true'::jsonb OR local_account->'registry_revision' IS DISTINCT FROM local_registry->'revision'
  OR local_account->>'binding_id' IS DISTINCT FROM b.id::text OR local_account->>'connection_id' IS DISTINCT FROM c.id::text OR local_account->>'product_instance_id' IS DISTINCT FROM t.product_instance_id::text OR local_account->>'tenant_id' IS DISTINCT FROM b.tenant_id THEN RAISE EXCEPTION 'Recipient local account unavailable' USING ERRCODE='HDN06';END IF;
  EXECUTE 'select to_jsonb(r) from helpdesk_audit.cg_local_receipts r where workspace_id=$1 and registry_revision=$2 for share' INTO local_receipt USING w,(local_registry->>'revision')::integer;
  IF local_receipt IS NULL OR local_receipt->'decision_hash' IS DISTINCT FROM local_registry->'decision_hash' OR local_receipt->'receipt'->'decisionHash' IS DISTINCT FROM local_registry->'decision_hash' OR local_receipt->'receipt'->'revision' IS DISTINCT FROM local_registry->'revision'
  OR local_receipt->'receipt'->>'workspaceId' IS DISTINCT FROM w::text OR local_receipt->'receipt'->'requestId' IS DISTINCT FROM local_receipt->'request_id' OR local_receipt->'receipt'->'commandHash' IS DISTINCT FROM local_receipt->'command_hash'
  OR local_receipt->'receipt'->'sourceManifest' IS DISTINCT FROM '{"authority":"persisted-local-registry","complete":true,"externalApiQualified":false,"resourceType":"work","source":"helpdesk-local","version":1}'::jsonb
  OR NOT coalesce(isfinite((local_registry->>'as_of')::timestamptz),false) OR (local_registry->>'as_of')::timestamptz>clock_timestamp() OR (local_receipt->'receipt'->>'asOf')::timestamptz IS DISTINCT FROM (local_registry->>'as_of')::timestamptz
  THEN RAISE EXCEPTION 'Recipient local receipt unavailable' USING ERRCODE='HDN06';END IF;
  EXECUTE 'select to_jsonb(p) from helpdesk_auth.cg_local_permissions p where workspace_id=$1 and account_id=$2 and principal_id=$3 and operation=$4 for share' INTO local_permission USING w,a,person,recipient_operation;
  IF local_permission IS NOT NULL AND local_permission->'active'='false'::jsonb THEN RAISE EXCEPTION 'Recipient local permission revoked' USING ERRCODE='HDN04';END IF;
  IF local_permission IS NULL OR local_permission->'active' IS DISTINCT FROM 'true'::jsonb OR local_permission->'registry_revision' IS DISTINCT FROM local_registry->'revision' OR jsonb_typeof(local_permission->'work_ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Recipient local permission unavailable' USING ERRCODE='HDN06';END IF;
  FOR ref IN SELECT resource_type,resource_id FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,target) ORDER BY resource_type,resource_id FOR SHARE LOOP
   IF ref.resource_type<>'work' OR NOT local_permission->'work_ids' @> jsonb_build_array(ref.resource_id) THEN RAISE EXCEPTION 'Recipient local work permission revoked' USING ERRCODE='HDN04';END IF;
   EXECUTE 'select to_jsonb(x) from helpdesk_auth.cg_local_works x where workspace_id=$1 and account_id=$2 and id=$3 for share' INTO local_work USING w,a,ref.resource_id;
   IF local_work IS NOT NULL AND local_work->'active'='false'::jsonb THEN RAISE EXCEPTION 'Recipient local work revoked' USING ERRCODE='HDN04';END IF;
   IF local_work IS NULL OR local_work->'active' IS DISTINCT FROM 'true'::jsonb OR local_work->'registry_revision' IS DISTINCT FROM local_registry->'revision' THEN RAISE EXCEPTION 'Recipient local work unavailable' USING ERRCODE='HDN06';END IF;
  END LOOP;
  -- This is a new observation of the current immutable local decision, not an
  -- extension of an old CG envelope. Save(sending) repeats all checks and locks.
  until:=least(helpdesk_auth.hdn_notification_stamp(i->>'expiresAt'),clock_timestamp()+interval '30 seconds');revision:='local-'||(local_registry->>'revision');
 ELSE
  SELECT * INTO STRICT g FROM helpdesk_auth.cg_resource_grant_sets WHERE (workspace_id,account_id,binding_id,principal_id,operation)=(w,a,b.id,person,recipient_operation) FOR SHARE;IF NOT g.active THEN RAISE EXCEPTION 'Recipient resource grant revoked' USING ERRCODE='HDN04';END IF;
  IF g.source_revision LIKE 'local:%' THEN RAISE EXCEPTION 'Recipient local source unavailable' USING ERRCODE='HDN06';END IF;
  SELECT * INTO STRICT o FROM helpdesk_auth.cg_resource_observations WHERE (workspace_id,account_id,binding_id,principal_id,operation,grant_revision)=(w,a,b.id,person,recipient_operation,g.revision) FOR SHARE;
  IF g.as_of>clock_timestamp() OR g.expires_at<=clock_timestamp() OR o.access_revision<>g.source_revision OR o.as_of<>g.as_of OR o.expires_at<>g.expires_at OR o.expected_count<>g.expected_count
  THEN RAISE EXCEPTION 'Recipient observation unavailable' USING ERRCODE='HDN06';END IF;
  IF (SELECT count(*) FROM helpdesk_auth.cg_resource_grant_refs x WHERE (x.workspace_id,x.account_id,x.binding_id,x.principal_id,x.operation)=(w,a,b.id,person,recipient_operation))<>g.expected_count THEN RAISE EXCEPTION 'Recipient grant coverage unavailable' USING ERRCODE='HDN06';END IF;
  IF EXISTS(SELECT 1 FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,target) AND NOT EXISTS(SELECT 1 FROM helpdesk_auth.cg_resource_grant_refs y WHERE (y.workspace_id,y.account_id,y.binding_id,y.principal_id,y.operation,y.resource_type,y.resource_id)=(w,a,b.id,person,recipient_operation,x.resource_type,x.resource_id))) THEN RAISE EXCEPTION 'Recipient resources revoked' USING ERRCODE='HDN04';END IF;
  until:=least(g.expires_at,helpdesk_auth.hdn_notification_stamp(i->>'expiresAt'),clock_timestamp()+interval '30 seconds');revision:='grant-'||g.revision::text;
 END IF;
 -- Dynamic query is fixed here solely so fresh test DBs can provision synthetic
 -- auth.users independently. Identifier and recipient parameter are fixed.
 EXECUTE 'select email,email_confirmed_at from auth.users where id=$1 and email_confirmed_at is not null and deleted_at is null and (banned_until is null or banned_until<=clock_timestamp()) for share' INTO address,verified_at USING p.supabase_user_id;
 IF address IS NULL OR verified_at>clock_timestamp() OR length(address)>254 OR address !~ '^[A-Za-z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Za-z0-9][A-Za-z0-9.-]*\.[A-Za-z]{2,63}$' THEN RAISE EXCEPTION 'Verified recipient contact required' USING ERRCODE='HDN06';END IF;
 RETURN jsonb_build_object('intentId',i->'id','workspaceId',i->'workspaceId','accountId',i->'accountId','recipientId',i->'recipientId','channelId','resend','resourceHash',i->'resourceHash','revision',revision,'decision','allowed','address',address,'expiresAt',helpdesk_auth.hdn_workflow_iso(until));
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Recipient unavailable' USING ERRCODE='HDN06';END$$;


-- SOURCE hdn_review_authority.sql SHA256 1392363580bdea81382b6d53d1113f3f13697f206dace701ef9c00b6eb4080dd
-- Private immutable policy histories. No normal request can publish authority.
CREATE FUNCTION helpdesk_auth.hdnr_valid_policy(d jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT coalesce(helpdesk_auth.hdn_cfg_object(d,ARRAY['versionId','status','selfApprovalAllowed','sensitive','onApproved','onRejected','challengeTtlSeconds'])
  AND jsonb_typeof(d->'versionId')='string' AND d->>'versionId'~'^[A-Za-z0-9_-]{1,100}$'
  AND d->>'status'='published' AND d->'selfApprovalAllowed'='false'::jsonb AND d->'sensitive'='true'::jsonb
  AND d->>'onApproved'='open' AND d->>'onRejected'='waiting_customer' AND d->'challengeTtlSeconds'='300'::jsonb,false)
$$;
CREATE TABLE helpdesk_core.hdnr_policies(
 workspace_id uuid NOT NULL,account_id uuid NOT NULL,version_id text NOT NULL,document jsonb NOT NULL,
 sha256 text NOT NULL CHECK(sha256~'^[a-f0-9]{64}$'),request_id uuid NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 3 AND 1000),
 recorded_by name NOT NULL DEFAULT session_user,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(workspace_id,account_id,version_id),UNIQUE(workspace_id,request_id),
 FOREIGN KEY(workspace_id,account_id) REFERENCES helpdesk_core.accounts(workspace_id,id),
 CHECK(helpdesk_auth.hdnr_valid_policy(document) AND document->>'versionId'=version_id AND sha256=helpdesk_auth.hdni_digest(document)),CHECK(isfinite(recorded_at)));
CREATE TABLE helpdesk_core.hdnr_profiles(
 workspace_id uuid NOT NULL,account_id uuid NOT NULL,profile_version_id text NOT NULL,
 configuration_id uuid NOT NULL,configuration_version integer NOT NULL CHECK(configuration_version>=2),configuration_hash text NOT NULL CHECK(configuration_hash~'^[a-f0-9]{64}$'),
 form_id uuid NOT NULL,form_version integer NOT NULL CHECK(form_version=configuration_version),schema_hash text NOT NULL CHECK(schema_hash~'^[a-f0-9]{64}$'),
 policy_version_id text NOT NULL,required_for uuid[] NOT NULL,work_ids text[] NOT NULL,
 request_id uuid NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 3 AND 1000),recorded_by name NOT NULL DEFAULT session_user,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(workspace_id,account_id,profile_version_id),UNIQUE(workspace_id,account_id,form_id,form_version),UNIQUE(workspace_id,request_id),
 FOREIGN KEY(workspace_id,account_id,policy_version_id) REFERENCES helpdesk_core.hdnr_policies(workspace_id,account_id,version_id),
 FOREIGN KEY(workspace_id,configuration_id,configuration_version) REFERENCES helpdesk_core.hdn_cfg_versions(workspace_id,id,version),
 CHECK(helpdesk_auth.hdn_notification_valid_members(required_for,10)),
 CHECK(cardinality(work_ids) BETWEEN 1 AND 1000 AND array_ndims(work_ids)=1 AND array_lower(work_ids,1)=1 AND array_position(work_ids,NULL) IS NULL),CHECK(isfinite(recorded_at)));
CREATE TABLE helpdesk_auth.hdnr_grants(
 workspace_id uuid NOT NULL,account_id uuid NOT NULL,principal_id uuid NOT NULL REFERENCES helpdesk_auth.principals(id),
 capability text NOT NULL CHECK(capability IN ('forms.revise','approvals.request','approvals.decide')),revision bigint NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
 active boolean NOT NULL,work_ids text[] NOT NULL,expires_at timestamptz NOT NULL,
 request_id uuid NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 3 AND 1000),recorded_by name NOT NULL DEFAULT session_user,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(workspace_id,account_id,principal_id,capability,revision),UNIQUE(workspace_id,request_id),
 FOREIGN KEY(workspace_id,account_id) REFERENCES helpdesk_core.accounts(workspace_id,id),
 CHECK(cardinality(work_ids) BETWEEN 1 AND 1000 AND array_ndims(work_ids)=1 AND array_lower(work_ids,1)=1 AND array_position(work_ids,NULL) IS NULL),
 CHECK(isfinite(expires_at) AND isfinite(recorded_at) AND expires_at>recorded_at));
CREATE TABLE helpdesk_auth.hdnr_rosters(
 workspace_id uuid NOT NULL,account_id uuid NOT NULL,profile_version_id text NOT NULL,revision bigint NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
 approver_id uuid NOT NULL REFERENCES helpdesk_auth.principals(id),active boolean NOT NULL,work_ids text[] NOT NULL,expires_at timestamptz NOT NULL,
 request_id uuid NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 3 AND 1000),recorded_by name NOT NULL DEFAULT session_user,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(workspace_id,account_id,profile_version_id,revision),UNIQUE(workspace_id,request_id),
 FOREIGN KEY(workspace_id,account_id,profile_version_id) REFERENCES helpdesk_core.hdnr_profiles(workspace_id,account_id,profile_version_id),
 CHECK(cardinality(work_ids) BETWEEN 1 AND 1000 AND array_ndims(work_ids)=1 AND array_lower(work_ids,1)=1 AND array_position(work_ids,NULL) IS NULL),
 CHECK(isfinite(expires_at) AND isfinite(recorded_at) AND expires_at>recorded_at));

-- An operator cannot silently reinterpret a profile already used by a ticket.
CREATE FUNCTION helpdesk_auth.hdnr_profile_pin() RETURNS trigger LANGUAGE plpgsql VOLATILE SET search_path='' AS $$
DECLARE cfg helpdesk_core.hdn_cfg_versions%rowtype;entry jsonb;BEGIN
 PERFORM helpdesk_auth.cg_local_operator();
 SELECT * INTO STRICT cfg FROM helpdesk_core.hdn_cfg_versions WHERE (workspace_id,id,version)=(NEW.workspace_id,NEW.configuration_id,NEW.configuration_version) FOR SHARE;
 IF cfg.status<>'published' OR cfg.content_hash<>NEW.configuration_hash THEN RAISE EXCEPTION 'Published review configuration changed' USING ERRCODE='HDR02';END IF;
 SELECT e INTO STRICT entry FROM jsonb_array_elements(cfg.artifacts->'entries') e WHERE e->'form'->>'id'=NEW.form_id::text AND e->'form'->'version'=to_jsonb(NEW.form_version);
 IF entry->'workflow'->>'versionId'<>NEW.profile_version_id OR helpdesk_auth.hdni_digest(entry->'form')<>NEW.schema_hash
  OR EXISTS(SELECT 1 FROM helpdesk_core.hdn_workflow_state WHERE workspace_id=NEW.workspace_id AND account_id=NEW.account_id AND profile_version_id=NEW.profile_version_id)
 THEN RAISE EXCEPTION 'New review profile must precede its first ticket' USING ERRCODE='HDR02';END IF;
 RETURN NEW;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'Published review form unavailable' USING ERRCODE='HDR03';END$$;
CREATE TRIGGER hdnr_profile_pin BEFORE INSERT ON helpdesk_core.hdnr_profiles FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdnr_profile_pin();
DO $private$ DECLARE obj text;role_name text;BEGIN
 FOREACH obj IN ARRAY ARRAY['helpdesk_core.hdnr_policies','helpdesk_core.hdnr_profiles','helpdesk_auth.hdnr_grants','helpdesk_auth.hdnr_rosters'] LOOP
  EXECUTE 'ALTER TABLE '||obj||' ENABLE ROW LEVEL SECURITY';EXECUTE 'ALTER TABLE '||obj||' FORCE ROW LEVEL SECURITY';
  EXECUTE 'CREATE TRIGGER hdnr_history_immutable BEFORE UPDATE OR DELETE ON '||obj||' FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdn_notification_immutable()';
  EXECUTE 'REVOKE ALL ON TABLE '||obj||' FROM PUBLIC';
  FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
   IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON TABLE %s FROM %I',obj,role_name);END IF;
  END LOOP;
 END LOOP;
 REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_valid_policy(jsonb),helpdesk_auth.hdnr_profile_pin() FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_valid_policy(jsonb),helpdesk_auth.hdnr_profile_pin() FROM %I',role_name);END IF;
 END LOOP;
END $private$;


-- SOURCE hdn_review_opening_guard.sql SHA256 06363e0410dab7d66563a1d3a61891a56bcb1c0df48a6b800acd76bae5912664
-- A new triage opening requires a private same-transaction proof produced only
-- after hdni_create independently reconstructs the complete expected bundle.
CREATE TABLE helpdesk_audit.hdnr_openings(
 workspace_id uuid NOT NULL,account_id uuid NOT NULL,ticket_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES helpdesk_auth.principals(id),
 profile_version_id text NOT NULL,ticket_hash text NOT NULL CHECK(ticket_hash~'^[a-f0-9]{64}$'),profile_hash text NOT NULL CHECK(profile_hash~'^[a-f0-9]{64}$'),snapshot_hash text NOT NULL CHECK(snapshot_hash~'^[a-f0-9]{64}$'),
 transaction_id xid8 NOT NULL DEFAULT pg_current_xact_id(),PRIMARY KEY(workspace_id,account_id,ticket_id),
 FOREIGN KEY(workspace_id,account_id,profile_version_id) REFERENCES helpdesk_core.hdnr_profiles(workspace_id,account_id,profile_version_id),
 FOREIGN KEY(workspace_id,account_id,ticket_id) REFERENCES helpdesk_core.tickets(workspace_id,account_id,id) DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE helpdesk_audit.hdnr_openings ENABLE ROW LEVEL SECURITY;
ALTER TABLE helpdesk_audit.hdnr_openings FORCE ROW LEVEL SECURITY;
CREATE TRIGGER hdnr_opening_immutable BEFORE UPDATE OR DELETE ON helpdesk_audit.hdnr_openings FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdn_notification_immutable();
CREATE FUNCTION helpdesk_auth.hdnr_pending_opening_allowed(w uuid,a uuid,target uuid,person uuid) RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce(session_user='helpdesk_app' AND person=helpdesk_auth.actor_id() AND w=helpdesk_auth.workspace_id() AND helpdesk_auth.is_human()
  AND EXISTS(SELECT 1 FROM helpdesk_audit.hdnr_openings o JOIN helpdesk_core.hdnr_profiles p ON(p.workspace_id,p.account_id,p.profile_version_id)=(o.workspace_id,o.account_id,o.profile_version_id)
   WHERE (o.workspace_id,o.account_id,o.ticket_id,o.actor_id,o.transaction_id)=(w,a,target,person,pg_current_xact_id()) AND person=ANY(p.required_for)),false)
$$;
CREATE FUNCTION helpdesk_auth.hdnr_opening_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r helpdesk_audit.hdni_receipts%rowtype;s jsonb;BEGIN
 SELECT * INTO STRICT r FROM helpdesk_audit.hdni_receipts WHERE(workspace_id,account_id,ticket_id,actor_id,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.actor_id,NEW.transaction_id);
 SELECT document INTO STRICT s FROM helpdesk_core.hdni_snapshots WHERE(workspace_id,account_id,ticket_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id);
 IF r.snapshot_hash<>NEW.snapshot_hash OR helpdesk_auth.hdni_digest(s)<>NEW.snapshot_hash OR helpdesk_auth.hdni_digest(s->'bundle'->'ticket')<>NEW.ticket_hash
  OR helpdesk_auth.hdni_digest(s->'profile')<>NEW.profile_hash OR s->'profile'->'approvalRequired' IS DISTINCT FROM 'true'::jsonb
  OR s->'profile'->>'initialState'<>'triage' OR s->'profile'->>'profileVersionId'<>NEW.profile_version_id OR s->'bundle'->'workflow'->>'approval'<>'pending'
  OR s->'bundle'->'ticket'->>'status'<>'triage' OR s->'receipt' IS DISTINCT FROM r.result OR r.transaction_id<>pg_current_xact_id()
 THEN RAISE EXCEPTION 'Incomplete qualified pending opening' USING ERRCODE='23514';END IF;
 RETURN NULL;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Pending opening receipt required' USING ERRCODE='23514';END$$;
CREATE CONSTRAINT TRIGGER hdnr_opening_complete AFTER INSERT ON helpdesk_audit.hdnr_openings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdnr_opening_complete();
DO $private$ DECLARE role_name text;BEGIN
 REVOKE ALL ON TABLE helpdesk_audit.hdnr_openings FROM PUBLIC;
 REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_pending_opening_allowed(uuid,uuid,uuid,uuid),helpdesk_auth.hdnr_opening_complete() FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN
   EXECUTE format('REVOKE ALL ON TABLE helpdesk_audit.hdnr_openings FROM %I',role_name);
   EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_pending_opening_allowed(uuid,uuid,uuid,uuid),helpdesk_auth.hdnr_opening_complete() FROM %I',role_name);
  END IF;
 END LOOP;
END $private$;

create or replace function helpdesk_audit.record_ticket_effect() returns trigger
language plpgsql security definer set search_path='' as $$
declare k text; d jsonb; matched uuid; changes integer;
begin
 if new.workspace_id is distinct from helpdesk_auth.workspace_id() or helpdesk_auth.actor_id() is null then
  raise exception 'Ticket write requires authenticated transaction context' using errcode='23514';
 end if;
 if tg_op='INSERT' then
  if new.created_by is distinct from helpdesk_auth.actor_id() or new.version<>1 or (new.status<>'new' AND NOT (new.status='triage' AND helpdesk_auth.hdnr_pending_opening_allowed(new.workspace_id,new.account_id,new.id,new.created_by))) or new.assigned_to is not null then
   raise exception 'Invalid initial ticket effect' using errcode='23514';
  end if;
  k:='ticket.created';d:=jsonb_build_object('version',1);
 else
  -- Existing immutable, version, authorization and workflow guards still execute.
  changes:=(new.status is distinct from old.status)::integer+(new.priority is distinct from old.priority)::integer+
   (new.assigned_to is distinct from old.assigned_to)::integer;
  if changes>1 then raise exception 'One ticket operation per version required' using errcode='23514';end if;
  if new.subject is distinct from old.subject or new.description is distinct from old.description then
   raise exception 'Unsupported ticket field mutation' using errcode='23514';end if;
  if new.status is distinct from old.status then
   k:='ticket.status_changed';d:=jsonb_build_object('from',old.status,'to',new.status);
  elsif new.priority is distinct from old.priority then
   k:='ticket.priority_changed';d:=jsonb_build_object('from',old.priority,'to',new.priority,'version',new.version);
  elsif new.assigned_to is distinct from old.assigned_to then
   k:='ticket.assignment_changed';d:=jsonb_build_object('action',case when exists(select 1 from helpdesk_audit.hdn_workflow_commits c where c.workspace_id=new.workspace_id and c.account_id=new.account_id and c.ticket_id=new.id and c.actor_id=helpdesk_auth.actor_id() and c.transaction_id=pg_current_xact_id() and c.to_version=new.version and c.command->>'action'='transfer') then 'transfer' when new.assigned_to is null then 'release' else 'claim' end,
    'from',old.assigned_to,'to',new.assigned_to,'version',new.version);
  else
   -- A public message is inserted BEFORE its parent version advances. No empty version bumps.
   update helpdesk_audit.write_effects set applied=true
    where workspace_id=new.workspace_id and account_id=new.account_id and ticket_id=new.id
      and ticket_version=new.version and kind='message.created' and actor_id=helpdesk_auth.actor_id()
      and transaction_id=pg_current_xact_id() and not applied returning id into matched;
   if not found then raise exception 'Version bump requires a new matching message' using errcode='23514';end if;
   return null;
  end if;
 end if;
