 target:=(receipt->'result'->>'ticketId')::uuid;event_uuid:=(bundle->'audit'->>'id')::uuid;request_uuid:=(bundle->'audit'->>'requestId')::uuid;at_text:=receipt->'result'->>'createdAt';stamp:=at_text::timestamptz;
