CREATE OR REPLACE FUNCTION helpdesk_auth.hdni_opening_effect() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE snap jsonb;ticket_doc jsonb;opening_request_nonce text;stamp timestamptz;draft_expiry timestamptz;
BEGIN
 PERFORM helpdesk_auth.hdni_lock_scope(NEW.scope);
 SELECT document INTO snap FROM helpdesk_core.hdni_snapshots WHERE (workspace_id,ticket_id,account_id)=(NEW.workspace_id,NEW.ticket_id,NEW.account_id);ticket_doc:=snap->'bundle'->'ticket';opening_request_nonce:=snap->'bundle'->'audit'->>'requestId';stamp:=(ticket_doc->>'createdAt')::timestamptz;
 IF snap IS NULL OR ticket_doc->'status' IS DISTINCT FROM snap->'profile'->'initialState' OR NEW.snapshot_hash IS DISTINCT FROM helpdesk_auth.hdni_digest(snap) OR NEW.result IS DISTINCT FROM snap->'receipt' OR NEW.sequence::text IS DISTINCT FROM NEW.result->>'sequence'
 OR NOT EXISTS(SELECT 1 FROM helpdesk_core.tickets t WHERE (t.workspace_id,t.account_id,t.id,t.created_by,t.product_instance_id,t.service_code,t.subject,t.description,t.coverage_id,t.contract_version_id,t.contract_snapshot,t.created_at,t.updated_at,t.version,t.status,t.priority)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.actor_id,(ticket_doc->>'productInstanceId')::uuid,ticket_doc->>'serviceCode',ticket_doc->>'subject',ticket_doc->>'description',(ticket_doc->>'coverageId')::uuid,(ticket_doc->>'contractVersionId')::uuid,ticket_doc->'contractSnapshot',stamp,stamp,1,snap->'profile'->>'initialState',ticket_doc->>'priority') AND t.assigned_to IS NULL)
 OR NOT EXISTS(SELECT 1 FROM helpdesk_core.ticket_events e JOIN helpdesk_integration.outbox_events o ON (o.workspace_id,o.account_id,o.ticket_id,o.id,o.type)=(e.workspace_id,e.account_id,e.ticket_id,e.id,e.type) JOIN helpdesk_audit.write_effects f ON (f.workspace_id,f.event_id)=(e.workspace_id,e.id) WHERE (e.workspace_id,e.account_id,e.ticket_id,e.id,e.actor_id,e.type,e.data,e.created_at)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.event_id,NEW.actor_id,'ticket.created','{"version":1}'::jsonb,stamp) AND e.customer_visible AND f.applied AND f.transaction_id=NEW.transaction_id AND f.ticket_version=1 AND o.request_id=opening_request_nonce)
 OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.audit_events a WHERE (a.workspace_id,a.id,a.principal_id,a.action,a.resource_id,a.request_id,a.created_at)=(NEW.workspace_id,NEW.event_id,NEW.actor_id,'support.created',NEW.ticket_id,opening_request_nonce,stamp))
 OR NOT EXISTS(SELECT 1 FROM helpdesk_core.hdn_workflow_state s WHERE (s.workspace_id,s.account_id,s.ticket_id,s.profile_version_id,s.approval)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.result->>'profileVersionId',CASE WHEN snap->'profile'->'approvalRequired'='true'::jsonb THEN 'pending' ELSE 'not_required' END) AND s.last_event_at>=stamp)
 OR NOT EXISTS(SELECT 1 FROM helpdesk_core.cg_ticket_resource_sets s WHERE (s.workspace_id,s.account_id,s.ticket_id,s.binding_id,s.expected_count,s.sealed)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,(NEW.scope->>'bindingId')::uuid,jsonb_array_length(NEW.scope->'refs'),true))
 OR (SELECT count(*) FROM helpdesk_core.cg_ticket_resource_refs r WHERE (r.workspace_id,r.account_id,r.ticket_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id))<>jsonb_array_length(NEW.scope->'refs')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.scope->'refs') ref WHERE NOT EXISTS(SELECT 1 FROM helpdesk_core.cg_ticket_resource_refs r WHERE (r.workspace_id,r.account_id,r.ticket_id,r.resource_type,r.resource_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,ref->>'type',ref->>'id')))
 OR NOT EXISTS(SELECT 1 FROM helpdesk_core.hdni_protocol_counters c WHERE c.workspace_id=NEW.workspace_id AND c.last_sequence>=NEW.sequence)
 THEN RAISE EXCEPTION 'Opening effect incomplete' USING ERRCODE='23514';END IF;
 SELECT expires_at INTO draft_expiry FROM helpdesk_core.hdni_drafts d WHERE (d.workspace_id,d.id,d.owner_id,d.revision)=(NEW.workspace_id,NEW.draft_id,NEW.actor_id,NEW.draft_revision+1) AND d.document->>'status'='committed' AND d.document->>'ticketId'=NEW.ticket_id::text;
 IF draft_expiry IS NULL OR draft_expiry<=clock_timestamp() THEN RAISE EXCEPTION 'Draft effect missing or expired' USING ERRCODE='HDI06';END IF;
 IF snap->'coverage'->>'validUntil' IS NOT NULL AND (snap->'coverage'->>'validUntil')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION 'Coverage expired before commit' USING ERRCODE='HDI11';END IF;
 RETURN NULL;
END$$;


-- SOURCE hdn_review_store.sql SHA256 044d4218b49a2c17a647543b3b0d2b2b4bfc800375ecc8e6a47a6834f62d834e
-- Current role, scope, registry receipt and COMPLETE sealed work coverage;
-- copied from the natively qualified internal recipient checks, without queue semantics.
CREATE FUNCTION helpdesk_auth.hdnr_operator(w uuid,a uuid,ticket uuid,person uuid) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE t helpdesk_core.tickets%rowtype;r helpdesk_auth.cg_local_registries%rowtype;l helpdesk_auth.cg_local_accounts%rowtype;
 p helpdesk_auth.cg_local_permissions%rowtype;s helpdesk_core.cg_ticket_resource_sets%rowtype;b helpdesk_auth.cg_resource_bindings%rowtype;connection helpdesk_auth.cg_resource_connections%rowtype;ref record;BEGIN
 SELECT * INTO STRICT t FROM helpdesk_core.tickets WHERE(workspace_id,account_id,id)=(w,a,ticket) FOR SHARE;
 SELECT * INTO r FROM helpdesk_auth.cg_local_registries WHERE workspace_id=w FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Qualified local internal source required' USING ERRCODE='HDN06';END IF;
 SELECT * INTO l FROM helpdesk_auth.cg_local_accounts WHERE workspace_id=w AND account_id=a FOR SHARE;
 IF NOT FOUND OR NOT l.active THEN RETURN false;END IF;
 IF l.registry_revision<>r.revision OR l.product_instance_id<>t.product_instance_id OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.cg_local_receipts receipt WHERE receipt.workspace_id=w AND receipt.registry_revision=r.revision AND receipt.decision_hash=r.decision_hash AND receipt.receipt->>'decisionHash'=r.decision_hash AND receipt.receipt->'revision'=to_jsonb(r.revision) AND receipt.receipt->'sourceManifest'=helpdesk_auth.cg_local_manifest()) THEN RAISE EXCEPTION 'Current local internal receipt required' USING ERRCODE='HDN06';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('helpdesk-human-scopes:'||w::text||':'||person::text,0));
 PERFORM 1 FROM helpdesk_auth.principals WHERE id=person AND kind='human' AND active FOR SHARE;IF NOT FOUND THEN RETURN false;END IF;
 IF NOT ARRAY['tickets:read','tickets:write']<@helpdesk_auth.human_scopes(w,person) THEN RETURN false;END IF;
 PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE workspace_id=w AND principal_id=person AND active AND role='admin' FOR SHARE;
 IF NOT FOUND THEN PERFORM 1 FROM helpdesk_auth.account_grants WHERE workspace_id=w AND account_id=a AND principal_id=person AND active AND role='agent' FOR SHARE;IF NOT FOUND THEN RETURN false;END IF;END IF;
 SELECT * INTO p FROM helpdesk_auth.cg_local_permissions WHERE workspace_id=w AND account_id=a AND principal_id=person AND operation='tickets.write' FOR SHARE;
 IF NOT FOUND OR NOT p.active THEN RETURN false;END IF;
 IF p.registry_revision<>r.revision THEN RAISE EXCEPTION 'Current internal write decision required' USING ERRCODE='HDN06';END IF;
 SELECT * INTO STRICT s FROM helpdesk_core.cg_ticket_resource_sets WHERE (workspace_id,account_id,ticket_id)=(w,a,ticket) AND sealed FOR SHARE;
 SELECT * INTO b FROM helpdesk_auth.cg_resource_bindings WHERE (workspace_id,account_id,id)=(w,a,s.binding_id) FOR SHARE;
 IF NOT FOUND OR NOT b.active THEN RETURN false;END IF;
 SELECT * INTO connection FROM helpdesk_auth.cg_resource_connections WHERE (workspace_id,id)=(w,b.connection_id) FOR SHARE;
 IF NOT FOUND OR NOT connection.active THEN RETURN false;END IF;
 IF l.binding_id<>s.binding_id OR l.connection_id<>connection.id OR b.tenant_id<>l.tenant_id OR connection.product_instance_id<>t.product_instance_id THEN RAISE EXCEPTION 'Internal namespace mismatch' USING ERRCODE='HDN06';END IF;
 IF (SELECT count(*) FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,ticket))<>s.expected_count THEN RAISE EXCEPTION 'Incomplete sealed internal resources' USING ERRCODE='HDN06';END IF;
 FOR ref IN SELECT x.resource_type,x.resource_id FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,ticket) ORDER BY x.resource_type,x.resource_id FOR SHARE LOOP
  IF ref.resource_type<>'work' OR NOT ref.resource_id=ANY(p.work_ids) THEN RETURN false;END IF;
  PERFORM 1 FROM helpdesk_auth.cg_local_works x WHERE x.workspace_id=w AND x.account_id=a AND x.id=ref.resource_id AND x.active AND x.registry_revision=r.revision FOR SHARE;
  IF NOT FOUND THEN RETURN false;END IF;
 END LOOP;RETURN true;
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Internal authority unavailable' USING ERRCODE='HDN06';END$$;

-- Private review state. Only qualified request RPCs may produce rows.
CREATE TABLE helpdesk_core.hdnr_forms(
 workspace_id uuid NOT NULL,account_id uuid NOT NULL,ticket_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>1),source_version integer NOT NULL CHECK(source_version>1),
 document jsonb NOT NULL,sha256 text NOT NULL CHECK(sha256=helpdesk_auth.hdni_digest(document)),receipt_id uuid NOT NULL,
 PRIMARY KEY(workspace_id,account_id,ticket_id,revision),UNIQUE(workspace_id,account_id,ticket_id,source_version),
 FOREIGN KEY(workspace_id,account_id,ticket_id) REFERENCES helpdesk_core.tickets(workspace_id,account_id,id),
 CHECK(helpdesk_auth.hdn_cfg_object(document,ARRAY['formId','formVersion','schemaHash','revision','answers','publicAnswers','evidence','draftId','draftRevision']) AND document->'revision'=to_jsonb(revision)));
CREATE TABLE helpdesk_core.hdnr_invitations(
 id uuid PRIMARY KEY,workspace_id uuid NOT NULL,account_id uuid NOT NULL,ticket_id uuid NOT NULL,receipt_id uuid NOT NULL,document jsonb NOT NULL,revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),
 UNIQUE(workspace_id,account_id,ticket_id,id),FOREIGN KEY(workspace_id,account_id,ticket_id) REFERENCES helpdesk_core.tickets(workspace_id,account_id,id),
 CHECK(helpdesk_auth.hdn_cfg_object(document,ARRAY['id','ticketId','workspaceId','accountId','approverId','policyVersionId','ticketVersion','formRevision','targetHash','status','createdAt','expiresAt','challenge'])
  AND document->>'id'=id::text AND document->>'ticketId'=ticket_id::text AND document->>'workspaceId'=workspace_id::text AND document->>'accountId'=account_id::text
  AND document->>'status' IN ('pending','used','revoked') AND document->>'targetHash'~'^[a-f0-9]{64}$'));
CREATE UNIQUE INDEX hdnr_one_pending_invitation ON helpdesk_core.hdnr_invitations(workspace_id,account_id,ticket_id) WHERE document->>'status'='pending';
CREATE TABLE helpdesk_audit.hdnr_receipts(
 id uuid PRIMARY KEY,workspace_id uuid NOT NULL,account_id uuid NOT NULL,ticket_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES helpdesk_auth.principals(id),
 intent_key text NOT NULL CHECK(intent_key~'^[A-Za-z0-9._:-]{16,128}$'),intent_hash text NOT NULL CHECK(intent_hash~'^[a-f0-9]{64}$'),action text NOT NULL CHECK(action IN ('invitation','approval','revision')),
 invitation_id uuid,result jsonb NOT NULL,bundle jsonb NOT NULL,scope jsonb NOT NULL,request_id uuid NOT NULL,created_at timestamptz NOT NULL CHECK(isfinite(created_at)),transaction_id xid8 NOT NULL DEFAULT pg_current_xact_id(),
 UNIQUE(workspace_id,actor_id,intent_key),UNIQUE(workspace_id,account_id,ticket_id,id),FOREIGN KEY(workspace_id,account_id,ticket_id) REFERENCES helpdesk_core.tickets(workspace_id,account_id,id));
CREATE TABLE helpdesk_integration.hdnr_sources(
 id uuid PRIMARY KEY,workspace_id uuid NOT NULL,account_id uuid NOT NULL,ticket_id uuid NOT NULL,receipt_id uuid NOT NULL,
 kind text NOT NULL CHECK(kind IN ('support.approval_requested','support.approval_granted','support.approval_rejected','support.form_revised')),
 source_version integer NOT NULL CHECK(source_version>0),invitation_id uuid,request_id uuid NOT NULL,created_at timestamptz NOT NULL CHECK(isfinite(created_at)),
 UNIQUE(workspace_id,receipt_id),FOREIGN KEY(workspace_id,account_id,ticket_id,receipt_id) REFERENCES helpdesk_audit.hdnr_receipts(workspace_id,account_id,ticket_id,id),
 CHECK((kind='support.approval_requested')=(invitation_id IS NOT NULL)));
ALTER TABLE helpdesk_core.hdnr_forms ADD FOREIGN KEY(workspace_id,account_id,ticket_id,receipt_id) REFERENCES helpdesk_audit.hdnr_receipts(workspace_id,account_id,ticket_id,id);
ALTER TABLE helpdesk_core.hdnr_invitations ADD FOREIGN KEY(workspace_id,account_id,ticket_id,receipt_id) REFERENCES helpdesk_audit.hdnr_receipts(workspace_id,account_id,ticket_id,id);
CREATE TABLE helpdesk_audit.hdnr_challenges(
 workspace_id uuid NOT NULL,account_id uuid NOT NULL,ticket_id uuid NOT NULL,invitation_id uuid NOT NULL,generation integer NOT NULL CHECK(generation>0),
 actor_id uuid NOT NULL REFERENCES helpdesk_auth.principals(id),challenge_hash text NOT NULL CHECK(challenge_hash~'^[a-f0-9]{64}$'),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL,
 target_hash text NOT NULL CHECK(target_hash~'^[a-f0-9]{64}$'),transaction_id xid8 NOT NULL DEFAULT pg_current_xact_id(),
 PRIMARY KEY(workspace_id,invitation_id,generation),FOREIGN KEY(workspace_id,account_id,ticket_id,invitation_id) REFERENCES helpdesk_core.hdnr_invitations(workspace_id,account_id,ticket_id,id),
 CHECK(isfinite(created_at) AND isfinite(expires_at) AND expires_at>created_at));

CREATE FUNCTION helpdesk_auth.hdnr_scope_hash(ctx jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT helpdesk_auth.hdni_digest(jsonb_build_object('principalId',ctx->'principalId','workspaceId',ctx->'workspaceId','accountId',ctx->'accountId','bindingId',ctx->'bindingId','bindingRevision',ctx->'bindingRevision','accessRevision',ctx->'accessRevision','manifestFingerprint',ctx->'manifestFingerprint','refs',helpdesk_auth.hdni_refs_key(ctx->'refs')))
$$;
CREATE FUNCTION helpdesk_auth.hdnr_target_hash(a jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT helpdesk_auth.hdni_digest(jsonb_build_object('workspaceId',a->'ticket'->'workspaceId','accountId',a->'ticket'->'accountId','ticketId',a->'ticket'->'id','ticketVersion',a->'ticket'->'version','profileVersionId',a->'ticket'->'profileVersionId','requesterId',a->'requesterId','formRevision',a->'form'->'revision','formHash',helpdesk_auth.hdni_digest(jsonb_build_object('formId',a->'form'->'formId','formVersion',a->'form'->'formVersion','schemaHash',a->'form'->'schemaHash','answers',a->'form'->'answers','evidence',a->'form'->'evidence')),'refsHash',helpdesk_auth.hdni_digest(to_jsonb(helpdesk_auth.hdni_refs_key(a->'refs')))))
$$;
CREATE FUNCTION helpdesk_auth.hdnr_aggregate(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE current_doc jsonb;s helpdesk_core.hdni_snapshots%rowtype;r helpdesk_audit.hdni_receipts%rowtype;p helpdesk_core.hdnr_profiles%rowtype;policy helpdesk_core.hdnr_policies%rowtype;
 f helpdesk_core.hdnr_forms%rowtype;form_doc jsonb;events jsonb;event_count integer;distinct_count integer;w uuid:=helpdesk_auth.workspace_id();who uuid:=helpdesk_auth.actor_id();BEGIN
 current_doc:=helpdesk_auth.hdn_read_support_workflow(target);
 IF current_doc IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO STRICT s FROM helpdesk_core.hdni_snapshots WHERE(workspace_id,account_id,ticket_id)=(w,(current_doc->'ticket'->>'accountId')::uuid,target) FOR SHARE;
 SELECT * INTO STRICT r FROM helpdesk_audit.hdni_receipts WHERE(workspace_id,account_id,ticket_id)=(s.workspace_id,s.account_id,target) FOR SHARE;
 IF r.snapshot_hash<>helpdesk_auth.hdni_digest(s.document) OR r.result IS DISTINCT FROM s.document->'receipt' THEN RAISE EXCEPTION 'Original review snapshot changed' USING ERRCODE='HDR03';END IF;
 SELECT * INTO STRICT p FROM helpdesk_core.hdnr_profiles WHERE(workspace_id,account_id,profile_version_id)=(w,s.account_id,current_doc->'ticket'->>'profileVersionId') FOR SHARE;
 IF s.document->'profile'->>'profileVersionId'<>p.profile_version_id OR s.document->'bundle'->'form'->>'schemaHash'<>p.schema_hash OR helpdesk_auth.hdni_digest(s.document->'profile'->'form')<>p.schema_hash
  OR s.document->'profile'->'approvalRequired'='true'::jsonb AND NOT (s.document->'bundle'->>'requesterId')::uuid=ANY(p.required_for)
 THEN RAISE EXCEPTION 'Pinned review profile changed' USING ERRCODE='HDR03';END IF;
 SELECT * INTO STRICT policy FROM helpdesk_core.hdnr_policies WHERE(workspace_id,account_id,version_id)=(w,s.account_id,p.policy_version_id) FOR SHARE;
 form_doc:=s.document->'bundle'->'form'||jsonb_build_object('revision',1,'draftId',s.document->'bundle'->'draftId','draftRevision',s.document->'draft'->'revision');
 SELECT * INTO f FROM helpdesk_core.hdnr_forms WHERE(workspace_id,account_id,ticket_id)=(w,s.account_id,target) ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF FOUND THEN
  IF f.sha256<>helpdesk_auth.hdni_digest(f.document) OR f.source_version>(current_doc->'ticket'->>'version')::integer OR (SELECT count(*) FROM helpdesk_core.hdnr_forms WHERE(workspace_id,account_id,ticket_id)=(w,s.account_id,target))<>f.revision-1 THEN RAISE EXCEPTION 'Review form history incomplete' USING ERRCODE='HDR03';END IF;
  form_doc:=f.document;
 END IF;
 IF form_doc->>'schemaHash'<>p.schema_hash OR form_doc->>'formId'<>p.form_id::text OR form_doc->'formVersion'<>to_jsonb(p.form_version) THEN RAISE EXCEPTION 'Review form pin changed' USING ERRCODE='HDR03';END IF;
 SELECT jsonb_agg(value ORDER BY (value->>'sequence')::integer),count(*),count(DISTINCT(value->>'sequence')::integer) INTO events,event_count,distinct_count FROM (
  SELECT s.document->'bundle'->'event' value UNION ALL SELECT public_event FROM helpdesk_audit.hdn_workflow_commits WHERE(workspace_id,account_id,ticket_id)=(w,s.account_id,target)) stream;
 IF event_count<>(current_doc->'ticket'->>'version')::integer OR distinct_count<>event_count OR EXISTS(SELECT 1 FROM jsonb_array_elements(events) e WHERE e->>'profileVersionId'<>p.profile_version_id OR e->>'ticketId'<>target::text OR e->>'workspaceId'<>w::text OR (e->>'sequence')::integer NOT BETWEEN 1 AND event_count) THEN RAISE EXCEPTION 'Review workflow history incomplete' USING ERRCODE='HDR03';END IF;
 RETURN jsonb_build_object('principalId',who,'aggregate',jsonb_build_object('ticket',current_doc->'ticket','requesterId',s.document->'bundle'->'requesterId','protocol',s.document->'bundle'->'protocol','refs',s.document->'bundle'->'resourceScope'->'refs','form',form_doc,'profile',s.document->'profile','approvalPolicy',policy.document,'events',events));
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Pinned review aggregate unavailable' USING ERRCODE='HDR03';WHEN SQLSTATE 'HDW01' THEN RAISE EXCEPTION 'Review ticket access denied' USING ERRCODE='HDR01';END$$;
CREATE FUNCTION helpdesk_auth.hdnr_grant(target uuid,cap text,ctx jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE aggregate_doc jsonb;g helpdesk_auth.hdnr_grants%rowtype;ref jsonb;w uuid:=helpdesk_auth.workspace_id();who uuid:=helpdesk_auth.actor_id();a uuid;BEGIN
 PERFORM helpdesk_auth.hdni_lock_scope(ctx);
 IF session_user<>'helpdesk_app' OR ctx->>'operation'<>'tickets.write' OR cap NOT IN ('forms.revise','approvals.request','approvals.decide') THEN RAISE EXCEPTION 'Review write capability required' USING ERRCODE='HDR05';END IF;
 aggregate_doc:=helpdesk_auth.hdnr_aggregate(target)->'aggregate';a:=(aggregate_doc->'ticket'->>'accountId')::uuid;
 IF a::text IS DISTINCT FROM ctx->>'accountId' OR helpdesk_auth.hdni_refs_key(aggregate_doc->'refs') IS DISTINCT FROM helpdesk_auth.hdni_refs_key(ctx->'refs') THEN RAISE EXCEPTION 'Review resource scope changed' USING ERRCODE='HDR01';END IF;
 SELECT * INTO g FROM helpdesk_auth.hdnr_grants WHERE(workspace_id,account_id,principal_id,capability)=(w,a,who,cap) ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF NOT FOUND OR NOT g.active OR g.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Current review capability required' USING ERRCODE='HDR05';END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(ctx->'refs') LOOP
  IF ref->>'type'<>'work' OR NOT (ref->>'id')=ANY(g.work_ids) THEN RAISE EXCEPTION 'Review capability does not cover exact work' USING ERRCODE='HDR05';END IF;
 END LOOP;
 IF cap<>'forms.revise' THEN
  PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE workspace_id=w AND principal_id=who AND active AND role='admin' FOR SHARE;
  IF NOT FOUND OR NOT helpdesk_auth.hdnr_operator(w,a,target,who) THEN RAISE EXCEPTION 'Initial approval requires current administrator authority' USING ERRCODE='HDR05';END IF;
 END IF;
 RETURN jsonb_build_object('principalId',who,'workspaceId',w,'accountId',a,'capability',cap,'scopeHash',helpdesk_auth.hdnr_scope_hash(ctx),'active',true,'revision','review-grant-'||g.revision::text,'expiresAt',helpdesk_auth.hdn_workflow_iso(g.expires_at));
END$$;
CREATE FUNCTION helpdesk_auth.hdnr_route(target uuid,ctx jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE doc jsonb;roster helpdesk_auth.hdnr_rosters%rowtype;g helpdesk_auth.hdnr_grants%rowtype;ref jsonb;w uuid:=helpdesk_auth.workspace_id();a uuid;BEGIN
 PERFORM helpdesk_auth.hdnr_grant(target,'approvals.request',ctx);doc:=helpdesk_auth.hdnr_aggregate(target)->'aggregate';a:=(doc->'ticket'->>'accountId')::uuid;
 SELECT * INTO roster FROM helpdesk_auth.hdnr_rosters WHERE(workspace_id,account_id,profile_version_id)=(w,a,doc->'ticket'->>'profileVersionId') ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF NOT FOUND OR NOT roster.active OR roster.expires_at<=clock_timestamp() OR roster.approver_id::text IN (doc->>'requesterId',doc->'ticket'->>'createdBy') OR NOT helpdesk_auth.hdnr_operator(w,a,target,roster.approver_id) THEN RAISE EXCEPTION 'Exact current approver required' USING ERRCODE='HDR01';END IF;
 PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE workspace_id=w AND principal_id=roster.approver_id AND active AND role='admin' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Initial approver assurance policy requires administrator' USING ERRCODE='HDR01';END IF;
 SELECT * INTO g FROM helpdesk_auth.hdnr_grants WHERE(workspace_id,account_id,principal_id,capability)=(w,a,roster.approver_id,'approvals.decide') ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF NOT FOUND OR NOT g.active OR g.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Approver capability revoked' USING ERRCODE='HDR01';END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(ctx->'refs') LOOP
  IF ref->>'type'<>'work' OR NOT (ref->>'id')=ANY(g.work_ids) OR NOT (ref->>'id')=ANY(roster.work_ids) THEN RAISE EXCEPTION 'Approver work coverage revoked' USING ERRCODE='HDR01';END IF;
 END LOOP;
 RETURN jsonb_build_object('principalId',roster.approver_id,'principalKind','human','workspaceId',w,'accountId',a,'ticketId',target,'policyVersionId',doc->'approvalPolicy'->'versionId','resourceHash',helpdesk_auth.hdni_digest(to_jsonb(helpdesk_auth.hdni_refs_key(ctx->'refs'))),'revision','review-roster-'||roster.revision::text,'active',true,'expiresAt',helpdesk_auth.hdn_workflow_iso(least(roster.expires_at,g.expires_at)));
END$$;



-- SOURCE hdn_review_invitation.sql SHA256 d735ca889f7bf99c61e7fb8ecf8ed58ff24dc4e333f88cd1459b23274575d6d1
CREATE FUNCTION helpdesk_auth.hdnr_context(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE ctx jsonb;BEGIN
 IF session_user<>'helpdesk_app' OR NOT coalesce(helpdesk_auth.is_human(),false) OR NOT coalesce(helpdesk_auth.has_scope(helpdesk_auth.workspace_id(),'tickets:read'),false) OR NOT coalesce(helpdesk_auth.has_scope(helpdesk_auth.workspace_id(),'tickets:write'),false) THEN RAISE EXCEPTION 'Human review session required' USING ERRCODE='HDR01';END IF;
 ctx:=helpdesk_auth.cg_lock_ticket_scope(target,'tickets.write')-'ticketId';
 IF ctx IS NULL THEN RAISE EXCEPTION 'Current review work access required' USING ERRCODE='HDR01';END IF;
 PERFORM helpdesk_auth.hdni_lock_scope(ctx);RETURN ctx;
END$$;
CREATE FUNCTION helpdesk_auth.hdnr_invitation_receipt(key text) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE row helpdesk_audit.hdnr_receipts%rowtype;BEGIN
 IF session_user<>'helpdesk_app' OR NOT coalesce(helpdesk_auth.is_human(),false) OR key IS NULL OR key!~'^[A-Za-z0-9._:-]{16,128}$' THEN RAISE EXCEPTION 'Invalid private receipt lookup' USING ERRCODE='HDR01';END IF;
 SELECT * INTO row FROM helpdesk_audit.hdnr_receipts WHERE(workspace_id,actor_id,intent_key)=(helpdesk_auth.workspace_id(),helpdesk_auth.actor_id(),key) FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 PERFORM helpdesk_auth.hdnr_grant(row.ticket_id,'approvals.request',helpdesk_auth.hdnr_context(row.ticket_id));
 IF row.action<>'invitation' THEN RAISE EXCEPTION 'Review intent key belongs to another action' USING ERRCODE='HDR04';END IF;
 RETURN jsonb_build_object('key',row.intent_key,'hash',row.intent_hash,'result',row.result);
END$$;
CREATE FUNCTION helpdesk_auth.hdnr_pending_invitation(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;BEGIN
 PERFORM helpdesk_auth.hdnr_grant(target,'approvals.request',helpdesk_auth.hdnr_context(target));
 SELECT document INTO result FROM helpdesk_core.hdnr_invitations WHERE workspace_id=helpdesk_auth.workspace_id() AND ticket_id=target AND document->>'status'='pending' FOR UPDATE;RETURN result;
END$$;
CREATE FUNCTION helpdesk_auth.hdnr_invitation(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE row helpdesk_core.hdnr_invitations%rowtype;BEGIN
 IF session_user<>'helpdesk_app' OR NOT coalesce(helpdesk_auth.is_human(),false) THEN RAISE EXCEPTION 'Human approval session required' USING ERRCODE='HDR01';END IF;
 SELECT * INTO row FROM helpdesk_core.hdnr_invitations WHERE workspace_id=helpdesk_auth.workspace_id() AND id=target FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF row.document->>'approverId' IS DISTINCT FROM helpdesk_auth.actor_id()::text THEN RAISE EXCEPTION 'Invitation belongs to another person' USING ERRCODE='HDR01';END IF;
 PERFORM helpdesk_auth.hdnr_grant(row.ticket_id,'approvals.decide',helpdesk_auth.hdnr_context(row.ticket_id));RETURN row.document;
END$$;
CREATE FUNCTION helpdesk_auth.hdnr_commit_invitation(bundle jsonb,receipt jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE w uuid:=helpdesk_auth.workspace_id();who uuid:=helpdesk_auth.actor_id();target uuid;ctx jsonb;a jsonb;route jsonb;i jsonb:=bundle->'invitation';audit_doc jsonb:=bundle->'audit';outbox_doc jsonb:=bundle->'outbox';result jsonb;expected_i jsonb;expected_audit jsonb;expected_outbox jsonb;
 account uuid;invitation_uuid uuid;effect_uuid uuid;request_uuid uuid;at_text text;stamp timestamptz;intent_hash text;prior helpdesk_audit.hdnr_receipts%rowtype;affected integer;BEGIN
 IF NOT coalesce(helpdesk_auth.hdn_cfg_object(bundle,ARRAY['invitation','audit','outbox']) AND helpdesk_auth.hdn_cfg_object(receipt,ARRAY['key','hash','result']),false)
  OR receipt->>'key' IS NULL OR receipt->>'key'!~'^[A-Za-z0-9._:-]{16,128}$' THEN RAISE EXCEPTION 'Invalid invitation command' USING ERRCODE='HDR03';END IF;
 target:=(receipt->'result'->>'ticketId')::uuid;ctx:=helpdesk_auth.hdnr_context(target);PERFORM helpdesk_auth.hdnr_grant(target,'approvals.request',ctx);a:=helpdesk_auth.hdnr_aggregate(target)->'aggregate';account:=(a->'ticket'->>'accountId')::uuid;
 intent_hash:=helpdesk_auth.hdni_digest(jsonb_build_object('ticketId',target,'expected',a->'ticket'->'version','actorId',who,'workspaceId',w));
 SELECT * INTO prior FROM helpdesk_audit.hdnr_receipts WHERE(workspace_id,actor_id,intent_key)=(w,who,receipt->>'key') FOR UPDATE;
 IF FOUND THEN IF prior.action<>'invitation' OR prior.intent_hash IS DISTINCT FROM receipt->>'hash' THEN RAISE EXCEPTION 'Review idempotency conflict' USING ERRCODE='HDR04';END IF;RETURN prior.result;END IF;
 IF receipt->>'hash' IS DISTINCT FROM intent_hash OR a->'ticket'->>'approval'<>'pending' OR a->'ticket'->>'status' NOT IN ('new','triage') OR a->'profile'->'approvalRequired' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Invitation target changed' USING ERRCODE='HDR02';END IF;
 IF EXISTS(SELECT 1 FROM helpdesk_core.hdnr_invitations WHERE workspace_id=w AND ticket_id=target AND document->>'status'='pending') THEN RAISE EXCEPTION 'An invitation is already pending' USING ERRCODE='HDR03';END IF;
 route:=helpdesk_auth.hdnr_route(target,ctx);invitation_uuid:=(i->>'id')::uuid;effect_uuid:=(audit_doc->>'id')::uuid;request_uuid:=(audit_doc->>'requestId')::uuid;at_text:=audit_doc->>'at';stamp:=helpdesk_auth.hdn_notification_stamp(at_text);
 IF i->>'id'!~'^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' OR effect_uuid=invitation_uuid OR stamp>clock_timestamp() OR stamp<clock_timestamp()-interval '30 seconds' OR stamp<helpdesk_auth.hdn_notification_stamp(a->'ticket'->>'lastEventAt') THEN RAISE EXCEPTION 'Invalid invitation identity or time' USING ERRCODE='HDR03';END IF;
 expected_i:=jsonb_build_object('id',invitation_uuid,'ticketId',target,'workspaceId',w,'accountId',account,'approverId',route->'principalId','policyVersionId',a->'approvalPolicy'->'versionId','ticketVersion',a->'ticket'->'version','formRevision',a->'form'->'revision','targetHash',helpdesk_auth.hdnr_target_hash(a),'status','pending','createdAt',at_text,'expiresAt',route->'expiresAt','challenge',NULL);
 expected_audit:=jsonb_build_object('id',effect_uuid,'actorId',who,'ticketId',target,'invitationId',invitation_uuid,'requestId',request_uuid,'type','approval.requested','rosterRevision',route->'revision','at',at_text);
 expected_outbox:=jsonb_build_object('id',effect_uuid,'workspaceId',w,'accountId',account,'ticketId',target,'type','support.approval_requested','invitationId',invitation_uuid,'version',a->'ticket'->'version','requestId',request_uuid,'createdAt',at_text);
 result:=jsonb_build_object('ticketId',target,'workspaceId',w,'accountId',account,'actorId',who,'invitationId',invitation_uuid,'ticketVersion',a->'ticket'->'version','formRevision',a->'form'->'revision','notification','pending','replayed',false);
 IF i IS DISTINCT FROM expected_i OR audit_doc IS DISTINCT FROM expected_audit OR outbox_doc IS DISTINCT FROM expected_outbox OR receipt->'result' IS DISTINCT FROM result THEN RAISE EXCEPTION 'Invitation bundle is not the pinned command' USING ERRCODE='HDR02';END IF;
 INSERT INTO helpdesk_audit.hdnr_receipts(id,workspace_id,account_id,ticket_id,actor_id,intent_key,intent_hash,action,invitation_id,result,bundle,scope,request_id,created_at) VALUES(effect_uuid,w,account,target,who,receipt->>'key',intent_hash,'invitation',invitation_uuid,result,bundle,ctx,request_uuid,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Invitation receipt suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_core.hdnr_invitations(id,workspace_id,account_id,ticket_id,receipt_id,document) VALUES(invitation_uuid,w,account,target,effect_uuid,expected_i);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Invitation suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_audit.audit_events(workspace_id,id,principal_id,action,resource_id,request_id,created_at) VALUES(w,effect_uuid,who,'approval.requested',target,request_uuid::text,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Invitation audit suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_integration.hdnr_sources(id,workspace_id,account_id,ticket_id,receipt_id,kind,source_version,invitation_id,request_id,created_at) VALUES(effect_uuid,w,account,target,effect_uuid,'support.approval_requested',(a->'ticket'->>'version')::integer,invitation_uuid,request_uuid,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Invitation source suppressed' USING ERRCODE='HDR03';END IF;
 RETURN result;
EXCEPTION WHEN data_exception OR no_data_found THEN RAISE EXCEPTION 'Invalid invitation command' USING ERRCODE='HDR03';END$$;
CREATE FUNCTION helpdesk_auth.hdnr_invitation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r helpdesk_audit.hdnr_receipts%rowtype;BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Invitation mutation requires a qualified later command' USING ERRCODE='HDR03';END IF;
 SELECT * INTO STRICT r FROM helpdesk_audit.hdnr_receipts WHERE(id,workspace_id,account_id,ticket_id,action,transaction_id)=(NEW.receipt_id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,'invitation',pg_current_xact_id());
 IF session_user<>'helpdesk_app' OR r.actor_id IS DISTINCT FROM helpdesk_auth.actor_id() OR r.invitation_id<>NEW.id OR r.bundle->'invitation' IS DISTINCT FROM NEW.document OR NEW.revision<>1 THEN RAISE EXCEPTION 'Unqualified invitation insertion' USING ERRCODE='HDR03';END IF;RETURN NEW;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Invitation receipt required' USING ERRCODE='HDR03';END$$;
CREATE TRIGGER hdnr_invitation_guard BEFORE INSERT OR UPDATE OR DELETE ON helpdesk_core.hdnr_invitations FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdnr_invitation_guard();
CREATE FUNCTION helpdesk_auth.hdnr_receipt_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE source helpdesk_integration.hdnr_sources%rowtype;invitation helpdesk_core.hdnr_invitations%rowtype;BEGIN
 IF session_user<>'helpdesk_app' OR NEW.transaction_id<>pg_current_xact_id() OR NEW.workspace_id IS DISTINCT FROM helpdesk_auth.workspace_id() OR NEW.actor_id IS DISTINCT FROM helpdesk_auth.actor_id() OR NEW.action<>'invitation' THEN RAISE EXCEPTION 'Unqualified review receipt' USING ERRCODE='HDR03';END IF;
 PERFORM helpdesk_auth.hdnr_grant(NEW.ticket_id,'approvals.request',NEW.scope);
 SELECT * INTO STRICT source FROM helpdesk_integration.hdnr_sources WHERE(id,workspace_id,account_id,ticket_id,receipt_id)=(NEW.id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id);
 SELECT * INTO STRICT invitation FROM helpdesk_core.hdnr_invitations WHERE(id,workspace_id,account_id,ticket_id,receipt_id)=(NEW.invitation_id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id);
 IF source.kind<>'support.approval_requested' OR source.invitation_id<>NEW.invitation_id OR source.created_at<>NEW.created_at OR source.request_id<>NEW.request_id
  OR source.source_version<>(NEW.result->>'ticketVersion')::integer OR invitation.document IS DISTINCT FROM NEW.bundle->'invitation'
  OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.audit_events a WHERE(a.workspace_id,a.id,a.principal_id,a.action,a.resource_id,a.request_id,a.created_at)=(NEW.workspace_id,NEW.id,NEW.actor_id,'approval.requested',NEW.ticket_id,NEW.request_id::text,NEW.created_at))
 THEN RAISE EXCEPTION 'Invitation effects incomplete' USING ERRCODE='HDR03';END IF;
 RETURN NULL;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Review receipt effects missing' USING ERRCODE='HDR03';END$$;
CREATE CONSTRAINT TRIGGER hdnr_receipt_complete AFTER INSERT ON helpdesk_audit.hdnr_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdnr_receipt_complete();
DO $private$ DECLARE obj text;role_name text;signature text;BEGIN
 FOREACH obj IN ARRAY ARRAY['helpdesk_core.hdnr_forms','helpdesk_core.hdnr_invitations','helpdesk_audit.hdnr_receipts','helpdesk_integration.hdnr_sources','helpdesk_audit.hdnr_challenges'] LOOP
  EXECUTE 'ALTER TABLE '||obj||' ENABLE ROW LEVEL SECURITY';EXECUTE 'ALTER TABLE '||obj||' FORCE ROW LEVEL SECURITY';
  IF obj<>'helpdesk_core.hdnr_invitations' THEN EXECUTE 'CREATE TRIGGER hdnr_history_immutable BEFORE UPDATE OR DELETE ON '||obj||' FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdn_notification_immutable()';END IF;
  EXECUTE 'REVOKE ALL ON TABLE '||obj||' FROM PUBLIC';
  FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
   IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON TABLE %s FROM %I',obj,role_name);END IF;
  END LOOP;
 END LOOP;
 FOREACH signature IN ARRAY ARRAY['hdnr_operator(uuid,uuid,uuid,uuid)','hdnr_scope_hash(jsonb)','hdnr_target_hash(jsonb)','hdnr_context(uuid)','hdnr_aggregate(uuid)','hdnr_grant(uuid,text,jsonb)','hdnr_route(uuid,jsonb)','hdnr_invitation_receipt(text)','hdnr_pending_invitation(uuid)','hdnr_invitation(uuid)','hdnr_commit_invitation(jsonb,jsonb)','hdnr_invitation_guard()','hdnr_receipt_complete()'] LOOP
  EXECUTE 'REVOKE ALL ON FUNCTION helpdesk_auth.'||signature||' FROM PUBLIC';
  FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
   IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.%s FROM %I',signature,role_name);END IF;
  END LOOP;
 END LOOP;
 GRANT EXECUTE ON FUNCTION helpdesk_auth.hdnr_aggregate(uuid),helpdesk_auth.hdnr_grant(uuid,text,jsonb),helpdesk_auth.hdnr_route(uuid,jsonb),helpdesk_auth.hdnr_invitation_receipt(text),helpdesk_auth.hdnr_pending_invitation(uuid),helpdesk_auth.hdnr_invitation(uuid),helpdesk_auth.hdnr_commit_invitation(jsonb,jsonb) TO helpdesk_app;
END $private$;


-- SOURCE hdn_review_challenge.sql SHA256 dedd8b3dd667e6bc535a6922fdd01bd216dcd08de659c41e1b3360470f28a98f
CREATE OR REPLACE FUNCTION helpdesk_auth.hdnr_invitation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r helpdesk_audit.hdnr_receipts%rowtype;c helpdesk_audit.hdnr_challenges%rowtype;BEGIN
 IF session_user<>'helpdesk_app' OR NOT coalesce(helpdesk_auth.is_human(),false) OR TG_OP='DELETE' THEN RAISE EXCEPTION 'Human qualified invitation command required' USING ERRCODE='HDR03';END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT r FROM helpdesk_audit.hdnr_receipts WHERE(id,workspace_id,account_id,ticket_id,action,transaction_id)=(NEW.receipt_id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,'invitation',pg_current_xact_id());
  IF r.actor_id IS DISTINCT FROM helpdesk_auth.actor_id() OR r.invitation_id<>NEW.id OR r.bundle->'invitation' IS DISTINCT FROM NEW.document OR NEW.revision<>1 THEN RAISE EXCEPTION 'Unqualified invitation insertion' USING ERRCODE='HDR03';END IF;RETURN NEW;
 END IF;
 IF (NEW.id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.receipt_id) IS DISTINCT FROM (OLD.id,OLD.workspace_id,OLD.account_id,OLD.ticket_id,OLD.receipt_id) OR NEW.revision<>OLD.revision+1
  OR OLD.document->>'status'<>'pending' OR NEW.document-'challenge' IS DISTINCT FROM OLD.document-'challenge' OR NEW.document->>'approverId' IS DISTINCT FROM helpdesk_auth.actor_id()::text
 THEN RAISE EXCEPTION 'Invitation identity or command changed' USING ERRCODE='HDR02';END IF;
 SELECT * INTO STRICT c FROM helpdesk_audit.hdnr_challenges WHERE(workspace_id,account_id,ticket_id,invitation_id,generation,actor_id,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,(NEW.document->'challenge'->>'generation')::integer,helpdesk_auth.actor_id(),pg_current_xact_id());
 IF c.generation<>coalesce((OLD.document->'challenge'->>'generation')::integer,0)+1 OR c.challenge_hash IS DISTINCT FROM NEW.document->'challenge'->>'hash'
  OR c.target_hash IS DISTINCT FROM NEW.document->>'targetHash' OR c.expires_at<>helpdesk_auth.hdn_notification_stamp(NEW.document->'challenge'->>'expiresAt') OR c.expires_at<=clock_timestamp()
 THEN RAISE EXCEPTION 'Qualified current challenge required' USING ERRCODE='HDR02';END IF;RETURN NEW;
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Invitation proof required' USING ERRCODE='HDR03';END$$;
CREATE FUNCTION helpdesk_auth.hdnr_challenge(proposed jsonb,expected integer) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE row helpdesk_core.hdnr_invitations%rowtype;a jsonb;q jsonb:=proposed->'challenge';ctx jsonb;now_stamp timestamptz:=clock_timestamp();until_stamp timestamptz;affected integer;BEGIN
 SELECT * INTO row FROM helpdesk_core.hdnr_invitations WHERE workspace_id=helpdesk_auth.workspace_id() AND id=(proposed->>'id')::uuid FOR UPDATE;
 IF NOT FOUND OR row.document->>'approverId' IS DISTINCT FROM helpdesk_auth.actor_id()::text THEN RAISE EXCEPTION 'Invitation belongs to another person' USING ERRCODE='HDR01';END IF;
 ctx:=helpdesk_auth.hdnr_context(row.ticket_id);PERFORM helpdesk_auth.hdnr_grant(row.ticket_id,'approvals.decide',ctx);a:=helpdesk_auth.hdnr_aggregate(row.ticket_id)->'aggregate';
 IF row.document->>'status'<>'pending' OR a->'ticket'->>'approval'<>'pending' OR a->'ticket'->>'status' NOT IN ('new','triage') OR row.document->'ticketVersion' IS DISTINCT FROM a->'ticket'->'version'
  OR row.document->'formRevision' IS DISTINCT FROM a->'form'->'revision' OR row.document->>'targetHash' IS DISTINCT FROM helpdesk_auth.hdnr_target_hash(a)
  OR row.document->'policyVersionId' IS DISTINCT FROM a->'approvalPolicy'->'versionId' OR row.document->>'approverId' IN (a->>'requesterId',a->'ticket'->>'createdBy')
  OR helpdesk_auth.hdn_notification_stamp(row.document->>'createdAt')>now_stamp OR helpdesk_auth.hdn_notification_stamp(row.document->>'expiresAt')<=now_stamp
 THEN RAISE EXCEPTION 'Invitation target changed or expired' USING ERRCODE='HDR02';END IF;
 IF expected IS NULL OR expected NOT BETWEEN 0 AND 2147483646 OR expected<>coalesce((row.document->'challenge'->>'generation')::integer,0)
  OR proposed-'challenge' IS DISTINCT FROM row.document-'challenge' OR NOT coalesce(helpdesk_auth.hdn_cfg_object(q,ARRAY['hash','generation','expiresAt']),false)
  OR jsonb_typeof(q->'hash') IS DISTINCT FROM 'string' OR q->>'hash'!~'^[a-f0-9]{64}$' OR q->'generation' IS DISTINCT FROM to_jsonb(expected+1)
 THEN RAISE EXCEPTION 'Challenge generation changed' USING ERRCODE='HDR02';END IF;
 until_stamp:=helpdesk_auth.hdn_notification_stamp(q->>'expiresAt');
 IF until_stamp<=now_stamp OR until_stamp>least(helpdesk_auth.hdn_notification_stamp(row.document->>'expiresAt'),now_stamp+interval '300 seconds') THEN RAISE EXCEPTION 'Challenge expiry invalid' USING ERRCODE='HDR02';END IF;
 INSERT INTO helpdesk_audit.hdnr_challenges(workspace_id,account_id,ticket_id,invitation_id,generation,actor_id,challenge_hash,expires_at,created_at,target_hash) VALUES(row.workspace_id,row.account_id,row.ticket_id,row.id,expected+1,helpdesk_auth.actor_id(),q->>'hash',until_stamp,now_stamp,row.document->>'targetHash');
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Challenge proof suppressed' USING ERRCODE='HDR03';END IF;
 UPDATE helpdesk_core.hdnr_invitations SET document=proposed,revision=revision+1 WHERE id=row.id AND workspace_id=row.workspace_id AND revision=row.revision;
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Challenge update suppressed' USING ERRCODE='HDR02';END IF;
 IF NOT EXISTS(SELECT 1 FROM helpdesk_core.hdnr_invitations WHERE id=row.id AND document=proposed AND revision=row.revision+1) THEN RAISE EXCEPTION 'Challenge persistence changed' USING ERRCODE='HDR03';END IF;
 RETURN proposed;
EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'Invalid private challenge' USING ERRCODE='HDR03';END$$;
CREATE FUNCTION helpdesk_auth.hdnr_challenge_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE row helpdesk_core.hdnr_invitations%rowtype;a jsonb;BEGIN
 IF session_user<>'helpdesk_app' OR NEW.transaction_id<>pg_current_xact_id() OR NEW.workspace_id IS DISTINCT FROM helpdesk_auth.workspace_id() OR NEW.actor_id IS DISTINCT FROM helpdesk_auth.actor_id() OR NEW.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Current challenge command required' USING ERRCODE='HDR03';END IF;
 PERFORM helpdesk_auth.hdnr_grant(NEW.ticket_id,'approvals.decide',helpdesk_auth.hdnr_context(NEW.ticket_id));
 SELECT * INTO STRICT row FROM helpdesk_core.hdnr_invitations WHERE(workspace_id,account_id,ticket_id,id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.invitation_id);
 a:=helpdesk_auth.hdnr_aggregate(NEW.ticket_id)->'aggregate';
 IF row.document->>'status'<>'pending' OR row.document->>'approverId'<>NEW.actor_id::text OR row.document->>'targetHash'<>NEW.target_hash OR NEW.target_hash<>helpdesk_auth.hdnr_target_hash(a)
  OR row.document->'challenge' IS DISTINCT FROM jsonb_build_object('hash',NEW.challenge_hash,'generation',NEW.generation,'expiresAt',row.document->'challenge'->'expiresAt')
  OR helpdesk_auth.hdn_notification_stamp(row.document->'challenge'->>'expiresAt')<>NEW.expires_at THEN RAISE EXCEPTION 'Challenge effects incomplete' USING ERRCODE='HDR03';END IF;RETURN NULL;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Challenge invitation missing' USING ERRCODE='HDR03';END$$;
CREATE CONSTRAINT TRIGGER hdnr_challenge_complete AFTER INSERT ON helpdesk_audit.hdnr_challenges DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdnr_challenge_complete();
DO $private$ DECLARE role_name text;BEGIN
 REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_challenge(jsonb,integer),helpdesk_auth.hdnr_challenge_complete() FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_challenge(jsonb,integer),helpdesk_auth.hdnr_challenge_complete() FROM %I',role_name);END IF;
 END LOOP;
 GRANT EXECUTE ON FUNCTION helpdesk_auth.hdnr_challenge(jsonb,integer) TO helpdesk_app;
END $private$;


