DECLARE r helpdesk_audit.hdnr_receipts%rowtype;c helpdesk_audit.hdnr_challenges%rowtype;BEGIN
 IF session_user<>'helpdesk_app' OR NOT coalesce(helpdesk_auth.is_human(),false) OR TG_OP='DELETE' THEN RAISE EXCEPTION 'Human qualified invitation command required' USING ERRCODE='HDR03';END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT r FROM helpdesk_audit.hdnr_receipts WHERE(id,workspace_id,account_id,ticket_id,action,transaction_id)=(NEW.receipt_id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,'invitation',pg_current_xact_id());
  IF r.actor_id IS DISTINCT FROM helpdesk_auth.actor_id() OR r.invitation_id<>NEW.id OR r.bundle->'invitation' IS DISTINCT FROM NEW.document OR NEW.revision<>1 THEN RAISE EXCEPTION 'Unqualified invitation insertion' USING ERRCODE='HDR03';END IF;RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.receipt_id) IS NOT DISTINCT FROM (OLD.id,OLD.workspace_id,OLD.account_id,OLD.ticket_id,OLD.receipt_id)
  AND NEW.revision=OLD.revision+1 AND OLD.document->>'status'='pending' AND NEW.document=OLD.document||jsonb_build_object('status','used') AND OLD.document->>'approverId'=helpdesk_auth.actor_id()::text THEN
  SELECT * INTO STRICT r FROM helpdesk_audit.hdnr_receipts WHERE(workspace_id,account_id,ticket_id,invitation_id,actor_id,action,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,helpdesk_auth.actor_id(),'approval',pg_current_xact_id());
  IF r.bundle->'decision'->'challengeGeneration' IS DISTINCT FROM OLD.document->'challenge'->'generation' OR r.result->'version' IS DISTINCT FROM to_jsonb((OLD.document->>'ticketVersion')::integer+1) OR r.result->'formRevision' IS DISTINCT FROM OLD.document->'formRevision' THEN RAISE EXCEPTION 'Approval invitation consumption changed' USING ERRCODE='HDR02';END IF;RETURN NEW;
 END IF;
 IF (NEW.id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.receipt_id) IS DISTINCT FROM (OLD.id,OLD.workspace_id,OLD.account_id,OLD.ticket_id,OLD.receipt_id) OR NEW.revision<>OLD.revision+1
  OR OLD.document->>'status'<>'pending' OR NEW.document-'challenge' IS DISTINCT FROM OLD.document-'challenge' OR NEW.document->>'approverId' IS DISTINCT FROM helpdesk_auth.actor_id()::text
 THEN RAISE EXCEPTION 'Invitation identity or command changed' USING ERRCODE='HDR02';END IF;
 SELECT * INTO STRICT c FROM helpdesk_audit.hdnr_challenges WHERE(workspace_id,account_id,ticket_id,invitation_id,generation,actor_id,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,(NEW.document->'challenge'->>'generation')::integer,helpdesk_auth.actor_id(),pg_current_xact_id());
 IF c.generation<>coalesce((OLD.document->'challenge'->>'generation')::integer,0)+1 OR c.challenge_hash IS DISTINCT FROM NEW.document->'challenge'->>'hash'
  OR c.target_hash IS DISTINCT FROM NEW.document->>'targetHash' OR c.expires_at<>helpdesk_auth.hdn_notification_stamp(NEW.document->'challenge'->>'expiresAt') OR c.expires_at<=clock_timestamp()
 THEN RAISE EXCEPTION 'Qualified current challenge required' USING ERRCODE='HDR02';END IF;RETURN NEW;
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Invitation proof required' USING ERRCODE='HDR03';END$$;

CREATE FUNCTION helpdesk_auth.hdnr_receipt(key text) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE row helpdesk_audit.hdnr_receipts%rowtype;BEGIN
 IF session_user<>'helpdesk_app' OR NOT coalesce(helpdesk_auth.is_human(),false) OR key IS NULL OR key!~'^[A-Za-z0-9._:-]{16,128}$' THEN RAISE EXCEPTION 'Invalid private receipt lookup' USING ERRCODE='HDR01';END IF;
 SELECT * INTO row FROM helpdesk_audit.hdnr_receipts WHERE(workspace_id,actor_id,intent_key)=(helpdesk_auth.workspace_id(),helpdesk_auth.actor_id(),key) FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF row.action NOT IN ('approval','revision') THEN RAISE EXCEPTION 'Review intent belongs to another action' USING ERRCODE='HDR04';END IF;
 PERFORM helpdesk_auth.hdnr_grant(row.ticket_id,CASE WHEN row.action='approval' THEN 'approvals.decide' ELSE 'forms.revise' END,helpdesk_auth.hdnr_context(row.ticket_id));
 RETURN jsonb_build_object('key',row.intent_key,'hash',row.intent_hash,'result',row.result);
END$$;
CREATE FUNCTION helpdesk_auth.hdnr_commit_approval(bundle jsonb,receipt jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE w uuid:=helpdesk_auth.workspace_id();who uuid:=helpdesk_auth.actor_id();target uuid;account uuid;ctx jsonb;a jsonb;t jsonb;i jsonb;decision jsonb:=bundle->'decision';audit_doc jsonb:=bundle->'audit';outbox_doc jsonb:=bundle->'outbox';expected_decision jsonb;after_doc jsonb;event_doc jsonb;expected_audit jsonb;expected_outbox jsonb;result jsonb;
 invitation_uuid uuid;effect_uuid uuid;request_uuid uuid;at_text text;stamp timestamptz;choice text;reason text;kind text;next_status text;next_approval text;expected_version integer;next_version integer;intent_hash text;command_doc jsonb;prior helpdesk_audit.hdnr_receipts%rowtype;affected integer;BEGIN
 IF NOT coalesce(helpdesk_auth.hdn_cfg_object(bundle,ARRAY['expectedVersion','invitationId','decision','clocks','audit','outbox']) AND helpdesk_auth.hdn_cfg_object(receipt,ARRAY['key','hash','result']),false) OR receipt->>'key' IS NULL OR receipt->>'key'!~'^[A-Za-z0-9._:-]{16,128}$' THEN RAISE EXCEPTION 'Invalid approval command' USING ERRCODE='HDR03';END IF;
 target:=(receipt->'result'->>'ticketId')::uuid;ctx:=helpdesk_auth.hdnr_context(target);PERFORM helpdesk_auth.hdnr_grant(target,'approvals.decide',ctx);a:=helpdesk_auth.hdnr_aggregate(target)->'aggregate';t:=a->'ticket';account:=(t->>'accountId')::uuid;
 invitation_uuid:=(bundle->>'invitationId')::uuid;i:=helpdesk_auth.hdnr_invitation(invitation_uuid);
 SELECT * INTO prior FROM helpdesk_audit.hdnr_receipts WHERE(workspace_id,actor_id,intent_key)=(w,who,receipt->>'key') FOR UPDATE;
 IF FOUND THEN IF prior.action<>'approval' OR prior.intent_hash IS DISTINCT FROM receipt->>'hash' OR prior.result IS DISTINCT FROM receipt->'result' OR prior.ticket_id<>target OR prior.invitation_id<>invitation_uuid THEN RAISE EXCEPTION 'Review idempotency conflict' USING ERRCODE='HDR04';END IF;RETURN prior.result;END IF;
 expected_version:=(t->>'version')::integer;next_version:=expected_version+1;choice:=decision->>'decision';reason:=decision->>'reason';at_text:=audit_doc->>'at';stamp:=helpdesk_auth.hdn_notification_stamp(at_text);
 IF i IS NULL OR i->>'approverId'<>who::text OR i->>'ticketId'<>target::text OR i->>'status'<>'pending' OR i->'ticketVersion' IS DISTINCT FROM t->'version' OR i->'formRevision' IS DISTINCT FROM a->'form'->'revision'
  OR i->>'targetHash' IS DISTINCT FROM helpdesk_auth.hdnr_target_hash(a) OR i->'policyVersionId' IS DISTINCT FROM a->'approvalPolicy'->'versionId' OR who::text IN (a->>'requesterId',t->>'createdBy')
  OR t->>'approval'<>'pending' OR t->>'status' NOT IN ('new','triage') OR bundle->'expectedVersion' IS DISTINCT FROM t->'version' OR i->'challenge'='null'::jsonb
  OR decision->'challengeGeneration' IS DISTINCT FROM i->'challenge'->'generation' OR helpdesk_auth.hdn_notification_stamp(i->>'expiresAt')<=clock_timestamp() OR helpdesk_auth.hdn_notification_stamp(i->'challenge'->>'expiresAt')<=clock_timestamp()
 THEN RAISE EXCEPTION 'Approval target or challenge changed' USING ERRCODE='HDR02';END IF;
 IF choice IS NULL OR choice NOT IN ('approve','reject') OR jsonb_typeof(decision->'reason') IS DISTINCT FROM 'string' OR length(helpdesk_auth.hdni_trim(reason))=0 OR octet_length(helpdesk_auth.hdni_utf16(reason))/2>12000
  OR translate(reason,E'\t\n\r','')~'[\u0001-\u001f\u007f]' OR stamp>clock_timestamp() OR stamp<clock_timestamp()-interval '30 seconds' OR stamp<helpdesk_auth.hdn_notification_stamp(t->>'lastEventAt')
 THEN RAISE EXCEPTION 'Invalid approval decision or time' USING ERRCODE='HDR03';END IF;
 intent_hash:=helpdesk_auth.hdni_digest(jsonb_build_object('actorId',who,'workspaceId',w,'command',jsonb_build_object('ticketId',target,'invitationId',invitation_uuid,'expectedVersion',expected_version,'expectedFormRevision',a->'form'->'revision','token',i->'challenge'->'hash','decision',choice,'reason',reason)));
 IF receipt->>'hash' IS DISTINCT FROM intent_hash THEN RAISE EXCEPTION 'Approval challenge receipt mismatch' USING ERRCODE='HDR04';END IF;
 effect_uuid:=(audit_doc->>'id')::uuid;request_uuid:=(audit_doc->>'requestId')::uuid;
 next_status:=CASE WHEN choice='approve' THEN a->'approvalPolicy'->>'onApproved' ELSE a->'approvalPolicy'->>'onRejected' END;next_approval:=CASE WHEN choice='approve' THEN 'approved' ELSE 'pending' END;kind:=CASE WHEN choice='approve' THEN 'approval_granted' ELSE 'approval_rejected' END;
 after_doc:=t||jsonb_build_object('approval',next_approval,'status',next_status,'version',next_version,'updatedAt',at_text,'lastEventAt',at_text);
 event_doc:=jsonb_build_object('ticketId',target,'workspaceId',w,'profileVersionId',t->'profileVersionId','sequence',next_version,'at',at_text,'type',kind,'actorId',who,'actorKind','human_agent','from',t->'status','to',next_status);
 expected_decision:=jsonb_build_object('after',after_doc,'event',event_doc,'invitationId',invitation_uuid,'challengeGeneration',i->'challenge'->'generation','reason',reason,'decision',choice,'originPermissionGranted',false,'originExecution',CASE WHEN choice='approve' THEN 'pending_manual_action' ELSE 'not_requested' END);
 expected_audit:=jsonb_build_object('id',effect_uuid,'actorId',who,'workspaceId',w,'ticketId',target,'requestId',request_uuid,'at',at_text,'action','approval.'||choice,'invitationId',invitation_uuid,'formRevision',a->'form'->'revision','reason',reason,'capability','approvals.decide','originPermissionGranted',false);
 expected_outbox:=jsonb_build_object('id',effect_uuid,'workspaceId',w,'accountId',account,'ticketId',target,'type','support.'||kind,'version',next_version,'requestId',request_uuid,'createdAt',at_text);
 result:=jsonb_build_object('ticketId',target,'workspaceId',w,'accountId',account,'actorId',who,'eventId',effect_uuid,'version',next_version,'formRevision',a->'form'->'revision','action','approval','invitationId',invitation_uuid,'decision',choice,'notification','pending','replayed',false);
 IF decision IS DISTINCT FROM expected_decision OR audit_doc IS DISTINCT FROM expected_audit OR outbox_doc IS DISTINCT FROM expected_outbox OR receipt->'result' IS DISTINCT FROM result
  OR NOT coalesce(helpdesk_auth.hdn_cfg_object(bundle->'clocks',ARRAY['ticketId','workspaceId','sourceVersion','policyVersionId','calendarVersionId','asOf','firstResponse','solution']),false)
  OR bundle->'clocks'->>'ticketId'<>target::text OR bundle->'clocks'->>'workspaceId'<>w::text OR bundle->'clocks'->'sourceVersion'<>to_jsonb(next_version) OR bundle->'clocks'->>'asOf'<>at_text
  OR bundle->'clocks'->'policyVersionId'<>a->'profile'->'sla'->'versionId' OR bundle->'clocks'->'calendarVersionId'<>a->'profile'->'sla'->'calendar'->'versionId'
 THEN RAISE EXCEPTION 'Approval bundle changed' USING ERRCODE='HDR02';END IF;
 INSERT INTO helpdesk_audit.hdnr_receipts(id,workspace_id,account_id,ticket_id,actor_id,intent_key,intent_hash,action,invitation_id,result,bundle,scope,request_id,created_at) VALUES(effect_uuid,w,account,target,who,receipt->>'key',intent_hash,'approval',invitation_uuid,result,bundle,ctx,request_uuid,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Approval receipt suppressed' USING ERRCODE='HDR03';END IF;
 command_doc:=jsonb_build_object('action','approval','expectedVersion',expected_version,'invitationId',invitation_uuid,'expectedFormRevision',a->'form'->'revision','decision',choice,'challengeGeneration',i->'challenge'->'generation');
 INSERT INTO helpdesk_audit.hdn_workflow_commits(workspace_id,account_id,ticket_id,event_id,actor_id,profile_version_id,from_version,to_version,from_status,to_status,core_type,intent_key,intent_hash,command,public_event,audit,result,at)
 VALUES(w,account,target,effect_uuid,who,t->>'profileVersionId',expected_version,next_version,t->>'status',next_status,'ticket.status_changed',receipt->>'key',intent_hash,command_doc,event_doc,expected_audit,result,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Approval workflow proof suppressed' USING ERRCODE='HDR03';END IF;
 UPDATE helpdesk_core.tickets SET status=next_status,version=next_version,updated_at=stamp WHERE(workspace_id,account_id,id,version)=(w,account,target,expected_version);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Approval ticket revision changed' USING ERRCODE='HDR02';END IF;
 UPDATE helpdesk_core.hdn_workflow_state SET approval=next_approval,last_event_at=stamp WHERE(workspace_id,account_id,ticket_id)=(w,account,target);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Approval metadata suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_core.ticket_events(id,workspace_id,account_id,ticket_id,actor_id,type,customer_visible,data,created_at) VALUES(effect_uuid,w,account,target,who,'ticket.status_changed',true,jsonb_build_object('from',t->'status','to',next_status,'reason','Aprovação registrada no Help Desk.'),stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Approval core event suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_audit.audit_events(workspace_id,id,principal_id,action,resource_id,request_id,created_at) VALUES(w,effect_uuid,who,'approval.'||choice,target,request_uuid::text,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Approval audit suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_integration.outbox_events(id,workspace_id,account_id,ticket_id,type,payload,request_id,created_at) VALUES(effect_uuid,w,account,target,'ticket.status_changed',jsonb_build_object('specversion','1.0','id',effect_uuid,'source','helpdesk/workspaces/'||w::text,'type','com.helpdesk.ticket.status_changed.v1','subject','tickets/'||target::text,'datacontenttype','application/json','time',at_text,'data',jsonb_build_object('ticket_id',target,'version',next_version)),request_uuid::text,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Approval external header suppressed' USING ERRCODE='HDR03';END IF;
 UPDATE helpdesk_core.hdnr_invitations SET document=jsonb_set(document,'{status}','"used"'),revision=revision+1 WHERE id=invitation_uuid AND workspace_id=w AND document=i;
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Approval invitation changed' USING ERRCODE='HDR02';END IF;
 INSERT INTO helpdesk_integration.hdnr_sources(id,workspace_id,account_id,ticket_id,receipt_id,kind,source_version,invitation_id,request_id,created_at) VALUES(effect_uuid,w,account,target,effect_uuid,'support.'||kind,next_version,NULL,request_uuid,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Approval notification source suppressed' USING ERRCODE='HDR03';END IF;
 RETURN result;
EXCEPTION WHEN data_exception OR no_data_found THEN RAISE EXCEPTION 'Invalid private approval command' USING ERRCODE='HDR03';END$$;

-- The invitation guard extension and complete effect validator are composed
-- separately below before this candidate can be qualified or activated.

CREATE OR REPLACE FUNCTION helpdesk_auth.hdnr_receipt_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE source helpdesk_integration.hdnr_sources%rowtype;invitation helpdesk_core.hdnr_invitations%rowtype;c helpdesk_audit.hdn_workflow_commits%rowtype;
 a jsonb;actual_ticket jsonb;before_target jsonb;d jsonb:=NEW.bundle->'decision';expected_payload jsonb;BEGIN
 IF session_user<>'helpdesk_app' OR NEW.transaction_id<>pg_current_xact_id() OR NEW.workspace_id IS DISTINCT FROM helpdesk_auth.workspace_id() OR NEW.actor_id IS DISTINCT FROM helpdesk_auth.actor_id() THEN RAISE EXCEPTION 'Unqualified review receipt' USING ERRCODE='HDR03';END IF;
 SELECT * INTO STRICT source FROM helpdesk_integration.hdnr_sources WHERE(id,workspace_id,account_id,ticket_id,receipt_id)=(NEW.id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id);
 SELECT * INTO STRICT invitation FROM helpdesk_core.hdnr_invitations WHERE(id,workspace_id,account_id,ticket_id)=(NEW.invitation_id,NEW.workspace_id,NEW.account_id,NEW.ticket_id);
 IF source.created_at<>NEW.created_at OR source.request_id<>NEW.request_id THEN RAISE EXCEPTION 'Review source correlation changed' USING ERRCODE='HDR03';END IF;
 IF NEW.action='invitation' THEN
  PERFORM helpdesk_auth.hdnr_grant(NEW.ticket_id,'approvals.request',NEW.scope);
  IF source.kind<>'support.approval_requested' OR source.invitation_id<>NEW.invitation_id OR source.source_version<>(NEW.result->>'ticketVersion')::integer
   OR invitation.receipt_id<>NEW.id OR invitation.document IS DISTINCT FROM NEW.bundle->'invitation'
   OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.audit_events e WHERE(e.workspace_id,e.id,e.principal_id,e.action,e.resource_id,e.request_id,e.created_at)=(NEW.workspace_id,NEW.id,NEW.actor_id,'approval.requested',NEW.ticket_id,NEW.request_id::text,NEW.created_at))
  THEN RAISE EXCEPTION 'Invitation effects incomplete' USING ERRCODE='HDR03';END IF;
 ELSIF NEW.action='approval' THEN
  PERFORM helpdesk_auth.hdnr_grant(NEW.ticket_id,'approvals.decide',NEW.scope);a:=helpdesk_auth.hdnr_aggregate(NEW.ticket_id)->'aggregate';actual_ticket:=a->'ticket';
  IF source.kind IS DISTINCT FROM 'support.'||(d->'event'->>'type') OR source.invitation_id IS NOT NULL OR source.source_version<>(NEW.result->>'version')::integer
   OR invitation.document->>'status'<>'used' OR invitation.document->>'approverId'<>NEW.actor_id::text OR invitation.document->'ticketVersion'<>to_jsonb(source.source_version-1)
   OR invitation.document->'formRevision'<>NEW.result->'formRevision' OR invitation.document->'challenge'->'generation'<>d->'challengeGeneration'
   OR helpdesk_auth.hdn_notification_stamp(invitation.document->'challenge'->>'expiresAt')<=clock_timestamp()
   OR actual_ticket->'version'<>NEW.result->'version' OR a->'form'->'revision'<>NEW.result->'formRevision'
   OR (actual_ticket||jsonb_build_object('updatedAt',d->'after'->'updatedAt','lastEventAt',d->'after'->'lastEventAt')) IS DISTINCT FROM d->'after'
   OR helpdesk_auth.hdn_notification_stamp(actual_ticket->>'updatedAt')<>NEW.created_at OR helpdesk_auth.hdn_notification_stamp(actual_ticket->>'lastEventAt')<>NEW.created_at
  THEN RAISE EXCEPTION 'Approval state or invitation effect incomplete' USING ERRCODE='HDR03';END IF;
  before_target:=a||jsonb_build_object('ticket',actual_ticket||jsonb_build_object('version',source.source_version-1));
  IF invitation.document->>'targetHash'<>helpdesk_auth.hdnr_target_hash(before_target) THEN RAISE EXCEPTION 'Approval target pin changed' USING ERRCODE='HDR03';END IF;
  SELECT * INTO STRICT c FROM helpdesk_audit.hdn_workflow_commits WHERE(workspace_id,account_id,ticket_id,event_id,actor_id,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,NEW.actor_id,NEW.transaction_id);
  IF c.intent_key<>NEW.intent_key OR c.intent_hash<>NEW.intent_hash OR c.result IS DISTINCT FROM NEW.result OR c.public_event IS DISTINCT FROM d->'event' OR c.audit IS DISTINCT FROM NEW.bundle->'audit'
   OR c.core_type<>'ticket.status_changed' OR c.from_version<>source.source_version-1 OR c.to_version<>source.source_version OR c.from_status<>d->'event'->>'from' OR c.to_status<>d->'event'->>'to' OR c.at<>NEW.created_at
   OR c.command IS DISTINCT FROM jsonb_build_object('action','approval','expectedVersion',c.from_version,'invitationId',NEW.invitation_id,'expectedFormRevision',NEW.result->'formRevision','decision',d->'decision','challengeGeneration',d->'challengeGeneration')
   OR NOT EXISTS(SELECT 1 FROM helpdesk_core.ticket_events e JOIN helpdesk_audit.write_effects f ON(f.workspace_id,f.event_id)=(e.workspace_id,e.id)
    WHERE(e.workspace_id,e.account_id,e.ticket_id,e.id,e.actor_id,e.type,e.created_at)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,NEW.actor_id,'ticket.status_changed',NEW.created_at)
     AND e.customer_visible AND f.applied AND f.transaction_id=NEW.transaction_id AND f.ticket_version=c.to_version AND f.kind=e.type
     AND e.data-'reason'=f.expected_data AND f.expected_data=jsonb_build_object('from',c.from_status,'to',c.to_status))
   OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.audit_events e WHERE(e.workspace_id,e.id,e.principal_id,e.action,e.resource_id,e.request_id,e.created_at)=(NEW.workspace_id,NEW.id,NEW.actor_id,NEW.bundle->'audit'->>'action',NEW.ticket_id,NEW.request_id::text,NEW.created_at))
  THEN RAISE EXCEPTION 'Approval functional event or audit incomplete' USING ERRCODE='HDR03';END IF;
  expected_payload:=jsonb_build_object('specversion','1.0','id',NEW.id,'source','helpdesk/workspaces/'||NEW.workspace_id::text,'type','com.helpdesk.ticket.status_changed.v1','subject','tickets/'||NEW.ticket_id::text,'datacontenttype','application/json','time',NEW.bundle->'outbox'->'createdAt','data',jsonb_build_object('ticket_id',NEW.ticket_id,'version',source.source_version));
  IF NOT EXISTS(SELECT 1 FROM helpdesk_integration.outbox_events e WHERE(e.workspace_id,e.account_id,e.ticket_id,e.id,e.type,e.request_id,e.created_at)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,'ticket.status_changed',NEW.request_id::text,NEW.created_at) AND e.payload=expected_payload) THEN RAISE EXCEPTION 'Approval external header incomplete' USING ERRCODE='HDR03';END IF;
 ELSE RAISE EXCEPTION 'Review receipt action not yet qualified' USING ERRCODE='HDR03';END IF;
 RETURN NULL;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Review receipt effects missing' USING ERRCODE='HDR03';END$$;
DO $private$ DECLARE role_name text;BEGIN
 REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_receipt(text),helpdesk_auth.hdnr_commit_approval(jsonb,jsonb) FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_receipt(text),helpdesk_auth.hdnr_commit_approval(jsonb,jsonb) FROM %I',role_name);END IF;
 END LOOP;
 GRANT EXECUTE ON FUNCTION helpdesk_auth.hdnr_receipt(text),helpdesk_auth.hdnr_commit_approval(jsonb,jsonb) TO helpdesk_app;
END $private$;



-- SOURCE hdn_review_authority_lock.sql SHA256 3455ebf81767239eeccf64da5d927e5ad523b72e21e4a569d046de5083c25959
-- Authority changes are rare; one workspace latch prevents append-only history
-- from overtaking a qualified command without introducing cross-key deadlocks.
CREATE FUNCTION helpdesk_auth.hdnr_authority_read(w uuid) RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF w IS NULL THEN RAISE EXCEPTION 'Review workspace required' USING ERRCODE='HDR01';END IF;
 IF session_user='helpdesk_notification_worker' THEN PERFORM helpdesk_auth.hdn_notification_worker();
 ELSIF session_user<>'helpdesk_app' OR w IS DISTINCT FROM helpdesk_auth.workspace_id() OR NOT coalesce(helpdesk_auth.is_human(),false) THEN RAISE EXCEPTION 'Qualified review session required' USING ERRCODE='HDR01';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('helpdesk-review-authority:'||w::text,0));
END$$;
CREATE FUNCTION helpdesk_auth.hdnr_authority_publish() RETURNS trigger LANGUAGE plpgsql VOLATILE SET search_path='' AS $$
DECLARE prior_revision bigint;BEGIN
 PERFORM helpdesk_auth.cg_local_operator();PERFORM pg_advisory_xact_lock(hashtextextended('helpdesk-review-authority:'||NEW.workspace_id::text,0));
 IF TG_TABLE_NAME='hdnr_grants' THEN
  SELECT coalesce(max(revision),0) INTO prior_revision FROM helpdesk_auth.hdnr_grants WHERE(workspace_id,account_id,principal_id,capability)=(NEW.workspace_id,NEW.account_id,NEW.principal_id,NEW.capability);
  IF NEW.revision<>prior_revision+1 THEN RAISE EXCEPTION 'Review capability revision changed' USING ERRCODE='HDR02';END IF;
 ELSIF TG_TABLE_NAME='hdnr_rosters' THEN
  SELECT coalesce(max(revision),0) INTO prior_revision FROM helpdesk_auth.hdnr_rosters WHERE(workspace_id,account_id,profile_version_id)=(NEW.workspace_id,NEW.account_id,NEW.profile_version_id);
  IF NEW.revision<>prior_revision+1 THEN RAISE EXCEPTION 'Approver roster revision changed' USING ERRCODE='HDR02';END IF;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER hdnr_authority_publication BEFORE INSERT ON helpdesk_core.hdnr_policies FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdnr_authority_publish();
CREATE TRIGGER hdnr_authority_publication BEFORE INSERT ON helpdesk_core.hdnr_profiles FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdnr_authority_publish();
CREATE TRIGGER hdnr_authority_publication BEFORE INSERT ON helpdesk_auth.hdnr_grants FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdnr_authority_publish();
CREATE TRIGGER hdnr_authority_publication BEFORE INSERT ON helpdesk_auth.hdnr_rosters FOR EACH ROW EXECUTE FUNCTION helpdesk_auth.hdnr_authority_publish();
DO $private$ DECLARE role_name text;BEGIN
 REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_authority_read(uuid),helpdesk_auth.hdnr_authority_publish() FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_authority_read(uuid),helpdesk_auth.hdnr_authority_publish() FROM %I',role_name);END IF;
 END LOOP;
END $private$;


CREATE OR REPLACE FUNCTION helpdesk_auth.hdnr_aggregate(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE current_doc jsonb;s helpdesk_core.hdni_snapshots%rowtype;r helpdesk_audit.hdni_receipts%rowtype;p helpdesk_core.hdnr_profiles%rowtype;policy helpdesk_core.hdnr_policies%rowtype;
 f helpdesk_core.hdnr_forms%rowtype;form_doc jsonb;events jsonb;event_count integer;distinct_count integer;w uuid:=helpdesk_auth.workspace_id();who uuid:=helpdesk_auth.actor_id();BEGIN
 PERFORM helpdesk_auth.hdnr_authority_read(helpdesk_auth.workspace_id());
 current_doc:=helpdesk_auth.hdn_read_support_workflow(target);
 IF current_doc IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO STRICT s FROM helpdesk_core.hdni_snapshots WHERE(workspace_id,account_id,ticket_id)=(w,(current_doc->'ticket'->>'accountId')::uuid,target) FOR SHARE;
 SELECT * INTO STRICT r FROM helpdesk_audit.hdni_receipts WHERE(workspace_id,account_id,ticket_id)=(s.workspace_id,s.account_id,target) FOR SHARE;
 IF r.snapshot_hash<>helpdesk_auth.hdni_digest(s.document) OR r.result IS DISTINCT FROM s.document->'receipt' THEN RAISE EXCEPTION 'Original review snapshot changed' USING ERRCODE='HDR03';END IF;
 SELECT * INTO STRICT p FROM helpdesk_core.hdnr_profiles WHERE(workspace_id,account_id,profile_version_id)=(w,s.account_id,current_doc->'ticket'->>'profileVersionId') FOR SHARE;
 IF s.document->'profile'->>'profileVersionId'<>p.profile_version_id OR s.document->'bundle'->'form'->>'schemaHash'<>p.schema_hash OR helpdesk_auth.hdni_digest(s.document->'profile'->'form')<>p.schema_hash
  OR s.document->'profile'->'approvalRequired'='true'::jsonb AND NOT (s.document->'bundle'->>'requesterId')::uuid=ANY(p.required_for)
 THEN RAISE EXCEPTION 'Pinned review profile changed' USING ERRCODE='HDR03';END IF;
 SELECT * INTO STRICT policy FROM helpdesk_core.hdnr_policies WHERE(workspace_id,account_id,version_id)=(w,s.account_id,p.policy_version_id) FOR SHARE;
 form_doc:=s.document->'bundle'->'form'||jsonb_build_object('revision',1,'draftId',s.document->'bundle'->'draftId','draftRevision',s.document->'draft'->'revision');
 SELECT * INTO f FROM helpdesk_core.hdnr_forms WHERE(workspace_id,account_id,ticket_id)=(w,s.account_id,target) ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF FOUND THEN
  IF f.sha256<>helpdesk_auth.hdni_digest(f.document) OR f.source_version>(current_doc->'ticket'->>'version')::integer OR (SELECT count(*) FROM helpdesk_core.hdnr_forms WHERE(workspace_id,account_id,ticket_id)=(w,s.account_id,target))<>f.revision-1 THEN RAISE EXCEPTION 'Review form history incomplete' USING ERRCODE='HDR03';END IF;
  form_doc:=f.document;
 END IF;
 IF form_doc->>'schemaHash'<>p.schema_hash OR form_doc->>'formId'<>p.form_id::text OR form_doc->'formVersion'<>to_jsonb(p.form_version) THEN RAISE EXCEPTION 'Review form pin changed' USING ERRCODE='HDR03';END IF;
 SELECT jsonb_agg(value ORDER BY (value->>'sequence')::integer),count(*),count(DISTINCT(value->>'sequence')::integer) INTO events,event_count,distinct_count FROM (
  SELECT s.document->'bundle'->'event' value UNION ALL SELECT public_event FROM helpdesk_audit.hdn_workflow_commits WHERE(workspace_id,account_id,ticket_id)=(w,s.account_id,target)) stream;
 IF event_count<>(current_doc->'ticket'->>'version')::integer OR distinct_count<>event_count OR EXISTS(SELECT 1 FROM jsonb_array_elements(events) e WHERE e->>'profileVersionId'<>p.profile_version_id OR e->>'ticketId'<>target::text OR e->>'workspaceId'<>w::text OR (e->>'sequence')::integer NOT BETWEEN 1 AND event_count) THEN RAISE EXCEPTION 'Review workflow history incomplete' USING ERRCODE='HDR03';END IF;
 RETURN jsonb_build_object('principalId',who,'aggregate',jsonb_build_object('ticket',current_doc->'ticket','requesterId',s.document->'bundle'->'requesterId','protocol',s.document->'bundle'->'protocol','refs',s.document->'bundle'->'resourceScope'->'refs','form',form_doc,'profile',s.document->'profile','approvalPolicy',policy.document,'events',events));
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Pinned review aggregate unavailable' USING ERRCODE='HDR03';WHEN SQLSTATE 'HDW01' THEN RAISE EXCEPTION 'Review ticket access denied' USING ERRCODE='HDR01';END$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdnr_grant(target uuid,cap text,ctx jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE aggregate_doc jsonb;g helpdesk_auth.hdnr_grants%rowtype;roster helpdesk_auth.hdnr_rosters%rowtype;ref jsonb;w uuid:=helpdesk_auth.workspace_id();who uuid:=helpdesk_auth.actor_id();a uuid;BEGIN
 PERFORM helpdesk_auth.hdnr_authority_read(helpdesk_auth.workspace_id());
 PERFORM helpdesk_auth.hdni_lock_scope(ctx);
 IF session_user<>'helpdesk_app' OR ctx->>'operation'<>'tickets.write' OR cap NOT IN ('forms.revise','approvals.request','approvals.decide') THEN RAISE EXCEPTION 'Review write capability required' USING ERRCODE='HDR05';END IF;
 aggregate_doc:=helpdesk_auth.hdnr_aggregate(target)->'aggregate';a:=(aggregate_doc->'ticket'->>'accountId')::uuid;
 IF a::text IS DISTINCT FROM ctx->>'accountId' OR helpdesk_auth.hdni_refs_key(aggregate_doc->'refs') IS DISTINCT FROM helpdesk_auth.hdni_refs_key(ctx->'refs') THEN RAISE EXCEPTION 'Review resource scope changed' USING ERRCODE='HDR01';END IF;
 SELECT * INTO g FROM helpdesk_auth.hdnr_grants WHERE(workspace_id,account_id,principal_id,capability)=(w,a,who,cap) ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF NOT FOUND OR NOT g.active OR g.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Current review capability required' USING ERRCODE='HDR05';END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(ctx->'refs') LOOP
  IF ref->>'type'<>'work' OR NOT (ref->>'id')=ANY(g.work_ids) THEN RAISE EXCEPTION 'Review capability does not cover exact work' USING ERRCODE='HDR05';END IF;
 END LOOP;
 IF cap<>'forms.revise' THEN
  PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE workspace_id=w AND principal_id=who AND active AND role='admin' FOR SHARE;
  IF NOT FOUND OR NOT helpdesk_auth.hdnr_operator(w,a,target,who) THEN RAISE EXCEPTION 'Initial approval requires current administrator authority' USING ERRCODE='HDR05';END IF;
 END IF;
 IF cap='approvals.decide' THEN
  SELECT * INTO roster FROM helpdesk_auth.hdnr_rosters WHERE(workspace_id,account_id,profile_version_id)=(w,a,aggregate_doc->'ticket'->>'profileVersionId') ORDER BY revision DESC LIMIT 1 FOR SHARE;
  IF NOT FOUND OR NOT roster.active OR roster.expires_at<=clock_timestamp() OR roster.approver_id<>who THEN RAISE EXCEPTION 'Current approver delegation revoked' USING ERRCODE='HDR05';END IF;
  FOR ref IN SELECT value FROM jsonb_array_elements(ctx->'refs') LOOP
   IF ref->>'type'<>'work' OR NOT(ref->>'id')=ANY(roster.work_ids) THEN RAISE EXCEPTION 'Current approver work delegation revoked' USING ERRCODE='HDR05';END IF;
  END LOOP;
 END IF;
 RETURN jsonb_build_object('principalId',who,'workspaceId',w,'accountId',a,'capability',cap,'scopeHash',helpdesk_auth.hdnr_scope_hash(ctx),'active',true,'revision','review-grant-'||g.revision::text,'expiresAt',helpdesk_auth.hdn_workflow_iso(least(g.expires_at,coalesce(roster.expires_at,g.expires_at))));
END$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdnr_route(target uuid,ctx jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE doc jsonb;roster helpdesk_auth.hdnr_rosters%rowtype;g helpdesk_auth.hdnr_grants%rowtype;ref jsonb;w uuid:=helpdesk_auth.workspace_id();a uuid;BEGIN
 PERFORM helpdesk_auth.hdnr_authority_read(helpdesk_auth.workspace_id());
 PERFORM helpdesk_auth.hdnr_grant(target,'approvals.request',ctx);doc:=helpdesk_auth.hdnr_aggregate(target)->'aggregate';a:=(doc->'ticket'->>'accountId')::uuid;
 SELECT * INTO roster FROM helpdesk_auth.hdnr_rosters WHERE(workspace_id,account_id,profile_version_id)=(w,a,doc->'ticket'->>'profileVersionId') ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF NOT FOUND OR NOT roster.active OR roster.expires_at<=clock_timestamp() OR roster.approver_id::text IN (doc->>'requesterId',doc->'ticket'->>'createdBy') OR NOT helpdesk_auth.hdnr_operator(w,a,target,roster.approver_id) THEN RAISE EXCEPTION 'Exact current approver required' USING ERRCODE='HDR01';END IF;
 PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE workspace_id=w AND principal_id=roster.approver_id AND active AND role='admin' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Initial approver assurance policy requires administrator' USING ERRCODE='HDR01';END IF;
 SELECT * INTO g FROM helpdesk_auth.hdnr_grants WHERE(workspace_id,account_id,principal_id,capability)=(w,a,roster.approver_id,'approvals.decide') ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF NOT FOUND OR NOT g.active OR g.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Approver capability revoked' USING ERRCODE='HDR01';END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(ctx->'refs') LOOP
  IF ref->>'type'<>'work' OR NOT (ref->>'id')=ANY(g.work_ids) OR NOT (ref->>'id')=ANY(roster.work_ids) THEN RAISE EXCEPTION 'Approver work coverage revoked' USING ERRCODE='HDR01';END IF;
 END LOOP;
 RETURN jsonb_build_object('principalId',roster.approver_id,'principalKind','human','workspaceId',w,'accountId',a,'ticketId',target,'policyVersionId',doc->'approvalPolicy'->'versionId','resourceHash',helpdesk_auth.hdni_digest(to_jsonb(helpdesk_auth.hdni_refs_key(ctx->'refs'))),'revision','review-roster-'||roster.revision::text,'active',true,'expiresAt',helpdesk_auth.hdn_workflow_iso(least(roster.expires_at,g.expires_at)));
END$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdnr_context(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE ctx jsonb;BEGIN
 PERFORM helpdesk_auth.hdnr_authority_read(helpdesk_auth.workspace_id());
 IF session_user<>'helpdesk_app' OR NOT coalesce(helpdesk_auth.is_human(),false) OR NOT coalesce(helpdesk_auth.has_scope(helpdesk_auth.workspace_id(),'tickets:read'),false) OR NOT coalesce(helpdesk_auth.has_scope(helpdesk_auth.workspace_id(),'tickets:write'),false) THEN RAISE EXCEPTION 'Human review session required' USING ERRCODE='HDR01';END IF;
 ctx:=helpdesk_auth.cg_lock_ticket_scope(target,'tickets.write')-'ticketId';
 IF ctx IS NULL THEN RAISE EXCEPTION 'Current review work access required' USING ERRCODE='HDR01';END IF;
 PERFORM helpdesk_auth.hdni_lock_scope(ctx);RETURN ctx;
END$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdni_profile(ctx jsonb,form uuid,version integer) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE raw jsonb;binding helpdesk_core.hdnr_profiles%rowtype;policy helpdesk_core.hdnr_policies%rowtype;ref jsonb;BEGIN
 PERFORM helpdesk_auth.hdnr_authority_read(helpdesk_auth.workspace_id());
 raw:=helpdesk_auth.hdni_profile_v024(ctx,form,version);
 SELECT * INTO binding FROM helpdesk_core.hdnr_profiles q WHERE (q.workspace_id,q.account_id,q.form_id,q.form_version)=(helpdesk_auth.workspace_id(),(ctx->>'accountId')::uuid,hdni_profile.form,hdni_profile.version) FOR SHARE;
 IF NOT FOUND OR NOT helpdesk_auth.actor_id()=ANY(binding.required_for) THEN RETURN raw;END IF;
 IF (raw->'record'->>'id')::uuid<>binding.configuration_id OR (raw->'record'->>'version')::integer<>binding.configuration_version OR raw->'record'->>'contentHash'<>binding.configuration_hash THEN RAISE EXCEPTION 'Review configuration changed' USING ERRCODE='HDI05';END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(ctx->'refs') LOOP
  IF ref->>'type'<>'work' OR NOT (ref->>'id')=ANY(binding.work_ids) THEN RAISE EXCEPTION 'Approval form outside published work scope' USING ERRCODE='HDI01';END IF;
 END LOOP;
 SELECT * INTO STRICT policy FROM helpdesk_core.hdnr_policies WHERE (workspace_id,account_id,version_id)=(binding.workspace_id,binding.account_id,binding.policy_version_id) FOR SHARE;
 RETURN raw||jsonb_build_object('review',jsonb_build_object('formId',binding.form_id,'formVersion',binding.form_version,'profileVersionId',binding.profile_version_id,'schemaHash',binding.schema_hash,'configurationHash',binding.configuration_hash,'policyVersionId',binding.policy_version_id,'policyHash',policy.sha256,'approvalRequired',true));
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Published approval policy unavailable' USING ERRCODE='HDI05';END$$;


-- SOURCE hdn_review_revision.sql SHA256 22ebdc9a101f3f9a01e90f590ba31f79b25a1e0032cc4828ae96959e29b56cbb
CREATE FUNCTION helpdesk_auth.hdnr_diff(before_doc jsonb,after_doc jsonb,path_value text,has_before boolean,has_after boolean,depth integer) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE result jsonb:='[]';key text;part jsonb;BEGIN
 IF depth>12 THEN RAISE EXCEPTION 'Review diff depth exceeded' USING ERRCODE='HDR03';END IF;
 IF has_before AND has_after AND before_doc IS NOT DISTINCT FROM after_doc THEN RETURN result;END IF;
 IF has_before AND has_after AND jsonb_typeof(before_doc)='object' AND jsonb_typeof(after_doc)='object' THEN
  FOR key IN SELECT name FROM(SELECT jsonb_object_keys(before_doc) name UNION SELECT jsonb_object_keys(after_doc)) keys ORDER BY helpdesk_auth.hdni_utf16(name) LOOP
   IF jsonb_array_length(result)>=1000 THEN RAISE EXCEPTION 'Review diff bound exceeded' USING ERRCODE='HDR03';END IF;
   part:=helpdesk_auth.hdnr_diff(before_doc->key,after_doc->key,CASE WHEN path_value='' THEN key ELSE path_value||'.'||key END,before_doc ? key,after_doc ? key,depth+1);result:=result||part;
   IF jsonb_array_length(result)>1000 THEN RAISE EXCEPTION 'Review diff bound exceeded' USING ERRCODE='HDR03';END IF;
  END LOOP;RETURN result;
 END IF;
 RETURN jsonb_build_array(jsonb_build_object('path',path_value,'beforePresent',has_before,'afterPresent',has_after,'before',CASE WHEN has_before THEN before_doc ELSE 'null'::jsonb END,'after',CASE WHEN has_after THEN after_doc ELSE 'null'::jsonb END));
END$$;
CREATE FUNCTION helpdesk_auth.hdnr_scoped_revision(w uuid,a uuid,target uuid,before_version integer,after_version integer,prior text,next_status text,destination uuid) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF session_user<>'helpdesk_app' OR w IS DISTINCT FROM helpdesk_auth.workspace_id() OR NOT coalesce(helpdesk_auth.is_human(),false) OR NOT coalesce(helpdesk_auth.cg_ticket_resource_allowed(w,a,target,'tickets.write'),false) THEN RETURN false;END IF;
 RETURN EXISTS(SELECT 1 FROM helpdesk_audit.hdnr_receipts r JOIN helpdesk_audit.hdn_workflow_commits c ON(c.workspace_id,c.account_id,c.ticket_id,c.event_id,c.actor_id,c.transaction_id)=(r.workspace_id,r.account_id,r.ticket_id,r.id,r.actor_id,r.transaction_id)
  WHERE(r.workspace_id,r.account_id,r.ticket_id,r.actor_id,r.action,r.transaction_id)=(w,a,target,helpdesk_auth.actor_id(),'revision',pg_current_xact_id())
   AND prior='waiting_customer' AND next_status IN ('open','triage') AND c.from_version=before_version AND c.to_version=after_version AND c.from_status=prior AND c.to_status=next_status
   AND c.command->>'action'='revise_form' AND r.bundle->'expectedVersion'=to_jsonb(before_version) AND r.result->'version'=to_jsonb(after_version)
   AND r.bundle->'decision'->'after'->>'status'=next_status AND r.bundle->'decision'->'after'->'assignedTo' IS NOT DISTINCT FROM coalesce(to_jsonb(destination),'null'::jsonb)
   AND c.public_event=r.bundle->'decision'->'event' AND c.result=r.result);
END$$;


CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_scoped_workflow_commit(w uuid,a uuid,target uuid,before_version integer,after_version integer,prior text,next_status text,destination uuid) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF session_user<>'helpdesk_app' OR w IS DISTINCT FROM helpdesk_auth.workspace_id() OR NOT coalesce(helpdesk_auth.is_human(),false)
 OR NOT coalesce(helpdesk_auth.has_scope(w,'tickets:read') AND helpdesk_auth.has_scope(w,'tickets:write'),false)
 OR NOT coalesce(helpdesk_auth.cg_ticket_resource_allowed(w,a,target,'tickets.write'),false) THEN RETURN false;END IF;
 IF helpdesk_auth.hdnr_scoped_revision(w,a,target,before_version,after_version,prior,next_status,destination) THEN RETURN true;END IF;
 RETURN EXISTS(SELECT 1 FROM helpdesk_audit.hdn_workflow_commits c WHERE
 (c.workspace_id,c.account_id,c.ticket_id,c.actor_id,c.from_version,c.to_version,c.from_status,c.to_status)=
 (w,a,target,helpdesk_auth.actor_id(),before_version,after_version,prior,next_status)
 AND c.transaction_id=pg_current_xact_id() AND
 ((c.command->>'action'='customer_reply' AND prior='waiting_customer' AND next_status='open')
 OR (c.command->>'action'='reopen' AND prior='closed' AND next_status='open')
 OR (c.command->>'action'='transfer' AND prior=next_status AND c.command->>'targetPrincipalId'=destination::text)));
END$$;

create or replace function helpdesk_core.guard_ticket_transition() returns trigger
language plpgsql set search_path='' as $$
declare allowed text[];
begin
 if new.status=old.status then return new; end if;
 if ((old.status='waiting_customer' and new.status in ('open','triage')) or (old.status='closed' and new.status='open')) and helpdesk_auth.hdn_scoped_workflow_commit(old.workspace_id,old.account_id,old.id,old.version,new.version,old.status,new.status,new.assigned_to) then return new;end if;
 if not helpdesk_auth.is_operator(old.workspace_id,old.account_id) then
  if old.status<>'resolved' or new.status not in ('open','closed') then
   raise exception 'Transition not authorized' using errcode='42501';
  end if;
 else
  allowed:=case old.status
   when 'new' then array['triage','open','cancelled']
   when 'triage' then array['open','waiting_customer','cancelled']
   when 'open' then array['waiting_customer','waiting_internal','waiting_third_party','resolved','cancelled']
   when 'waiting_customer' then array['open','resolved','cancelled']
   when 'waiting_internal' then array['open','resolved','cancelled']
   when 'waiting_third_party' then array['open','resolved','cancelled']
   when 'resolved' then array['open','closed'] else array[]::text[] end;
  if not(new.status=any(allowed)) then raise exception 'Invalid transition' using errcode='23514'; end if;
 end if;
 return new;
end$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdni_guard_draft() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Draft deletion denied' USING ERRCODE='23514';END IF;
 IF NEW.owner_id IS DISTINCT FROM helpdesk_auth.actor_id() OR NEW.workspace_id IS DISTINCT FROM helpdesk_auth.workspace_id() OR NOT coalesce(helpdesk_auth.is_human(),false)
 OR NEW.document->>'id' IS DISTINCT FROM NEW.id::text OR NEW.document->>'ownerId' IS DISTINCT FROM NEW.owner_id::text OR NEW.document->>'workspaceId' IS DISTINCT FROM NEW.workspace_id::text OR NEW.document->>'accountId' IS DISTINCT FROM NEW.account_id::text
 OR NEW.document->'revision' IS DISTINCT FROM to_jsonb(NEW.revision) OR NEW.document->'formVersion' IS DISTINCT FROM to_jsonb(NEW.form_version) OR (NEW.document->>'expiresAt')::timestamptz IS DISTINCT FROM NEW.expires_at OR NOT ((NEW.document->>'status'='editing' AND NEW.document->'ticketId'='null'::jsonb) OR (TG_OP='UPDATE' AND OLD.document->>'status'='editing' AND NEW.document->>'status'='committed' AND (EXISTS(SELECT 1 FROM helpdesk_audit.hdni_receipts r WHERE (r.workspace_id,r.draft_id,r.ticket_id,r.actor_id,r.draft_revision)=(NEW.workspace_id,NEW.id,(NEW.document->>'ticketId')::uuid,NEW.owner_id,OLD.revision) AND r.transaction_id=pg_current_xact_id()) OR EXISTS(SELECT 1 FROM helpdesk_audit.hdnr_receipts r WHERE (r.workspace_id,r.account_id,r.ticket_id,r.actor_id,r.action,r.transaction_id)=(NEW.workspace_id,NEW.account_id,(NEW.document->>'ticketId')::uuid,NEW.owner_id,'revision',pg_current_xact_id()) AND r.bundle->>'draftId'=NEW.id::text AND r.bundle->'expectedDraftRevision'=to_jsonb(OLD.revision))) AND NEW.document-ARRAY['status','ticketId','revision']=OLD.document-ARRAY['status','ticketId','revision'])) THEN RAISE EXCEPTION 'Draft shape denied' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' AND (OLD.document->>'status'<>'editing' OR (NEW.workspace_id,NEW.id,NEW.owner_id,NEW.account_id,NEW.configuration_id,NEW.form_version,NEW.expires_at) IS DISTINCT FROM (OLD.workspace_id,OLD.id,OLD.owner_id,OLD.account_id,OLD.configuration_id,OLD.form_version,OLD.expires_at) OR NEW.revision<>OLD.revision+1 OR NEW.document->'formId' IS DISTINCT FROM OLD.document->'formId' OR NEW.document->'refs' IS DISTINCT FROM OLD.document->'refs' OR NEW.document->'schemaHash' IS DISTINCT FROM OLD.document->'schemaHash') THEN RAISE EXCEPTION 'Draft identity immutable' USING ERRCODE='23514';END IF;
 IF TG_OP='INSERT' AND NEW.revision<>1 THEN RAISE EXCEPTION 'Initial revision denied' USING ERRCODE='23514';END IF;
 RETURN NEW;
END$$;


CREATE OR REPLACE FUNCTION helpdesk_auth.hdnr_invitation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r helpdesk_audit.hdnr_receipts%rowtype;c helpdesk_audit.hdnr_challenges%rowtype;BEGIN
 IF session_user<>'helpdesk_app' OR NOT coalesce(helpdesk_auth.is_human(),false) OR TG_OP='DELETE' THEN RAISE EXCEPTION 'Human qualified invitation command required' USING ERRCODE='HDR03';END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT r FROM helpdesk_audit.hdnr_receipts WHERE(id,workspace_id,account_id,ticket_id,action,transaction_id)=(NEW.receipt_id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,'invitation',pg_current_xact_id());
  IF r.actor_id IS DISTINCT FROM helpdesk_auth.actor_id() OR r.invitation_id<>NEW.id OR r.bundle->'invitation' IS DISTINCT FROM NEW.document OR NEW.revision<>1 THEN RAISE EXCEPTION 'Unqualified invitation insertion' USING ERRCODE='HDR03';END IF;RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.receipt_id) IS NOT DISTINCT FROM (OLD.id,OLD.workspace_id,OLD.account_id,OLD.ticket_id,OLD.receipt_id)
  AND NEW.revision=OLD.revision+1 AND OLD.document->>'status'='pending' AND NEW.document=OLD.document||jsonb_build_object('status','revoked') THEN
  SELECT * INTO STRICT r FROM helpdesk_audit.hdnr_receipts WHERE(workspace_id,account_id,ticket_id,actor_id,action,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,helpdesk_auth.actor_id(),'revision',pg_current_xact_id());
  IF NOT coalesce((r.bundle->>'expectedVersion')::integer>=(OLD.document->>'ticketVersion')::integer AND r.bundle->'expectedFormRevision'=OLD.document->'formRevision' AND r.result->'formRevision'=to_jsonb((OLD.document->>'formRevision')::integer+1),false) THEN RAISE EXCEPTION 'Revision invitation target changed' USING ERRCODE='HDR02';END IF;RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.receipt_id) IS NOT DISTINCT FROM (OLD.id,OLD.workspace_id,OLD.account_id,OLD.ticket_id,OLD.receipt_id)
  AND NEW.revision=OLD.revision+1 AND OLD.document->>'status'='pending' AND NEW.document=OLD.document||jsonb_build_object('status','used') AND OLD.document->>'approverId'=helpdesk_auth.actor_id()::text THEN
  SELECT * INTO STRICT r FROM helpdesk_audit.hdnr_receipts WHERE(workspace_id,account_id,ticket_id,invitation_id,actor_id,action,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,helpdesk_auth.actor_id(),'approval',pg_current_xact_id());
  IF r.bundle->'decision'->'challengeGeneration' IS DISTINCT FROM OLD.document->'challenge'->'generation' OR r.result->'version' IS DISTINCT FROM to_jsonb((OLD.document->>'ticketVersion')::integer+1) OR r.result->'formRevision' IS DISTINCT FROM OLD.document->'formRevision' THEN RAISE EXCEPTION 'Approval invitation consumption changed' USING ERRCODE='HDR02';END IF;RETURN NEW;
 END IF;
 IF (NEW.id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.receipt_id) IS DISTINCT FROM (OLD.id,OLD.workspace_id,OLD.account_id,OLD.ticket_id,OLD.receipt_id) OR NEW.revision<>OLD.revision+1
  OR OLD.document->>'status'<>'pending' OR NEW.document-'challenge' IS DISTINCT FROM OLD.document-'challenge' OR NEW.document->>'approverId' IS DISTINCT FROM helpdesk_auth.actor_id()::text
 THEN RAISE EXCEPTION 'Invitation identity or command changed' USING ERRCODE='HDR02';END IF;
 SELECT * INTO STRICT c FROM helpdesk_audit.hdnr_challenges WHERE(workspace_id,account_id,ticket_id,invitation_id,generation,actor_id,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,(NEW.document->'challenge'->>'generation')::integer,helpdesk_auth.actor_id(),pg_current_xact_id());
 IF c.generation<>coalesce((OLD.document->'challenge'->>'generation')::integer,0)+1 OR c.challenge_hash IS DISTINCT FROM NEW.document->'challenge'->>'hash'
  OR c.target_hash IS DISTINCT FROM NEW.document->>'targetHash' OR c.expires_at<>helpdesk_auth.hdn_notification_stamp(NEW.document->'challenge'->>'expiresAt') OR c.expires_at<=clock_timestamp()
 THEN RAISE EXCEPTION 'Qualified current challenge required' USING ERRCODE='HDR02';END IF;RETURN NEW;
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Invitation proof required' USING ERRCODE='HDR03';END$$;

CREATE FUNCTION helpdesk_auth.hdnr_commit_revision(bundle jsonb,receipt jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE w uuid:=helpdesk_auth.workspace_id();who uuid:=helpdesk_auth.actor_id();target uuid;account uuid;ctx jsonb;a jsonb;t jsonb;d jsonb;answers jsonb;form_doc jsonb;delta jsonb;preview_hash text;intent_hash text;
 decision jsonb:=bundle->'decision';audit_doc jsonb:=bundle->'audit';outbox_doc jsonb:=bundle->'outbox';expected_decision jsonb;after_doc jsonb;event_doc jsonb;expected_audit jsonb;expected_outbox jsonb;result jsonb;consumed jsonb;command_doc jsonb;
 effect_uuid uuid;request_uuid uuid;draft_uuid uuid;at_text text;stamp timestamptz;comment_value text;next_status text;next_approval text;actor_kind text;expected_version integer;next_version integer;form_revision integer;draft_revision integer;prior helpdesk_audit.hdnr_receipts%rowtype;affected integer;BEGIN
 IF NOT coalesce(helpdesk_auth.hdn_cfg_object(bundle,ARRAY['expectedVersion','expectedFormRevision','draftId','expectedDraftRevision','decision','form','clocks','audit','outbox']) AND helpdesk_auth.hdn_cfg_object(receipt,ARRAY['key','hash','result']),false) OR receipt->>'key' IS NULL OR receipt->>'key'!~'^[A-Za-z0-9._:-]{16,128}$' THEN RAISE EXCEPTION 'Invalid form revision command' USING ERRCODE='HDR03';END IF;
 target:=(receipt->'result'->>'ticketId')::uuid;ctx:=helpdesk_auth.hdnr_context(target);PERFORM helpdesk_auth.hdnr_grant(target,'forms.revise',ctx);a:=helpdesk_auth.hdnr_aggregate(target)->'aggregate';t:=a->'ticket';account:=(t->>'accountId')::uuid;
 SELECT * INTO prior FROM helpdesk_audit.hdnr_receipts WHERE(workspace_id,actor_id,intent_key)=(w,who,receipt->>'key') FOR UPDATE;
 IF FOUND THEN IF prior.action<>'revision' OR prior.intent_hash IS DISTINCT FROM receipt->>'hash' OR prior.result IS DISTINCT FROM receipt->'result' OR prior.ticket_id<>target THEN RAISE EXCEPTION 'Review idempotency conflict' USING ERRCODE='HDR04';END IF;RETURN prior.result;END IF;
 expected_version:=(t->>'version')::integer;next_version:=expected_version+1;form_revision:=(a->'form'->>'revision')::integer;draft_uuid:=(bundle->>'draftId')::uuid;draft_revision:=(bundle->>'expectedDraftRevision')::integer;
 IF t->>'status'<>'waiting_customer' OR bundle->'expectedVersion' IS DISTINCT FROM t->'version' OR bundle->'expectedFormRevision' IS DISTINCT FROM a->'form'->'revision' THEN RAISE EXCEPTION 'Form target changed' USING ERRCODE='HDR02';END IF;
 d:=helpdesk_auth.hdni_draft(ctx,draft_uuid);
 IF d IS NULL OR d->>'status'<>'editing' OR d->'revision' IS DISTINCT FROM to_jsonb(draft_revision) OR d->'formId' IS DISTINCT FROM a->'form'->'formId' OR d->'formVersion' IS DISTINCT FROM a->'form'->'formVersion' OR d->'schemaHash' IS DISTINCT FROM a->'form'->'schemaHash' OR helpdesk_auth.hdni_refs_key(d->'refs') IS DISTINCT FROM helpdesk_auth.hdni_refs_key(ctx->'refs') THEN RAISE EXCEPTION 'Current owned form draft required' USING ERRCODE='HDR06';END IF;
 answers:=helpdesk_auth.hdni_answers(a->'profile'->'form',d->'answers');delta:=helpdesk_auth.hdnr_diff(a->'form'->'answers',answers,'',true,true,0);
 IF jsonb_array_length(delta)=0 THEN RAISE EXCEPTION 'Form revision has no changes' USING ERRCODE='HDR03';END IF;
 form_doc:=jsonb_build_object('formId',d->'formId','formVersion',d->'formVersion','schemaHash',d->'schemaHash','revision',form_revision+1,'answers',answers,'publicAnswers',answers,'evidence','[]'::jsonb,'draftId',draft_uuid,'draftRevision',draft_revision);
 comment_value:=decision->>'comment';at_text:=audit_doc->>'at';stamp:=helpdesk_auth.hdn_notification_stamp(at_text);
 IF jsonb_typeof(decision->'comment') IS DISTINCT FROM 'string' OR comment_value IS DISTINCT FROM helpdesk_auth.hdni_trim(comment_value) OR octet_length(helpdesk_auth.hdni_utf16(comment_value))/2>12000 OR translate(comment_value,E'\t\n\r','')~'[\u0001-\u001f\u007f]' OR stamp>clock_timestamp() OR stamp<clock_timestamp()-interval '30 seconds' OR stamp<helpdesk_auth.hdn_notification_stamp(t->>'lastEventAt') THEN RAISE EXCEPTION 'Invalid revision comment or time' USING ERRCODE='HDR03';END IF;
 preview_hash:=helpdesk_auth.hdni_digest(jsonb_build_object('ticketId',target,'expectedVersion',expected_version,'expectedFormRevision',form_revision,'draftId',draft_uuid,'draftRevision',draft_revision,'form',form_doc,'profile',a->'profile','approvalPolicy',a->'approvalPolicy','comment',comment_value,'refs',helpdesk_auth.hdni_refs_key(ctx->'refs')));
 intent_hash:=helpdesk_auth.hdni_digest(jsonb_build_object('actorId',who,'workspaceId',w,'command',jsonb_build_object('ticketId',target,'expectedVersion',expected_version,'expectedFormRevision',form_revision,'draftId',draft_uuid,'expectedDraftRevision',draft_revision,'comment',comment_value,'previewHash',preview_hash)));
 IF receipt->>'hash' IS DISTINCT FROM intent_hash THEN RAISE EXCEPTION 'Form preview or intent changed' USING ERRCODE='HDR07';END IF;
 effect_uuid:=(audit_doc->>'id')::uuid;request_uuid:=(audit_doc->>'requestId')::uuid;next_status:=CASE WHEN a->'profile'->'approvalRequired'='true'::jsonb THEN 'triage' ELSE 'open' END;next_approval:=CASE WHEN a->'profile'->'approvalRequired'='true'::jsonb THEN 'pending' ELSE 'not_required' END;
 -- Initial Consulte GEO profiles publish a fixed priority. Do not silently
 -- accept a different native priority algorithm for a future generic profile.
 IF a->'profile'->>'fixedPriority' IS DISTINCT FROM t->>'priority' THEN RAISE EXCEPTION 'Unqualified revised priority profile' USING ERRCODE='HDR03';END IF;
 actor_kind:=CASE WHEN coalesce(helpdesk_auth.is_operator(w,account),false) THEN 'human_agent' ELSE 'customer' END;
 after_doc:=t||jsonb_build_object('approval',next_approval,'status',next_status,'version',next_version,'updatedAt',at_text,'lastEventAt',at_text);
 event_doc:=jsonb_build_object('ticketId',target,'workspaceId',w,'profileVersionId',t->'profileVersionId','sequence',next_version,'at',at_text,'type','form_revised','actorId',who,'actorKind',actor_kind,'from',t->'status','to',next_status);
 expected_decision:=jsonb_build_object('after',after_doc,'event',event_doc,'formRevision',form_revision+1,'answers',answers,'diff',delta,'comment',comment_value,'invalidateInvitations',true);
 expected_audit:=jsonb_build_object('id',effect_uuid,'actorId',who,'workspaceId',w,'ticketId',target,'requestId',request_uuid,'at',at_text,'action','form.revised','fromRevision',form_revision,'toRevision',form_revision+1,'diff',delta,'comment',comment_value);
 expected_outbox:=jsonb_build_object('id',effect_uuid,'workspaceId',w,'accountId',account,'ticketId',target,'type','support.form_revised','version',next_version,'requestId',request_uuid,'createdAt',at_text);
 result:=jsonb_build_object('ticketId',target,'workspaceId',w,'accountId',account,'actorId',who,'eventId',effect_uuid,'version',next_version,'formRevision',form_revision+1,'action','revision','invitationId',NULL,'decision',NULL,'notification','pending','replayed',false);
 IF decision IS DISTINCT FROM expected_decision OR bundle->'form' IS DISTINCT FROM form_doc OR audit_doc IS DISTINCT FROM expected_audit OR outbox_doc IS DISTINCT FROM expected_outbox OR receipt->'result' IS DISTINCT FROM result
 OR NOT coalesce(helpdesk_auth.hdn_cfg_object(bundle->'clocks',ARRAY['ticketId','workspaceId','sourceVersion','policyVersionId','calendarVersionId','asOf','firstResponse','solution']),false)
 OR bundle->'clocks'->>'ticketId'<>target::text OR bundle->'clocks'->>'workspaceId'<>w::text OR bundle->'clocks'->'sourceVersion'<>to_jsonb(next_version) OR bundle->'clocks'->>'asOf'<>at_text OR bundle->'clocks'->'policyVersionId'<>a->'profile'->'sla'->'versionId' OR bundle->'clocks'->'calendarVersionId'<>a->'profile'->'sla'->'calendar'->'versionId' THEN RAISE EXCEPTION 'Form revision bundle changed' USING ERRCODE='HDR02';END IF;
 INSERT INTO helpdesk_audit.hdnr_receipts(id,workspace_id,account_id,ticket_id,actor_id,intent_key,intent_hash,action,invitation_id,result,bundle,scope,request_id,created_at) VALUES(effect_uuid,w,account,target,who,receipt->>'key',intent_hash,'revision',NULL,result,bundle,ctx,request_uuid,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision receipt suppressed' USING ERRCODE='HDR03';END IF;
 command_doc:=jsonb_build_object('action','revise_form','expectedVersion',expected_version,'expectedFormRevision',form_revision,'draftId',draft_uuid,'expectedDraftRevision',draft_revision);
 INSERT INTO helpdesk_audit.hdn_workflow_commits(workspace_id,account_id,ticket_id,event_id,actor_id,profile_version_id,from_version,to_version,from_status,to_status,core_type,intent_key,intent_hash,command,public_event,audit,result,at) VALUES(w,account,target,effect_uuid,who,t->>'profileVersionId',expected_version,next_version,t->>'status',next_status,'ticket.status_changed',receipt->>'key',intent_hash,command_doc,event_doc,expected_audit,result,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision workflow proof suppressed' USING ERRCODE='HDR03';END IF;
 UPDATE helpdesk_core.tickets SET status=next_status,version=next_version,updated_at=stamp WHERE(workspace_id,account_id,id,version)=(w,account,target,expected_version);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision ticket changed' USING ERRCODE='HDR02';END IF;
 UPDATE helpdesk_core.hdn_workflow_state SET approval=next_approval,last_event_at=stamp WHERE(workspace_id,account_id,ticket_id)=(w,account,target);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision metadata suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_core.hdnr_forms(workspace_id,account_id,ticket_id,revision,source_version,document,sha256,receipt_id) VALUES(w,account,target,form_revision+1,next_version,form_doc,helpdesk_auth.hdni_digest(form_doc),effect_uuid);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision form suppressed' USING ERRCODE='HDR03';END IF;
 consumed:=d||jsonb_build_object('revision',draft_revision+1,'status','committed','ticketId',target);
 UPDATE helpdesk_core.hdni_drafts SET revision=draft_revision+1,document=consumed WHERE(workspace_id,id,revision)=(w,draft_uuid,draft_revision);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision draft changed' USING ERRCODE='HDR06';END IF;
 INSERT INTO helpdesk_audit.hdni_draft_commits(workspace_id,draft_id,revision,actor_id,scope,document) VALUES(w,draft_uuid,draft_revision+1,who,ctx,consumed);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision draft audit suppressed' USING ERRCODE='HDR03';END IF;
 UPDATE helpdesk_core.hdnr_invitations SET document=jsonb_set(document,'{status}','"revoked"'),revision=revision+1 WHERE(workspace_id,account_id,ticket_id)=(w,account,target) AND document->>'status'='pending';
 INSERT INTO helpdesk_core.ticket_events(id,workspace_id,account_id,ticket_id,actor_id,type,customer_visible,data,created_at) VALUES(effect_uuid,w,account,target,who,'ticket.status_changed',true,jsonb_build_object('from',t->'status','to',next_status,'reason','Formulário revisado no Help Desk.'),stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision core event suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_audit.audit_events(workspace_id,id,principal_id,action,resource_id,request_id,created_at) VALUES(w,effect_uuid,who,'form.revised',target,request_uuid::text,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision audit suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_integration.outbox_events(id,workspace_id,account_id,ticket_id,type,payload,request_id,created_at) VALUES(effect_uuid,w,account,target,'ticket.status_changed',jsonb_build_object('specversion','1.0','id',effect_uuid,'source','helpdesk/workspaces/'||w::text,'type','com.helpdesk.ticket.status_changed.v1','subject','tickets/'||target::text,'datacontenttype','application/json','time',at_text,'data',jsonb_build_object('ticket_id',target,'version',next_version)),request_uuid::text,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision external header suppressed' USING ERRCODE='HDR03';END IF;
 INSERT INTO helpdesk_integration.hdnr_sources(id,workspace_id,account_id,ticket_id,receipt_id,kind,source_version,invitation_id,request_id,created_at) VALUES(effect_uuid,w,account,target,effect_uuid,'support.form_revised',next_version,NULL,request_uuid,stamp);
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Revision notification source suppressed' USING ERRCODE='HDR03';END IF;
 RETURN result;
EXCEPTION WHEN data_exception OR no_data_found THEN RAISE EXCEPTION 'Invalid private form revision' USING ERRCODE='HDR03';END$$;


CREATE OR REPLACE FUNCTION helpdesk_auth.hdnr_receipt_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE source helpdesk_integration.hdnr_sources%rowtype;invitation helpdesk_core.hdnr_invitations%rowtype;c helpdesk_audit.hdn_workflow_commits%rowtype;
 a jsonb;actual_ticket jsonb;before_target jsonb;d jsonb:=NEW.bundle->'decision';expected_payload jsonb;BEGIN
 IF session_user<>'helpdesk_app' OR NEW.transaction_id<>pg_current_xact_id() OR NEW.workspace_id IS DISTINCT FROM helpdesk_auth.workspace_id() OR NEW.actor_id IS DISTINCT FROM helpdesk_auth.actor_id() THEN RAISE EXCEPTION 'Unqualified review receipt' USING ERRCODE='HDR03';END IF;
 SELECT * INTO STRICT source FROM helpdesk_integration.hdnr_sources WHERE(id,workspace_id,account_id,ticket_id,receipt_id)=(NEW.id,NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id);
 IF NEW.action IN ('invitation','approval') THEN
 SELECT * INTO STRICT invitation FROM helpdesk_core.hdnr_invitations WHERE(id,workspace_id,account_id,ticket_id)=(NEW.invitation_id,NEW.workspace_id,NEW.account_id,NEW.ticket_id);
 END IF;
 IF source.created_at<>NEW.created_at OR source.request_id<>NEW.request_id THEN RAISE EXCEPTION 'Review source correlation changed' USING ERRCODE='HDR03';END IF;
 IF NEW.action='invitation' THEN
  PERFORM helpdesk_auth.hdnr_grant(NEW.ticket_id,'approvals.request',NEW.scope);
  IF source.kind<>'support.approval_requested' OR source.invitation_id<>NEW.invitation_id OR source.source_version<>(NEW.result->>'ticketVersion')::integer
   OR invitation.receipt_id<>NEW.id OR invitation.document IS DISTINCT FROM NEW.bundle->'invitation'
   OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.audit_events e WHERE(e.workspace_id,e.id,e.principal_id,e.action,e.resource_id,e.request_id,e.created_at)=(NEW.workspace_id,NEW.id,NEW.actor_id,'approval.requested',NEW.ticket_id,NEW.request_id::text,NEW.created_at))
  THEN RAISE EXCEPTION 'Invitation effects incomplete' USING ERRCODE='HDR03';END IF;
 ELSIF NEW.action='approval' THEN
  PERFORM helpdesk_auth.hdnr_grant(NEW.ticket_id,'approvals.decide',NEW.scope);a:=helpdesk_auth.hdnr_aggregate(NEW.ticket_id)->'aggregate';actual_ticket:=a->'ticket';
  IF source.kind IS DISTINCT FROM 'support.'||(d->'event'->>'type') OR source.invitation_id IS NOT NULL OR source.source_version<>(NEW.result->>'version')::integer
   OR invitation.document->>'status'<>'used' OR invitation.document->>'approverId'<>NEW.actor_id::text OR invitation.document->'ticketVersion'<>to_jsonb(source.source_version-1)
   OR invitation.document->'formRevision'<>NEW.result->'formRevision' OR invitation.document->'challenge'->'generation'<>d->'challengeGeneration'
   OR helpdesk_auth.hdn_notification_stamp(invitation.document->'challenge'->>'expiresAt')<=clock_timestamp()
   OR actual_ticket->'version'<>NEW.result->'version' OR a->'form'->'revision'<>NEW.result->'formRevision'
   OR (actual_ticket||jsonb_build_object('updatedAt',d->'after'->'updatedAt','lastEventAt',d->'after'->'lastEventAt')) IS DISTINCT FROM d->'after'
   OR helpdesk_auth.hdn_notification_stamp(actual_ticket->>'updatedAt')<>NEW.created_at OR helpdesk_auth.hdn_notification_stamp(actual_ticket->>'lastEventAt')<>NEW.created_at
  THEN RAISE EXCEPTION 'Approval state or invitation effect incomplete' USING ERRCODE='HDR03';END IF;
  before_target:=a||jsonb_build_object('ticket',actual_ticket||jsonb_build_object('version',source.source_version-1));
  IF invitation.document->>'targetHash'<>helpdesk_auth.hdnr_target_hash(before_target) THEN RAISE EXCEPTION 'Approval target pin changed' USING ERRCODE='HDR03';END IF;
  SELECT * INTO STRICT c FROM helpdesk_audit.hdn_workflow_commits WHERE(workspace_id,account_id,ticket_id,event_id,actor_id,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,NEW.actor_id,NEW.transaction_id);
  IF c.intent_key<>NEW.intent_key OR c.intent_hash<>NEW.intent_hash OR c.result IS DISTINCT FROM NEW.result OR c.public_event IS DISTINCT FROM d->'event' OR c.audit IS DISTINCT FROM NEW.bundle->'audit'
   OR c.core_type<>'ticket.status_changed' OR c.from_version<>source.source_version-1 OR c.to_version<>source.source_version OR c.from_status<>d->'event'->>'from' OR c.to_status<>d->'event'->>'to' OR c.at<>NEW.created_at
   OR c.command IS DISTINCT FROM jsonb_build_object('action','approval','expectedVersion',c.from_version,'invitationId',NEW.invitation_id,'expectedFormRevision',NEW.result->'formRevision','decision',d->'decision','challengeGeneration',d->'challengeGeneration')
   OR NOT EXISTS(SELECT 1 FROM helpdesk_core.ticket_events e JOIN helpdesk_audit.write_effects f ON(f.workspace_id,f.event_id)=(e.workspace_id,e.id)
    WHERE(e.workspace_id,e.account_id,e.ticket_id,e.id,e.actor_id,e.type,e.created_at)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,NEW.actor_id,'ticket.status_changed',NEW.created_at)
     AND e.customer_visible AND f.applied AND f.transaction_id=NEW.transaction_id AND f.ticket_version=c.to_version AND f.kind=e.type
     AND e.data-'reason'=f.expected_data AND f.expected_data=jsonb_build_object('from',c.from_status,'to',c.to_status))
   OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.audit_events e WHERE(e.workspace_id,e.id,e.principal_id,e.action,e.resource_id,e.request_id,e.created_at)=(NEW.workspace_id,NEW.id,NEW.actor_id,NEW.bundle->'audit'->>'action',NEW.ticket_id,NEW.request_id::text,NEW.created_at))
  THEN RAISE EXCEPTION 'Approval functional event or audit incomplete' USING ERRCODE='HDR03';END IF;
  expected_payload:=jsonb_build_object('specversion','1.0','id',NEW.id,'source','helpdesk/workspaces/'||NEW.workspace_id::text,'type','com.helpdesk.ticket.status_changed.v1','subject','tickets/'||NEW.ticket_id::text,'datacontenttype','application/json','time',NEW.bundle->'outbox'->'createdAt','data',jsonb_build_object('ticket_id',NEW.ticket_id,'version',source.source_version));
  IF NOT EXISTS(SELECT 1 FROM helpdesk_integration.outbox_events e WHERE(e.workspace_id,e.account_id,e.ticket_id,e.id,e.type,e.request_id,e.created_at)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,'ticket.status_changed',NEW.request_id::text,NEW.created_at) AND e.payload=expected_payload) THEN RAISE EXCEPTION 'Approval external header incomplete' USING ERRCODE='HDR03';END IF;
 ELSIF NEW.action='revision' THEN
  PERFORM helpdesk_auth.hdnr_grant(NEW.ticket_id,'forms.revise',NEW.scope);a:=helpdesk_auth.hdnr_aggregate(NEW.ticket_id)->'aggregate';actual_ticket:=a->'ticket';
  IF source.kind<>'support.form_revised' OR source.invitation_id IS NOT NULL OR NEW.invitation_id IS NOT NULL OR source.source_version<>(NEW.result->>'version')::integer
   OR actual_ticket->'version' IS DISTINCT FROM NEW.result->'version' OR a->'form'->'revision' IS DISTINCT FROM NEW.result->'formRevision'
   OR a->'form' IS DISTINCT FROM NEW.bundle->'form' OR (actual_ticket||jsonb_build_object('updatedAt',d->'after'->'updatedAt','lastEventAt',d->'after'->'lastEventAt')) IS DISTINCT FROM d->'after'
   OR helpdesk_auth.hdn_notification_stamp(actual_ticket->>'updatedAt')<>NEW.created_at OR helpdesk_auth.hdn_notification_stamp(actual_ticket->>'lastEventAt')<>NEW.created_at
   OR EXISTS(SELECT 1 FROM helpdesk_core.hdnr_invitations i WHERE(i.workspace_id,i.account_id,i.ticket_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id) AND i.document->>'status'='pending')
   OR NOT EXISTS(SELECT 1 FROM helpdesk_core.hdnr_forms f WHERE(f.workspace_id,f.account_id,f.ticket_id,f.revision,f.source_version,f.receipt_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,(NEW.result->>'formRevision')::integer,source.source_version,NEW.id) AND f.document=NEW.bundle->'form' AND f.sha256=helpdesk_auth.hdni_digest(f.document))
  THEN RAISE EXCEPTION 'Revision state form or invitations incomplete' USING ERRCODE='HDR03';END IF;
  SELECT * INTO STRICT c FROM helpdesk_audit.hdn_workflow_commits WHERE(workspace_id,account_id,ticket_id,event_id,actor_id,transaction_id)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,NEW.actor_id,NEW.transaction_id);
  IF c.intent_key<>NEW.intent_key OR c.intent_hash<>NEW.intent_hash OR c.result IS DISTINCT FROM NEW.result OR c.public_event IS DISTINCT FROM d->'event' OR c.audit IS DISTINCT FROM NEW.bundle->'audit'
   OR c.core_type<>'ticket.status_changed' OR c.from_version<>source.source_version-1 OR c.to_version<>source.source_version OR c.from_status<>'waiting_customer' OR c.to_status<>d->'event'->>'to' OR c.at<>NEW.created_at
   OR c.command IS DISTINCT FROM jsonb_build_object('action','revise_form','expectedVersion',NEW.bundle->'expectedVersion','expectedFormRevision',NEW.bundle->'expectedFormRevision','draftId',NEW.bundle->'draftId','expectedDraftRevision',NEW.bundle->'expectedDraftRevision')
   OR NOT EXISTS(SELECT 1 FROM helpdesk_core.ticket_events e JOIN helpdesk_audit.write_effects f ON(f.workspace_id,f.event_id)=(e.workspace_id,e.id)
    WHERE(e.workspace_id,e.account_id,e.ticket_id,e.id,e.actor_id,e.type,e.created_at)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,NEW.actor_id,'ticket.status_changed',NEW.created_at)
     AND e.customer_visible AND f.applied AND f.transaction_id=NEW.transaction_id AND f.ticket_version=c.to_version AND f.kind=e.type AND e.data-'reason'=f.expected_data AND f.expected_data=jsonb_build_object('from',c.from_status,'to',c.to_status))
   OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.audit_events e WHERE(e.workspace_id,e.id,e.principal_id,e.action,e.resource_id,e.request_id,e.created_at)=(NEW.workspace_id,NEW.id,NEW.actor_id,'form.revised',NEW.ticket_id,NEW.request_id::text,NEW.created_at))
   OR NOT EXISTS(SELECT 1 FROM helpdesk_core.hdni_drafts draft JOIN helpdesk_audit.hdni_draft_commits dc ON(dc.workspace_id,dc.draft_id,dc.revision)=(draft.workspace_id,draft.id,draft.revision)
    WHERE(draft.workspace_id,draft.account_id,draft.id,draft.owner_id,draft.revision)=(NEW.workspace_id,NEW.account_id,(NEW.bundle->>'draftId')::uuid,NEW.actor_id,(NEW.bundle->>'expectedDraftRevision')::integer+1)
     AND draft.document->>'status'='committed' AND draft.document->>'ticketId'=NEW.ticket_id::text AND helpdesk_auth.hdni_answers(a->'profile'->'form',draft.document->'answers')=NEW.bundle->'form'->'answers' AND draft.document->'formId'=NEW.bundle->'form'->'formId'
     AND draft.document->'formVersion'=NEW.bundle->'form'->'formVersion' AND draft.document->'schemaHash'=NEW.bundle->'form'->'schemaHash' AND helpdesk_auth.hdni_refs_key(draft.document->'refs')=helpdesk_auth.hdni_refs_key(NEW.scope->'refs')
     AND draft.expires_at>clock_timestamp() AND dc.actor_id=NEW.actor_id AND dc.scope=NEW.scope AND dc.document=draft.document)
  THEN RAISE EXCEPTION 'Revision functional event draft or audit incomplete' USING ERRCODE='HDR03';END IF;
  expected_payload:=jsonb_build_object('specversion','1.0','id',NEW.id,'source','helpdesk/workspaces/'||NEW.workspace_id::text,'type','com.helpdesk.ticket.status_changed.v1','subject','tickets/'||NEW.ticket_id::text,'datacontenttype','application/json','time',NEW.bundle->'outbox'->'createdAt','data',jsonb_build_object('ticket_id',NEW.ticket_id,'version',source.source_version));
  IF NOT EXISTS(SELECT 1 FROM helpdesk_integration.outbox_events e WHERE(e.workspace_id,e.account_id,e.ticket_id,e.id,e.type,e.request_id,e.created_at)=(NEW.workspace_id,NEW.account_id,NEW.ticket_id,NEW.id,'ticket.status_changed',NEW.request_id::text,NEW.created_at) AND e.payload=expected_payload) THEN RAISE EXCEPTION 'Revision external header incomplete' USING ERRCODE='HDR03';END IF;
 ELSE RAISE EXCEPTION 'Review receipt action not yet qualified' USING ERRCODE='HDR03';END IF;
 RETURN NULL;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Review receipt effects missing' USING ERRCODE='HDR03';END$$;

DO $private$ DECLARE role_name text;BEGIN
 REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_diff(jsonb,jsonb,text,boolean,boolean,integer),helpdesk_auth.hdnr_scoped_revision(uuid,uuid,uuid,integer,integer,text,text,uuid),helpdesk_auth.hdnr_commit_revision(jsonb,jsonb) FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_diff(jsonb,jsonb,text,boolean,boolean,integer),helpdesk_auth.hdnr_scoped_revision(uuid,uuid,uuid,integer,integer,text,text,uuid),helpdesk_auth.hdnr_commit_revision(jsonb,jsonb) FROM %I',role_name);END IF;
 END LOOP;
 GRANT EXECUTE ON FUNCTION helpdesk_auth.hdnr_commit_revision(jsonb,jsonb) TO helpdesk_app;
END $private$;


-- SOURCE hdn_review_notifications.sql SHA256 f4382d2a88116eb71ba09654da704ce51a39d910529133020e3de335e03af62c
ALTER FUNCTION helpdesk_auth.hdn_notification_facts(uuid) RENAME TO hdn_notification_facts_wave2_team;
CREATE FUNCTION helpdesk_auth.hdn_notification_facts(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE s helpdesk_integration.hdnr_sources%rowtype;r helpdesk_audit.hdnr_receipts%rowtype;root helpdesk_audit.hdni_receipts%rowtype;c helpdesk_audit.hdn_workflow_commits%rowtype;
 i helpdesk_core.hdnr_invitations%rowtype;facts jsonb;src jsonb;expected jsonb;prior jsonb;at_text text;BEGIN
 SELECT * INTO s FROM helpdesk_integration.hdnr_sources WHERE id=target FOR SHARE;
 IF NOT FOUND THEN RETURN helpdesk_auth.hdn_notification_facts_wave2_team(target);END IF;
 SELECT * INTO STRICT r FROM helpdesk_audit.hdnr_receipts WHERE(id,workspace_id,account_id,ticket_id)=(s.receipt_id,s.workspace_id,s.account_id,s.ticket_id) FOR SHARE;
 SELECT * INTO STRICT root FROM helpdesk_audit.hdni_receipts WHERE(workspace_id,account_id,ticket_id)=(s.workspace_id,s.account_id,s.ticket_id) FOR SHARE;
 facts:=helpdesk_auth.hdn_notification_facts_v024(root.event_id);src:=r.bundle->'outbox';at_text:=src->>'createdAt';
 expected:=jsonb_build_object('id',s.id,'workspaceId',s.workspace_id,'accountId',s.account_id,'ticketId',s.ticket_id,'type',s.kind,'version',s.source_version,'requestId',s.request_id,'createdAt',at_text);
 IF r.id<>s.id OR r.request_id<>s.request_id OR r.created_at<>s.created_at OR helpdesk_auth.hdn_notification_stamp(at_text)<>s.created_at THEN RAISE EXCEPTION 'Review source receipt mismatch' USING ERRCODE='HDN05';END IF;
 IF s.kind='support.approval_requested' THEN
  SELECT * INTO STRICT i FROM helpdesk_core.hdnr_invitations WHERE(id,workspace_id,account_id,ticket_id)=(s.invitation_id,s.workspace_id,s.account_id,s.ticket_id);
  expected:=expected||jsonb_build_object('invitationId',s.invitation_id);
  IF r.action<>'invitation' OR r.invitation_id<>s.invitation_id OR i.receipt_id<>r.id OR i.document-ARRAY['status','challenge'] IS DISTINCT FROM (r.bundle->'invitation')-ARRAY['status','challenge'] OR i.document->'ticketVersion'<>to_jsonb(s.source_version)
   OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.audit_events e WHERE(e.workspace_id,e.id,e.principal_id,e.action,e.resource_id,e.request_id,e.created_at)=(s.workspace_id,s.id,r.actor_id,'approval.requested',s.ticket_id,s.request_id::text,s.created_at)) THEN RAISE EXCEPTION 'Review invitation source mismatch' USING ERRCODE='HDN05';END IF;
 ELSE
  SELECT * INTO STRICT c FROM helpdesk_audit.hdn_workflow_commits WHERE(workspace_id,account_id,ticket_id,event_id)=(s.workspace_id,s.account_id,s.ticket_id,s.id) FOR SHARE;
  IF s.invitation_id IS NOT NULL OR c.transaction_id<>r.transaction_id OR c.actor_id<>r.actor_id OR c.intent_key<>r.intent_key OR c.intent_hash<>r.intent_hash OR c.to_version<>s.source_version OR c.at<>s.created_at OR c.public_event IS DISTINCT FROM r.bundle->'decision'->'event' OR c.result IS DISTINCT FROM r.result OR c.audit IS DISTINCT FROM r.bundle->'audit'
   OR s.kind IS DISTINCT FROM 'support.'||(c.public_event->>'type') OR s.kind='support.form_revised' AND (r.action<>'revision' OR c.command->>'action'<>'revise_form') OR s.kind IN ('support.approval_granted','support.approval_rejected') AND (r.action<>'approval' OR c.command->>'action'<>'approval')
   OR NOT EXISTS(SELECT 1 FROM helpdesk_core.ticket_events e JOIN helpdesk_audit.write_effects f ON(f.workspace_id,f.event_id)=(e.workspace_id,e.id) WHERE(e.workspace_id,e.account_id,e.ticket_id,e.id,e.actor_id,e.type,e.created_at)=(s.workspace_id,s.account_id,s.ticket_id,s.id,r.actor_id,'ticket.status_changed',s.created_at) AND e.customer_visible AND f.applied AND f.transaction_id=r.transaction_id AND f.ticket_version=s.source_version AND e.data-'reason'=f.expected_data AND f.expected_data=jsonb_build_object('from',c.from_status,'to',c.to_status))
   OR NOT EXISTS(SELECT 1 FROM helpdesk_audit.audit_events e WHERE(e.workspace_id,e.id,e.principal_id,e.action,e.resource_id,e.request_id,e.created_at)=(s.workspace_id,s.id,r.actor_id,r.bundle->'audit'->>'action',s.ticket_id,s.request_id::text,s.created_at))
   OR NOT EXISTS(SELECT 1 FROM helpdesk_integration.outbox_events o WHERE(o.workspace_id,o.account_id,o.ticket_id,o.id,o.type,o.request_id,o.created_at)=(s.workspace_id,s.account_id,s.ticket_id,s.id,'ticket.status_changed',s.request_id::text,s.created_at)
    AND o.payload=jsonb_build_object('specversion','1.0','id',s.id,'source','helpdesk/workspaces/'||s.workspace_id::text,'type','com.helpdesk.ticket.status_changed.v1','subject','tickets/'||s.ticket_id::text,'datacontenttype','application/json','time',at_text,'data',jsonb_build_object('ticket_id',s.ticket_id,'version',s.source_version))) THEN RAISE EXCEPTION 'Review workflow source mismatch' USING ERRCODE='HDN05';END IF;
 END IF;
 IF src IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Review source header changed' USING ERRCODE='HDN05';END IF;
 SELECT document INTO prior FROM helpdesk_integration.hdn_notification_plans WHERE event_id=target;
 IF prior IS NOT NULL AND prior->>'sourceHash'<>helpdesk_auth.hdni_digest(src) THEN RAISE EXCEPTION 'Review historical source changed' USING ERRCODE='HDN05';END IF;
 RETURN jsonb_set(facts,'{source}',src,false)||jsonb_build_object('wave2Eligible',true,'sourceApproverId',CASE WHEN s.kind='support.approval_requested' THEN i.document->'approverId' ELSE 'null'::jsonb END);
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Unqualified review source' USING ERRCODE='HDN05';END$$;

-- Dispatch authority is deliberately separate from immutable historical facts:
-- delivered callbacks remain valid after an invitation expires or is consumed.
CREATE FUNCTION helpdesk_auth.hdn_notification_approver(target uuid,person uuid) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE facts jsonb;src jsonb;w uuid;a uuid;ticket uuid;i helpdesk_core.hdnr_invitations%rowtype;t helpdesk_core.tickets%rowtype;g helpdesk_auth.hdnr_grants%rowtype;roster helpdesk_auth.hdnr_rosters%rowtype;p helpdesk_core.hdnr_profiles%rowtype;form_revision integer;ref record;BEGIN
 facts:=helpdesk_auth.hdn_notification_facts(target);src:=facts->'source';IF src->>'type'<>'support.approval_requested' OR facts->>'sourceApproverId' IS DISTINCT FROM person::text OR person::text=facts->>'requesterId' THEN RETURN false;END IF;
 w:=(src->>'workspaceId')::uuid;a:=(src->>'accountId')::uuid;ticket:=(src->>'ticketId')::uuid;PERFORM helpdesk_auth.hdnr_authority_read(w);
 SELECT * INTO STRICT t FROM helpdesk_core.tickets WHERE(workspace_id,account_id,id)=(w,a,ticket) FOR SHARE;
 SELECT * INTO STRICT i FROM helpdesk_core.hdnr_invitations WHERE(workspace_id,account_id,ticket_id,id)=(w,a,ticket,(src->>'invitationId')::uuid) FOR SHARE;
 SELECT p0.* INTO STRICT p FROM helpdesk_core.hdnr_profiles p0 JOIN helpdesk_core.hdn_workflow_state state ON(state.workspace_id,state.account_id,state.profile_version_id)=(p0.workspace_id,p0.account_id,p0.profile_version_id) WHERE(state.workspace_id,state.account_id,state.ticket_id)=(w,a,ticket);
 SELECT coalesce(max(revision),1) INTO form_revision FROM helpdesk_core.hdnr_forms WHERE(workspace_id,account_id,ticket_id)=(w,a,ticket);
 IF i.document->>'status'<>'pending' OR helpdesk_auth.hdn_notification_stamp(i.document->>'expiresAt')<=clock_timestamp() OR i.document->>'approverId'<>person::text OR i.document->'ticketVersion'<>to_jsonb(t.version) OR i.document->'formRevision'<>to_jsonb(form_revision) OR i.document->>'policyVersionId'<>p.policy_version_id OR t.status NOT IN ('new','triage') OR person=t.created_by THEN RETURN false;END IF;
 PERFORM 1 FROM helpdesk_core.hdn_workflow_state WHERE(workspace_id,account_id,ticket_id,approval)=(w,a,ticket,'pending') FOR SHARE;IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO roster FROM helpdesk_auth.hdnr_rosters WHERE(workspace_id,account_id,profile_version_id)=(w,a,p.profile_version_id) ORDER BY revision DESC LIMIT 1 FOR SHARE;
 SELECT * INTO g FROM helpdesk_auth.hdnr_grants WHERE(workspace_id,account_id,principal_id,capability)=(w,a,person,'approvals.decide') ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF g.principal_id IS NULL OR NOT g.active OR g.expires_at<=clock_timestamp() OR roster.approver_id IS DISTINCT FROM person OR NOT roster.active OR roster.expires_at<=clock_timestamp() THEN RETURN false;END IF;
 PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE(workspace_id,principal_id,role,active)=(w,person,'admin',true) FOR SHARE;IF NOT FOUND OR NOT helpdesk_auth.hdnr_operator(w,a,ticket,person) THEN RETURN false;END IF;
 FOR ref IN SELECT resource_type,resource_id FROM helpdesk_core.cg_ticket_resource_refs WHERE(workspace_id,account_id,ticket_id)=(w,a,ticket) LOOP
  IF ref.resource_type<>'work' OR NOT ref.resource_id=ANY(g.work_ids) OR NOT ref.resource_id=ANY(roster.work_ids) THEN RETURN false;END IF;
 END LOOP;RETURN true;
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Current approval recipient unavailable' USING ERRCODE='HDN06';END$$;


CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_sources(bound integer) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE row record;facts jsonb;src jsonb;ids jsonb:='[]';p jsonb;remaining integer;BEGIN
 PERFORM helpdesk_auth.hdn_notification_worker();IF bound NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'Bound required' USING ERRCODE='HDN02';END IF;
 FOR row IN SELECT x.id FROM helpdesk_integration.hdnr_sources x WHERE NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_plans planned WHERE planned.event_id=x.id) ORDER BY x.created_at,x.id LIMIT bound FOR UPDATE OF x SKIP LOCKED LOOP
  PERFORM helpdesk_auth.hdn_notification_facts(row.id);ids:=ids||jsonb_build_array(row.id);
 END LOOP;
 remaining:=bound-jsonb_array_length(ids);
 FOR row IN SELECT x.id FROM helpdesk_integration.hdn_notification_private_sources x WHERE NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_plans planned WHERE planned.event_id=x.id) ORDER BY x.created_at,x.id LIMIT remaining FOR UPDATE OF x SKIP LOCKED LOOP
  PERFORM helpdesk_auth.hdn_notification_facts(row.id);ids:=ids||jsonb_build_array(row.id);
 END LOOP;
 remaining:=bound-jsonb_array_length(ids);
 FOR row IN SELECT o.id FROM helpdesk_integration.outbox_events o WHERE NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdnr_sources x WHERE x.id=o.id) AND NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_private_sources x WHERE x.id=o.id) AND NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_plans planned WHERE planned.event_id=o.id) AND EXISTS(SELECT 1 FROM helpdesk_core.hdni_snapshots s WHERE (s.workspace_id,s.account_id,s.ticket_id)=(o.workspace_id,o.account_id,o.ticket_id)) ORDER BY o.created_at,o.id LIMIT remaining FOR UPDATE OF o SKIP LOCKED LOOP
  facts:=helpdesk_auth.hdn_notification_facts(row.id);src:=facts->'source';
  IF src->>'type' NOT IN ('support.created','support.devolutiva','support.customer_reply','support.form_revised','support.resolved','support.approval_requested','support.approval_granted','support.approval_rejected','support.transition','support.reply','support.handoff','support.closed','support.reopened','support.cancelled','internal.queue_created','internal.assignment_changed') THEN
   p:=jsonb_build_object('schema',1,'eventId',row.id,'sourceHash',helpdesk_auth.hdni_digest(src),'sourceVersion',src->'version','routingRevision','unhandled-v1','plannedAt',helpdesk_auth.hdn_workflow_iso(clock_timestamp()),'state','no_recipients','intentIds','[]'::jsonb);
   INSERT INTO helpdesk_integration.hdn_notification_plans VALUES(row.id,(src->>'workspaceId')::uuid,(src->>'accountId')::uuid,(src->>'ticketId')::uuid,p);
  ELSE ids:=ids||jsonb_build_array(row.id);END IF;
 END LOOP;RETURN ids;
END$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_routing(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE facts jsonb;src jsonb;route helpdesk_integration.hdn_notification_routes%rowtype;t helpdesk_integration.hdn_notification_templates%rowtype;
 roster helpdesk_integration.hdn_notification_queue_rosters%rowtype;people uuid[]:='{}';person uuid;recipients jsonb:='[]';BEGIN
 PERFORM helpdesk_auth.hdn_notification_worker();facts:=helpdesk_auth.hdn_notification_facts(target);src:=facts->'source';
 SELECT * INTO STRICT route FROM helpdesk_integration.hdn_notification_routes WHERE workspace_id=(src->>'workspaceId')::uuid AND kind=src->>'type' ORDER BY revision DESC LIMIT 1 FOR SHARE;
 IF route.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Routing expired' USING ERRCODE='HDN05';END IF;
 IF route.audience<>'none' AND facts->'wave2Eligible'='true'::jsonb AND (route.effective_after IS NULL OR helpdesk_auth.hdn_notification_stamp(src->>'createdAt')>=route.effective_after) THEN
  SELECT * INTO STRICT t FROM helpdesk_integration.hdn_notification_templates WHERE id=route.template_id AND version=route.template_version FOR SHARE;
  IF t.kind<>route.kind THEN RAISE EXCEPTION 'Template kind mismatch' USING ERRCODE='HDN05';END IF;
  IF route.audience='requester' THEN people:=ARRAY[(facts->>'requesterId')::uuid];
  ELSIF route.audience='approver' THEN people:=ARRAY[(facts->>'sourceApproverId')::uuid];
  ELSIF route.audience IN ('assignee','customer_return') AND facts->>'sourceAssigneeId' IS NOT NULL THEN people:=ARRAY[(facts->>'sourceAssigneeId')::uuid];
  ELSIF route.audience IN ('queue','customer_return') THEN
   SELECT * INTO STRICT roster FROM helpdesk_integration.hdn_notification_queue_rosters WHERE workspace_id=(src->>'workspaceId')::uuid AND account_id=(src->>'accountId')::uuid ORDER BY revision DESC LIMIT 1 FOR SHARE;
   IF roster.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Published queue roster expired' USING ERRCODE='HDN05';END IF;people:=roster.member_ids;
  ELSE RAISE EXCEPTION 'Audience not yet qualified' USING ERRCODE='HDN05';END IF;
  FOREACH person IN ARRAY people LOOP
   IF (route.recipient_ids IS NULL OR person=ANY(route.recipient_ids)) AND (route.audience='requester' OR route.audience='approver' AND helpdesk_auth.hdn_notification_approver(target,person) OR route.audience IN ('queue','assignee','customer_return') AND helpdesk_auth.hdn_notification_internal_person(target,person)) THEN
    recipients:=recipients||jsonb_build_array(jsonb_build_object('principalId',person,'channelId','resend','templateId',t.id,'templateVersion',t.version,'templateHash',t.sha256));
   END IF;
  END LOOP;
 END IF;
 RETURN jsonb_build_object('eventId',target,'workspaceId',src->'workspaceId','accountId',src->'accountId','ticketId',src->'ticketId','sourceVersion',src->'version','kind',src->'type','protocol',facts->'protocol','resourceHash',facts->'resourceHash','revision','route-'||route.revision::text,'status','published','expiresAt',helpdesk_auth.hdn_workflow_iso(route.expires_at),'recipients',recipients);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Published routing required' USING ERRCODE='HDN05';END$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_recipient(i jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE w uuid:=(i->>'workspaceId')::uuid;a uuid:=(i->>'accountId')::uuid;person uuid:=(i->>'recipientId')::uuid;target uuid:=(i->>'ticketId')::uuid;p helpdesk_auth.principals%rowtype;t helpdesk_core.tickets%rowtype;s helpdesk_core.cg_ticket_resource_sets%rowtype;b helpdesk_auth.cg_resource_bindings%rowtype;c helpdesk_auth.cg_resource_connections%rowtype;g helpdesk_auth.cg_resource_grant_sets%rowtype;o helpdesk_auth.cg_resource_observations%rowtype;facts jsonb;address text;verified_at timestamptz;until timestamptz;revision text;allowed boolean:=false;local_registry jsonb;local_account jsonb;local_permission jsonb;local_receipt jsonb;local_work jsonb;ref record;recipient_operation text:='tickets.read';internal_recipient boolean;current_route helpdesk_integration.hdn_notification_routes%rowtype;BEGIN
 IF i->>'kind' IN ('support.form_revised','support.approval_requested','support.approval_granted','support.approval_rejected') THEN PERFORM helpdesk_auth.hdnr_authority_read(w);END IF;
 SELECT * INTO STRICT t FROM helpdesk_core.tickets WHERE (workspace_id,account_id,id)=(w,a,target) FOR SHARE;
 facts:=helpdesk_auth.hdn_notification_facts((i->>'eventId')::uuid);internal_recipient:=i->>'kind' IN ('internal.queue_created','internal.assignment_changed','support.customer_reply','support.approval_requested');IF i->'resourceHash'<>facts->'resourceHash' OR i->'protocol'<>facts->'protocol' OR i->'kind'<>facts->'source'->'type' OR i->'sourceVersion'<>facts->'source'->'version' OR (NOT internal_recipient AND i->'recipientId'<>facts->'requesterId') OR (internal_recipient AND NOT CASE WHEN i->>'kind'='support.approval_requested' THEN i->'invitationId' IS NOT DISTINCT FROM facts->'source'->'invitationId' AND helpdesk_auth.hdn_notification_approver((i->>'eventId')::uuid,person) ELSE helpdesk_auth.hdn_notification_internal_person((i->>'eventId')::uuid,person) END) THEN RAISE EXCEPTION 'Recipient source mismatch' USING ERRCODE='HDN04';END IF;
 IF internal_recipient THEN recipient_operation:='tickets.write';END IF;
 IF i->>'kind' NOT IN ('support.created','support.devolutiva','support.resolved') THEN
  SELECT * INTO STRICT current_route FROM helpdesk_integration.hdn_notification_routes WHERE workspace_id=w AND kind=i->>'kind' ORDER BY revision DESC LIMIT 1 FOR SHARE;
  IF current_route.audience='none' OR current_route.expires_at<=clock_timestamp() OR current_route.recipient_ids IS NULL OR NOT person=ANY(current_route.recipient_ids) OR current_route.effective_after IS NULL OR helpdesk_auth.hdn_notification_stamp(facts->'source'->>'createdAt')<current_route.effective_after THEN RAISE EXCEPTION 'Wave2 recipient route revoked' USING ERRCODE='HDN04';END IF;
 END IF;
 -- Candidate installation precedes the local registry. These fixed queries
 -- become available after promotion; no identifier or actor comes from a caller.
 -- Lock registry before scopes/ACL, matching the local operator's lock order.
 IF to_regclass('helpdesk_auth.cg_local_registries') IS NOT NULL THEN
  EXECUTE 'select to_jsonb(r) from helpdesk_auth.cg_local_registries r where workspace_id=$1 for share' INTO local_registry USING w;
  EXECUTE 'select to_jsonb(a) from helpdesk_auth.cg_local_accounts a where workspace_id=$1 and account_id=$2 for share' INTO local_account USING w,a;
 END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('helpdesk-human-scopes:'||w::text||':'||person::text,0));
 SELECT * INTO p FROM helpdesk_auth.principals WHERE id=person FOR SHARE;IF NOT FOUND OR NOT p.active OR p.kind<>'human' THEN RAISE EXCEPTION 'Recipient human revoked' USING ERRCODE='HDN04';END IF;
 IF NOT 'tickets:read'=ANY(helpdesk_auth.human_scopes(w,person)) OR internal_recipient AND NOT 'tickets:write'=ANY(helpdesk_auth.human_scopes(w,person)) THEN RAISE EXCEPTION 'Recipient scopes revoked' USING ERRCODE='HDN04';END IF;
 PERFORM 1 FROM helpdesk_auth.account_grants WHERE workspace_id=w AND account_id=a AND principal_id=person AND active AND (role IN ('account_manager','agent') OR role='requester' AND t.created_by=person) FOR SHARE;allowed:=FOUND;
 IF NOT allowed THEN PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE workspace_id=w AND principal_id=person AND active AND role='admin' FOR SHARE;allowed:=FOUND;END IF;IF NOT allowed THEN RAISE EXCEPTION 'Recipient ticket access revoked' USING ERRCODE='HDN04';END IF;
 SELECT * INTO STRICT s FROM helpdesk_core.cg_ticket_resource_sets WHERE (workspace_id,account_id,ticket_id)=(w,a,target) AND sealed FOR SHARE;
 SELECT * INTO b FROM helpdesk_auth.cg_resource_bindings WHERE (workspace_id,account_id,id)=(w,a,s.binding_id) FOR SHARE;IF NOT FOUND OR NOT b.active THEN RAISE EXCEPTION 'Recipient binding revoked' USING ERRCODE='HDN04';END IF;
 SELECT * INTO c FROM helpdesk_auth.cg_resource_connections WHERE (workspace_id,id)=(w,b.connection_id) FOR SHARE;IF NOT FOUND OR NOT c.active OR c.product_instance_id<>t.product_instance_id THEN RAISE EXCEPTION 'Recipient connection revoked' USING ERRCODE='HDN04';END IF;
 IF (SELECT count(*) FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,target))<>s.expected_count THEN RAISE EXCEPTION 'Recipient sealed resources unavailable' USING ERRCODE='HDN06';END IF;
 IF local_account IS NOT NULL THEN
  IF local_account->'active'='false'::jsonb THEN RAISE EXCEPTION 'Recipient local account revoked' USING ERRCODE='HDN04';END IF;
  IF local_registry IS NULL OR local_account->'active' IS DISTINCT FROM 'true'::jsonb OR local_account->'registry_revision' IS DISTINCT FROM local_registry->'revision'
  OR local_account->>'binding_id' IS DISTINCT FROM b.id::text OR local_account->>'connection_id' IS DISTINCT FROM c.id::text OR local_account->>'product_instance_id' IS DISTINCT FROM t.product_instance_id::text OR local_account->>'tenant_id' IS DISTINCT FROM b.tenant_id THEN RAISE EXCEPTION 'Recipient local account unavailable' USING ERRCODE='HDN06';END IF;
  EXECUTE 'select to_jsonb(r) from helpdesk_audit.cg_local_receipts r where workspace_id=$1 and registry_revision=$2 for share' INTO local_receipt USING w,(local_registry->>'revision')::integer;
  IF local_receipt IS NULL OR local_receipt->'decision_hash' IS DISTINCT FROM local_registry->'decision_hash' OR local_receipt->'receipt'->'decisionHash' IS DISTINCT FROM local_registry->'decision_hash' OR local_receipt->'receipt'->'revision' IS DISTINCT FROM local_registry->'revision'
  OR local_receipt->'receipt'->>'workspaceId' IS DISTINCT FROM w::text OR local_receipt->'receipt'->'requestId' IS DISTINCT FROM local_receipt->'request_id' OR local_receipt->'receipt'->'commandHash' IS DISTINCT FROM local_receipt->'command_hash'
  OR local_receipt->'receipt'->'sourceManifest' IS DISTINCT FROM '{"authority":"persisted-local-registry","complete":true,"externalApiQualified":false,"resourceType":"work","source":"helpdesk-local","version":1}'::jsonb
  OR NOT coalesce(isfinite((local_registry->>'as_of')::timestamptz),false) OR (local_registry->>'as_of')::timestamptz>clock_timestamp() OR (local_receipt->'receipt'->>'asOf')::timestamptz IS DISTINCT FROM (local_registry->>'as_of')::timestamptz
  THEN RAISE EXCEPTION 'Recipient local receipt unavailable' USING ERRCODE='HDN06';END IF;
  EXECUTE 'select to_jsonb(p) from helpdesk_auth.cg_local_permissions p where workspace_id=$1 and account_id=$2 and principal_id=$3 and operation=$4 for share' INTO local_permission USING w,a,person,recipient_operation;
  IF local_permission IS NOT NULL AND local_permission->'active'='false'::jsonb THEN RAISE EXCEPTION 'Recipient local permission revoked' USING ERRCODE='HDN04';END IF;
  IF local_permission IS NULL OR local_permission->'active' IS DISTINCT FROM 'true'::jsonb OR local_permission->'registry_revision' IS DISTINCT FROM local_registry->'revision' OR jsonb_typeof(local_permission->'work_ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Recipient local permission unavailable' USING ERRCODE='HDN06';END IF;
  FOR ref IN SELECT resource_type,resource_id FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,target) ORDER BY resource_type,resource_id FOR SHARE LOOP
   IF ref.resource_type<>'work' OR NOT local_permission->'work_ids' @> jsonb_build_array(ref.resource_id) THEN RAISE EXCEPTION 'Recipient local work permission revoked' USING ERRCODE='HDN04';END IF;
   EXECUTE 'select to_jsonb(x) from helpdesk_auth.cg_local_works x where workspace_id=$1 and account_id=$2 and id=$3 for share' INTO local_work USING w,a,ref.resource_id;
   IF local_work IS NOT NULL AND local_work->'active'='false'::jsonb THEN RAISE EXCEPTION 'Recipient local work revoked' USING ERRCODE='HDN04';END IF;
   IF local_work IS NULL OR local_work->'active' IS DISTINCT FROM 'true'::jsonb OR local_work->'registry_revision' IS DISTINCT FROM local_registry->'revision' THEN RAISE EXCEPTION 'Recipient local work unavailable' USING ERRCODE='HDN06';END IF;
  END LOOP;
  -- This is a new observation of the current immutable local decision, not an
  -- extension of an old CG envelope. Save(sending) repeats all checks and locks.
  until:=least(helpdesk_auth.hdn_notification_stamp(i->>'expiresAt'),clock_timestamp()+interval '30 seconds');revision:='local-'||(local_registry->>'revision');
 ELSE
  SELECT * INTO STRICT g FROM helpdesk_auth.cg_resource_grant_sets WHERE (workspace_id,account_id,binding_id,principal_id,operation)=(w,a,b.id,person,recipient_operation) FOR SHARE;IF NOT g.active THEN RAISE EXCEPTION 'Recipient resource grant revoked' USING ERRCODE='HDN04';END IF;
  IF g.source_revision LIKE 'local:%' THEN RAISE EXCEPTION 'Recipient local source unavailable' USING ERRCODE='HDN06';END IF;
  SELECT * INTO STRICT o FROM helpdesk_auth.cg_resource_observations WHERE (workspace_id,account_id,binding_id,principal_id,operation,grant_revision)=(w,a,b.id,person,recipient_operation,g.revision) FOR SHARE;
  IF g.as_of>clock_timestamp() OR g.expires_at<=clock_timestamp() OR o.access_revision<>g.source_revision OR o.as_of<>g.as_of OR o.expires_at<>g.expires_at OR o.expected_count<>g.expected_count
  THEN RAISE EXCEPTION 'Recipient observation unavailable' USING ERRCODE='HDN06';END IF;
  IF (SELECT count(*) FROM helpdesk_auth.cg_resource_grant_refs x WHERE (x.workspace_id,x.account_id,x.binding_id,x.principal_id,x.operation)=(w,a,b.id,person,recipient_operation))<>g.expected_count THEN RAISE EXCEPTION 'Recipient grant coverage unavailable' USING ERRCODE='HDN06';END IF;
  IF EXISTS(SELECT 1 FROM helpdesk_core.cg_ticket_resource_refs x WHERE (x.workspace_id,x.account_id,x.ticket_id)=(w,a,target) AND NOT EXISTS(SELECT 1 FROM helpdesk_auth.cg_resource_grant_refs y WHERE (y.workspace_id,y.account_id,y.binding_id,y.principal_id,y.operation,y.resource_type,y.resource_id)=(w,a,b.id,person,recipient_operation,x.resource_type,x.resource_id))) THEN RAISE EXCEPTION 'Recipient resources revoked' USING ERRCODE='HDN04';END IF;
  until:=least(g.expires_at,helpdesk_auth.hdn_notification_stamp(i->>'expiresAt'),clock_timestamp()+interval '30 seconds');revision:='grant-'||g.revision::text;
 END IF;
 -- Dynamic query is fixed here solely so fresh test DBs can provision synthetic
 -- auth.users independently. Identifier and recipient parameter are fixed.
 EXECUTE 'select email,email_confirmed_at from auth.users where id=$1 and email_confirmed_at is not null and deleted_at is null and (banned_until is null or banned_until<=clock_timestamp()) for share' INTO address,verified_at USING p.supabase_user_id;
 IF address IS NULL OR verified_at>clock_timestamp() OR length(address)>254 OR address !~ '^[A-Za-z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Za-z0-9][A-Za-z0-9.-]*\.[A-Za-z]{2,63}$' THEN RAISE EXCEPTION 'Verified recipient contact required' USING ERRCODE='HDN06';END IF;
 RETURN jsonb_build_object('intentId',i->'id','workspaceId',i->'workspaceId','accountId',i->'accountId','recipientId',i->'recipientId','channelId','resend','resourceHash',i->'resourceHash','revision',revision,'decision','allowed','address',address,'expiresAt',helpdesk_auth.hdn_workflow_iso(until));
EXCEPTION WHEN no_data_found OR data_exception THEN RAISE EXCEPTION 'Recipient unavailable' USING ERRCODE='HDN06';END$$;

CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_write_plan(target uuid,p jsonb,intents jsonb) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE facts jsonb;src jsonb;r jsonb;expected jsonb;i jsonb;ids jsonb:='[]';row jsonb;recipient jsonb;n integer;affected integer;BEGIN PERFORM helpdesk_auth.hdn_notification_worker();facts:=helpdesk_auth.hdn_notification_facts(target);src:=facts->'source';r:=helpdesk_auth.hdn_notification_routing(target);
 IF jsonb_typeof(intents)<>'array' OR jsonb_array_length(intents)>100 OR jsonb_array_length(intents)<>jsonb_array_length(r->'recipients') OR EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_plans WHERE event_id=target) THEN RAISE EXCEPTION 'Plan conflict' USING ERRCODE='HDN05';END IF;
 FOR i IN SELECT value FROM jsonb_array_elements(intents) LOOP
  IF NOT helpdesk_auth.hdn_notification_valid_intent(i) OR i->>'eventId'<>target::text OR i->'workspaceId'<>src->'workspaceId' OR i->'accountId'<>src->'accountId' OR i->'ticketId'<>src->'ticketId' OR i->'kind'<>src->'type' OR i->'sourceVersion'<>src->'version' OR i->'resourceHash'<>r->'resourceHash' OR i->'protocol'<>r->'protocol' OR i->'expiresAt'<>r->'expiresAt' OR i->'createdAt'<>p->'plannedAt' OR i->'invitationId' IS DISTINCT FROM coalesce(src->'invitationId','null'::jsonb) THEN RAISE EXCEPTION 'Intent mismatch' USING ERRCODE='HDN05';END IF;
  recipient:=jsonb_build_object('principalId',i->'recipientId','channelId',i->'channelId','templateId',i->'templateId','templateVersion',i->'templateVersion','templateHash',i->'templateHash');IF NOT r->'recipients' @> jsonb_build_array(recipient) OR ids @> jsonb_build_array(i->'id') THEN RAISE EXCEPTION 'Recipient mismatch' USING ERRCODE='HDN05';END IF;ids:=ids||jsonb_build_array(i->'id');
 END LOOP;
 expected:=jsonb_build_object('schema',1,'eventId',target,'sourceHash',helpdesk_auth.hdni_digest(src),'sourceVersion',src->'version','routingRevision',r->'revision','plannedAt',p->'plannedAt','state',CASE WHEN jsonb_array_length(intents)=0 THEN 'no_recipients' ELSE 'planned' END,'intentIds',ids);
 IF p IS DISTINCT FROM expected OR helpdesk_auth.hdn_notification_stamp(p->>'plannedAt')<helpdesk_auth.hdn_notification_stamp(src->>'createdAt') OR helpdesk_auth.hdn_notification_stamp(p->>'plannedAt')>clock_timestamp() THEN RAISE EXCEPTION 'Plan mismatch' USING ERRCODE='HDN05';END IF;
 INSERT INTO helpdesk_integration.hdn_notification_plans VALUES(target,(src->>'workspaceId')::uuid,(src->>'accountId')::uuid,(src->>'ticketId')::uuid,p);GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Plan effect missing' USING ERRCODE='HDN05';END IF;
 FOR i IN SELECT value FROM jsonb_array_elements(intents) LOOP
  row:=jsonb_build_object('intent',i,'revision',1,'state','pending','attempts',0,'lease',NULL,'requestHash',NULL,'providerMessageId',NULL,'providerSequence',0,'providerEventAt',NULL,'nextAttemptAt',NULL,'lastReason',NULL,'attention',false,'updatedAt',p->'plannedAt');
  INSERT INTO helpdesk_integration.hdn_notification_records VALUES((i->>'id')::uuid,(i->>'workspaceId')::uuid,(i->>'accountId')::uuid,(i->>'ticketId')::uuid,target,(i->>'recipientId')::uuid,'resend',i,row);GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'Intent effect missing' USING ERRCODE='HDN05';END IF;
  IF NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_records WHERE id=(i->>'id')::uuid AND intent=i AND record=row) THEN RAISE EXCEPTION 'Intent effect altered' USING ERRCODE='HDN05';END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM helpdesk_integration.hdn_notification_plans WHERE event_id=target AND document=p) THEN RAISE EXCEPTION 'Plan effect altered' USING ERRCODE='HDN05';END IF;RETURN true;
END$$;

DO $private$ DECLARE role_name text;BEGIN
 REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_facts(uuid),helpdesk_auth.hdn_notification_approver(uuid,uuid) FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdn_notification_facts(uuid),helpdesk_auth.hdn_notification_approver(uuid,uuid) FROM %I',role_name);END IF;
 END LOOP;
END $private$;


-- SOURCE hdn_review_portal.sql SHA256 f6d1320ba138030b5235b8778f4179d7e7436ed355c586e938426a1c5819326f
CREATE FUNCTION helpdesk_auth.hdnr_view_capability(target uuid,cap text,ctx jsonb) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 PERFORM helpdesk_auth.hdnr_grant(target,cap,ctx);RETURN true;
EXCEPTION WHEN SQLSTATE 'HDR01' OR SQLSTATE 'HDR05' THEN RETURN false;END$$;

-- Authenticated read only. Never returns or generates a challenge, applies a
-- decision, consumes a draft, or changes an invitation. Initial CG cohort uses
-- current tickets.write scope for review; ordinary ticket reads stay separate.
CREATE FUNCTION helpdesk_auth.hdnr_view(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE w uuid:=helpdesk_auth.workspace_id();who uuid:=helpdesk_auth.actor_id();ctx jsonb;a jsonb;ticket jsonb;definition jsonb;fields jsonb;invite helpdesk_core.hdnr_invitations%rowtype;
 decision_row helpdesk_audit.hdnr_receipts%rowtype;invitation_id uuid;request_allowed boolean;decide_allowed boolean;revise_allowed boolean;last_decision jsonb:='null';BEGIN
 ctx:=helpdesk_auth.hdnr_context(target);
 IF NOT EXISTS(SELECT 1 FROM helpdesk_core.hdni_snapshots s JOIN helpdesk_core.hdnr_profiles p ON(p.workspace_id,p.account_id,p.profile_version_id)=(s.workspace_id,s.account_id,s.document->'profile'->>'profileVersionId') WHERE(s.workspace_id,s.ticket_id)=(w,target)) THEN RETURN NULL;END IF;
 a:=helpdesk_auth.hdnr_aggregate(target)->'aggregate';ticket:=a->'ticket';
 SELECT jsonb_agg(field ORDER BY ordinal) INTO fields FROM jsonb_array_elements(a->'profile'->'form'->'fields') WITH ORDINALITY x(field,ordinal) WHERE field->'public'='true'::jsonb;
 definition:=a->'profile'->'form'||jsonb_build_object('fields',coalesce(fields,'[]'::jsonb));
 request_allowed:=helpdesk_auth.hdnr_view_capability(target,'approvals.request',ctx);decide_allowed:=helpdesk_auth.hdnr_view_capability(target,'approvals.decide',ctx);revise_allowed:=helpdesk_auth.hdnr_view_capability(target,'forms.revise',ctx);
 SELECT * INTO invite FROM helpdesk_core.hdnr_invitations WHERE(workspace_id,account_id,ticket_id)=(w,(ticket->>'accountId')::uuid,target) AND document->>'status'='pending' ORDER BY id LIMIT 1;
 request_allowed:=request_allowed AND invite.id IS NULL AND ticket->>'status' IN ('new','triage') AND ticket->>'approval'='pending' AND a->'profile'->'approvalRequired'='true'::jsonb;
 decide_allowed:=decide_allowed AND invite.id IS NOT NULL AND invite.document->>'approverId'=who::text AND helpdesk_auth.hdn_notification_stamp(invite.document->>'expiresAt')>clock_timestamp() AND invite.document->'ticketVersion'=ticket->'version' AND invite.document->'formRevision'=a->'form'->'revision' AND invite.document->>'targetHash'=helpdesk_auth.hdnr_target_hash(a) AND ticket->>'status' IN ('new','triage') AND ticket->>'approval'='pending';
 IF coalesce(decide_allowed,false) THEN invitation_id:=invite.id;END IF;
 revise_allowed:=revise_allowed AND ticket->>'status'='waiting_customer';
 -- Decision justification is part of this explicit customer-facing review
 -- command, never a general private note. Only the pinned new CG review profile
 -- and this currently authorized ticket projection may disclose it.
 SELECT * INTO decision_row FROM helpdesk_audit.hdnr_receipts WHERE(workspace_id,account_id,ticket_id,action)=(w,(ticket->>'accountId')::uuid,target,'approval') ORDER BY(result->>'version')::integer DESC LIMIT 1;
 IF FOUND THEN last_decision:=jsonb_build_object('decision',decision_row.result->'decision','version',decision_row.result->'version','formRevision',decision_row.result->'formRevision','at',decision_row.bundle->'audit'->'at','reason',decision_row.bundle->'decision'->'reason');END IF;
 RETURN jsonb_build_object('schema',1,'context',jsonb_build_object('principalId',who,'workspaceId',w,'accountId',ticket->'accountId','ticketId',target,'version',ticket->'version','formRevision',a->'form'->'revision','invitationId',invitation_id),'protocol',a->'protocol','status',ticket->'status','approval',ticket->'approval',
  'form',jsonb_build_object('definition',definition,'formId',a->'form'->'formId','formVersion',a->'form'->'formVersion','schemaHash',a->'form'->'schemaHash','answers',a->'form'->'publicAnswers','refs',a->'refs'),
  'capabilities',jsonb_build_object('requestApproval',coalesce(request_allowed,false),'decideApproval',coalesce(decide_allowed,false),'reviseForm',coalesce(revise_allowed,false)),'decision',last_decision);
END$$;

CREATE FUNCTION helpdesk_auth.hdnr_landing(invitation uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE row helpdesk_core.hdnr_invitations%rowtype;a jsonb;ctx jsonb;BEGIN
 IF session_user<>'helpdesk_app' OR NOT coalesce(helpdesk_auth.is_human(),false) THEN RAISE EXCEPTION 'Human invitation navigation required' USING ERRCODE='HDR01';END IF;
 SELECT * INTO row FROM helpdesk_core.hdnr_invitations WHERE(workspace_id,id)=(helpdesk_auth.workspace_id(),invitation);
 IF NOT FOUND OR row.document->>'approverId' IS DISTINCT FROM helpdesk_auth.actor_id()::text THEN RAISE EXCEPTION 'Invitation navigation denied' USING ERRCODE='HDR01';END IF;
 ctx:=helpdesk_auth.hdnr_context(row.ticket_id);PERFORM helpdesk_auth.hdnr_grant(row.ticket_id,'approvals.decide',ctx);a:=helpdesk_auth.hdnr_aggregate(row.ticket_id)->'aggregate';
 SELECT * INTO STRICT row FROM helpdesk_core.hdnr_invitations WHERE(workspace_id,id)=(helpdesk_auth.workspace_id(),invitation) FOR SHARE;
 IF row.document->>'status'<>'pending' OR helpdesk_auth.hdn_notification_stamp(row.document->>'expiresAt')<=clock_timestamp() OR row.document->'ticketVersion' IS DISTINCT FROM a->'ticket'->'version' OR row.document->'formRevision' IS DISTINCT FROM a->'form'->'revision' OR row.document->>'targetHash' IS DISTINCT FROM helpdesk_auth.hdnr_target_hash(a) OR row.document->'policyVersionId' IS DISTINCT FROM a->'approvalPolicy'->'versionId' OR a->'ticket'->>'approval'<>'pending' OR a->'ticket'->>'status' NOT IN ('new','triage') THEN RAISE EXCEPTION 'Invitation target changed' USING ERRCODE='HDR02';END IF;
 RETURN jsonb_build_object('workspaceId',row.workspace_id,'ticketId',row.ticket_id,'invitationId',row.id);
END$$;

-- Operational alert 30 uses the panel, independent of the failing SMTP channel.
-- No provider call, resend, notification producer, contact or raw provider data.
CREATE FUNCTION helpdesk_auth.hdn_notification_attention(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE ctx jsonb;w uuid:=helpdesk_auth.workspace_id();who uuid:=helpdesk_auth.actor_id();a uuid;rows jsonb;BEGIN
 ctx:=helpdesk_auth.hdnr_context(target);a:=(ctx->>'accountId')::uuid;
 PERFORM 1 FROM helpdesk_auth.workspace_memberships WHERE(workspace_id,principal_id,role,active)=(w,who,'admin',true) FOR SHARE;
 IF NOT FOUND OR NOT helpdesk_auth.hdnr_operator(w,a,target,who) THEN RAISE EXCEPTION 'Current delivery operations authority required' USING ERRCODE='HDR01';END IF;
 SELECT coalesce(jsonb_agg(item ORDER BY updated_at DESC,id),'[]'::jsonb) INTO rows FROM(
  SELECT id,helpdesk_auth.hdn_notification_stamp(record->>'updatedAt') updated_at,jsonb_build_object('id',id,'kind',intent->'kind','state',record->'state','attempts',record->'attempts','attention',record->'attention','updatedAt',record->'updatedAt','nextAttemptAt',record->'nextAttemptAt','reason',record->'lastReason') item
  FROM helpdesk_integration.hdn_notification_records WHERE(workspace_id,account_id,ticket_id)=(w,a,target) ORDER BY helpdesk_auth.hdn_notification_stamp(record->>'updatedAt') DESC,id LIMIT 20) recent;
 RETURN jsonb_build_object('ticketId',target,'workspaceId',w,'accountId',a,'items',rows,'limit',20,'resendAvailable',false);
END$$;
DO $private$ DECLARE role_name text;BEGIN
 REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_view_capability(uuid,text,jsonb),helpdesk_auth.hdnr_view(uuid),helpdesk_auth.hdnr_landing(uuid),helpdesk_auth.hdn_notification_attention(uuid) FROM PUBLIC;
 FOREACH role_name IN ARRAY ARRAY['helpdesk_app','helpdesk_notification_worker','helpdesk_resource_publisher','helpdesk_maintenance','anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION helpdesk_auth.hdnr_view_capability(uuid,text,jsonb),helpdesk_auth.hdnr_view(uuid),helpdesk_auth.hdnr_landing(uuid),helpdesk_auth.hdn_notification_attention(uuid) FROM %I',role_name);END IF;
 END LOOP;
 GRANT EXECUTE ON FUNCTION helpdesk_auth.hdnr_view(uuid),helpdesk_auth.hdnr_landing(uuid),helpdesk_auth.hdn_notification_attention(uuid) TO helpdesk_app;
END $private$;


-- SOURCE hdn_notification_wave2_expiry.sql SHA256 081df7e573532de2eff6e369f8ef36b33580de5f2d020d76378c574abdfae341
-- Expired finite authority seals an empty plan; it cannot stall the shared queue.
CREATE OR REPLACE FUNCTION helpdesk_auth.hdn_notification_routing(target uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE facts jsonb;src jsonb;route helpdesk_integration.hdn_notification_routes%rowtype;t helpdesk_integration.hdn_notification_templates%rowtype;
 roster helpdesk_integration.hdn_notification_queue_rosters%rowtype;people uuid[]:='{}';person uuid;recipients jsonb:='[]';BEGIN
 PERFORM helpdesk_auth.hdn_notification_worker();facts:=helpdesk_auth.hdn_notification_facts(target);src:=facts->'source';
 SELECT * INTO STRICT route FROM helpdesk_integration.hdn_notification_routes WHERE workspace_id=(src->>'workspaceId')::uuid AND kind=src->>'type' ORDER BY revision DESC LIMIT 1 FOR SHARE;

 IF route.expires_at>clock_timestamp() AND route.audience<>'none' AND facts->'wave2Eligible'='true'::jsonb AND (route.effective_after IS NULL OR helpdesk_auth.hdn_notification_stamp(src->>'createdAt')>=route.effective_after) THEN
  SELECT * INTO STRICT t FROM helpdesk_integration.hdn_notification_templates WHERE id=route.template_id AND version=route.template_version FOR SHARE;
  IF t.kind<>route.kind THEN RAISE EXCEPTION 'Template kind mismatch' USING ERRCODE='HDN05';END IF;
  IF route.audience='requester' THEN people:=ARRAY[(facts->>'requesterId')::uuid];
  ELSIF route.audience='approver' THEN people:=ARRAY[(facts->>'sourceApproverId')::uuid];
  ELSIF route.audience IN ('assignee','customer_return') AND facts->>'sourceAssigneeId' IS NOT NULL THEN people:=ARRAY[(facts->>'sourceAssigneeId')::uuid];
  ELSIF route.audience IN ('queue','customer_return') THEN
   SELECT * INTO STRICT roster FROM helpdesk_integration.hdn_notification_queue_rosters WHERE workspace_id=(src->>'workspaceId')::uuid AND account_id=(src->>'accountId')::uuid ORDER BY revision DESC LIMIT 1 FOR SHARE;
   IF roster.expires_at>clock_timestamp() THEN people:=roster.member_ids;END IF;
  ELSE RAISE EXCEPTION 'Audience not yet qualified' USING ERRCODE='HDN05';END IF;
  FOREACH person IN ARRAY people LOOP
   IF (route.recipient_ids IS NULL OR person=ANY(route.recipient_ids)) AND (route.audience='requester' OR route.audience='approver' AND helpdesk_auth.hdn_notification_approver(target,person) OR route.audience IN ('queue','assignee','customer_return') AND helpdesk_auth.hdn_notification_internal_person(target,person)) THEN
    recipients:=recipients||jsonb_build_array(jsonb_build_object('principalId',person,'channelId','resend','templateId',t.id,'templateVersion',t.version,'templateHash',t.sha256));
   END IF;
  END LOOP;
 END IF;
 RETURN jsonb_build_object('eventId',target,'workspaceId',src->'workspaceId','accountId',src->'accountId','ticketId',src->'ticketId','sourceVersion',src->'version','kind',src->'type','protocol',facts->'protocol','resourceHash',facts->'resourceHash','revision','route-'||route.revision::text,'status','published','expiresAt',helpdesk_auth.hdn_workflow_iso(route.expires_at),'recipients',recipients);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Published routing required' USING ERRCODE='HDN05';END$$;



-- WAVE2 FINAL CATALOGUE
DO $wave2_final_catalogue$ DECLARE checked record;BEGIN
 IF NOT (EXISTS(SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname='helpdesk_app'
 AND NOT(r.rolsuper OR r.rolbypassrls OR r.rolcreaterole OR r.rolcreatedb OR r.rolreplication)
 AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members m WHERE m.member=r.oid)
 AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE c.relowner=r.oid AND n.nspname LIKE 'helpdesk_%')
 AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_namespace n WHERE n.nspowner=r.oid AND n.nspname LIKE 'helpdesk_%')
 AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE p.proowner=r.oid AND n.nspname LIKE 'helpdesk_%'))) THEN RAISE EXCEPTION 'Restricted application identity required' USING ERRCODE='HDE06';END IF;
 SELECT * INTO checked FROM (with
